let Print_listReverseAndMapAndIntersperseAndFlatten (elementToPrint: 'a -> Print_Print) (inBetweenPrint: Print_Print) (elements: List<'a>) : Print_Print =
    match elements with
    | [] ->
        Print_empty

    | head :: tail ->
        List_foldl
            (fun (next: 'a) (soFar: Print_Print) ->
                Print_followedBy soFar (Print_followedBy inBetweenPrint (elementToPrint next))
            )
            (elementToPrint head)
            tail

