let ParserLenient_skipFloatAfterIntegerDecimal (offset: int64) (src: StringRope) : int64 =
    match String_slice offset ((+) offset 1L) src with
    | StringRopeOne(".") ->
        let offsetAfterDigits: int64 =
            ParserLenient_skip1OrMoreDigits0To9 ((+) offset 1L) src
        
        if Basics_eq offsetAfterDigits -1L then
