        else
            match String_slice offsetAfterDigits ((+) offsetAfterDigits 1L) src with
            | StringRopeOne("e") ->
                ParserLenient_skipAfterFloatExponentMark ((+) offsetAfterDigits 1L) src

            | StringRopeOne("E") ->
                ParserLenient_skipAfterFloatExponentMark ((+) offsetAfterDigits 1L) src

            | _ ->
                offsetAfterDigits

    | StringRopeOne("e") ->
        ParserLenient_skipAfterFloatExponentMark ((+) offset 1L) src

    | StringRopeOne("E") ->
        ParserLenient_skipAfterFloatExponentMark ((+) offset 1L) src

    | _ ->
        -1L

let ParserLenient_run (ParserLenient_Parser(parse): ParserLenient_Parser<'a>) (src: StringRope) : ValueOption<'a> =
    match
        parse
            { Col = 1L
            ; Indent = []
            ; Offset = 0L
            ; Row = 1L
            ; Src = src
            }
    with
    | ParserLenient_Good(value, finalState) ->
        if Basics_eq ((-) finalState.Offset (String_length finalState.Src)) 0L then
            ValueSome value

        else
            ValueNone

    | ParserLenient_Bad(_, _) ->
        ValueNone

