let ParserLenient_whileAtMost3WithoutLinebreakAnd2PartUtf16ToResultAndThen (charAsStringIsOkay: StringRope -> bool) (consumedStringToIntermediateOrErr: StringRope -> ValueOption<'intermediate>) (intermediateToFollowupParser: 'intermediate -> ParserLenient_Parser<'res>) : ParserLenient_Parser<'res> =
    ParserLenient_Parser
        (fun (s0: Generated_Col_Indent_Offset_Row_Src<int64, List<int64>, int64, int64, StringRope>) ->
