                s0.Offset
            
            let consumed: Generated_Length_String<int64, StringRope> =
                if charAsStringIsOkay (String_slice s0Offset ((+) s0Offset 1L) src) then
                    if charAsStringIsOkay (String_slice ((+) s0Offset 1L) ((+) s0Offset 2L) src) then
                        if charAsStringIsOkay (String_slice ((+) s0Offset 2L) ((+) s0Offset 3L) src) then
                            { Length = 3L
                            ; String = String_slice s0Offset ((+) s0Offset 3L) src
                            }

                        else
                            { Length = 2L
                            ; String = String_slice s0Offset ((+) s0Offset 2L) src
                            }

                    else
                        { Length = 1L
                        ; String = String_slice s0Offset ((+) s0Offset 1L) src
                        }

                else
                    ParserLenient_length0StringEmpty
            
            match consumedStringToIntermediateOrErr consumed.String with
            | ValueSome(intermediate) ->
                let (ParserLenient_Parser(parseFollowup): ParserLenient_Parser<'res>) =
                    intermediateToFollowupParser intermediate
                
                ParserLenient_pStepCommit
                    (parseFollowup
                        { Col = (+) s0.Col consumed.Length
                        ; Indent = s0.Indent
                        ; Offset = (+) s0Offset consumed.Length
                        ; Row = s0.Row
                        ; Src = src
                        }
