let ParserLenient_convertIntegerDecimalOrHexadecimal (offset: int64) (src: StringRope) : Generated_Base_OffsetAndInt<ParserLenient_Base, Generated_Int_Offset<int64, int64>> =
    match String_slice offset ((+) offset 1L) src with
    | StringRopeOne("0") ->
        match String_slice ((+) offset 1L) ((+) offset 2L) src with
        | StringRopeOne("x") ->
            let hex: Generated_Int_Offset<int64, int64> =
                ParserLenient_convert1OrMoreHexadecimal ((+) offset 2L) src
            
            { Base = ParserLenient_Hexadecimal
            ; OffsetAndInt =
                { Int = hex.Int
                ; Offset = hex.Offset
                }
            }

        | _ ->
            { Base = ParserLenient_Decimal
            ; OffsetAndInt =
                { Int = 0L
                ; Offset = (+) offset 1L
                }
            }

    | StringRopeOne("1") ->
        { Base = ParserLenient_Decimal
        ; OffsetAndInt = ParserLenient_convert0OrMore0To9s 1L ((+) offset 1L) src
        }

    | StringRopeOne("2") ->
        { Base = ParserLenient_Decimal
        ; OffsetAndInt = ParserLenient_convert0OrMore0To9s 2L ((+) offset 1L) src
        }

    | StringRopeOne("3") ->
        { Base = ParserLenient_Decimal
        ; OffsetAndInt = ParserLenient_convert0OrMore0To9s 3L ((+) offset 1L) src
        }

    | StringRopeOne("4") ->
        { Base = ParserLenient_Decimal
        ; OffsetAndInt = ParserLenient_convert0OrMore0To9s 4L ((+) offset 1L) src
        }

    | StringRopeOne("5") ->
        { Base = ParserLenient_Decimal
        ; OffsetAndInt = ParserLenient_convert0OrMore0To9s 5L ((+) offset 1L) src
        }

    | StringRopeOne("6") ->
        { Base = ParserLenient_Decimal
        ; OffsetAndInt = ParserLenient_convert0OrMore0To9s 6L ((+) offset 1L) src
        }

    | StringRopeOne("7") ->
        { Base = ParserLenient_Decimal
        ; OffsetAndInt = ParserLenient_convert0OrMore0To9s 7L ((+) offset 1L) src
        }

    | StringRopeOne("8") ->
        { Base = ParserLenient_Decimal
        ; OffsetAndInt = ParserLenient_convert0OrMore0To9s 8L ((+) offset 1L) src
        }

    | StringRopeOne("9") ->
        { Base = ParserLenient_Decimal
        ; OffsetAndInt = ParserLenient_convert0OrMore0To9s 9L ((+) offset 1L) src
        }

    | _ ->
        ParserLenient_errorAsBaseOffsetAndInt

let ParserLenient_floatOrIntegerDecimalOrHexadecimalMapWithRange (rangeAndFloatToRes: Generated_End_Start<Generated_Column_Row<int64, int64>, Generated_Column_Row<int64, int64>> -> float -> 'res) (rangeAndIntDecimalToRes: ElmSyntaxRange_Range -> int64 -> 'res) (rangeAndIntHexadecimalToRes: ElmSyntaxRange_Range -> int64 -> 'res) : ParserLenient_Parser<'res> =
    ParserLenient_Parser
        (fun (s0: Generated_Col_Indent_Offset_Row_Src<int64, List<int64>, int64, int64, StringRope>) ->
            let s1: Generated_Base_OffsetAndInt<ParserLenient_Base, Generated_Int_Offset<int64, int64>> =
                ParserLenient_convertIntegerDecimalOrHexadecimal s0.Offset s0.Src
            
            if Basics_eq s1.OffsetAndInt.Offset -1L then
                ParserLenient_pStepBadBacktracking

            else
                let offsetAfterFloat: int64 =
                    ParserLenient_skipFloatAfterIntegerDecimal s1.OffsetAndInt.Offset s0.Src
                
                if Basics_eq offsetAfterFloat -1L then
                    let newColumn: int64 =
                        (+) s0.Col ((-) s1.OffsetAndInt.Offset s0.Offset)
                    
                    let range: ElmSyntaxRange_Range =
                        { End =
                            { Column = newColumn
                            ; Row = s0.Row
                            }
                        ; Start =
                            { Column = s0.Col
                            ; Row = s0.Row
                            }
                        }
                    
                    ParserLenient_Good
                        (struct(
                          match s1.Base with
                          | ParserLenient_Decimal ->
                            rangeAndIntDecimalToRes range s1.OffsetAndInt.Int

                          | ParserLenient_Hexadecimal ->
                            rangeAndIntHexadecimalToRes range s1.OffsetAndInt.Int
                        , { Col = newColumn
                          ; Indent = s0.Indent
                          ; Offset = s1.OffsetAndInt.Offset
                          ; Row = s0.Row
                          ; Src = s0.Src
                          }
                        ))

                else
                    match String_toFloat (String_slice s0.Offset offsetAfterFloat s0.Src) with
                    | ValueSome(float_) ->
                        let newColumn: int64 =
                            (+) s0.Col ((-) offsetAfterFloat s0.Offset)
                        
                        ParserLenient_Good
                            (struct(
                              rangeAndFloatToRes
                                { End =
                                    { Column = newColumn
                                    ; Row = s0.Row
                                    }
                                ; Start =
                                    { Column = s0.Col
                                    ; Row = s0.Row
                                    }
                                }
                                float_
                            , { Col = newColumn
                              ; Indent = s0.Indent
                              ; Offset = offsetAfterFloat
                              ; Row = s0.Row
                              ; Src = s0.Src
                              }
                            ))

                    | ValueNone ->
                        ParserLenient_pStepBadBacktracking
        )

