                      ; Src = s.Src
                      }
                    ))

            else
                ParserFast_Bad (struct( false, ParserFast_ExpectingSymbol (struct( s.Row, s.Col, str )) ))
        )

let rec ParserFast_skipWhileWithoutLinebreakAnd2PartUtf16Help (isGood: int -> bool) (offset: int64) (src: StringRope) : int64 =
    if String_any isGood (String_slice offset ((+) offset 1L) src) then
        ParserFast_skipWhileWithoutLinebreakAnd2PartUtf16Help isGood ((+) offset 1L) src

    else
        offset

let ParserFast_whileWithoutLinebreakAnd2PartUtf16ValidateMapWithRangeBacktrackableFollowedBySymbol (whileRangeAndContentToRes: Generated_End_Start<Generated_Column_Row<int64, int64>, Generated_Column_Row<int64, int64>> -> StringRope -> 'res) (whileCharIsOkay: int -> bool) (whileResultIsOkay: StringRope -> bool) (mandatoryFinalSymbol: StringRope) : ParserFast_Parser<'res> =
    let mandatoryFinalSymbolLength: int64 =
        String_length mandatoryFinalSymbol
    
    ParserFast_Parser
        (fun (s0: Generated_Col_Indent_Offset_Row_Src<int64, int64, int64, int64, StringRope>) ->
            let s1Offset: int64 =
                ParserFast_skipWhileWithoutLinebreakAnd2PartUtf16Help whileCharIsOkay s0.Offset s0.Src
            
            let whileContent: StringRope =
                String_slice s0.Offset s1Offset s0.Src
            
            if Basics_and (Basics_eq (String_slice s1Offset ((+) s1Offset mandatoryFinalSymbolLength) s0.Src) mandatoryFinalSymbol) (whileResultIsOkay whileContent) then
                let s1Column: int64 =
                    (+) s0.Col ((-) s1Offset s0.Offset)
                
                ParserFast_Good
                    (struct(
                      whileRangeAndContentToRes
                        { End =
                            { Column = s1Column
                            ; Row = s0.Row
                            }
                        ; Start =
                            { Column = s0.Col
                            ; Row = s0.Row
                            }
                        }
                        whileContent
                    , { Col = (+) s1Column mandatoryFinalSymbolLength
                      ; Indent = s0.Indent
                      ; Offset = (+) s1Offset mandatoryFinalSymbolLength
                      ; Row = s0.Row
                      ; Src = s0.Src
                      }
                    ))

            else
                ParserFast_Bad (struct( false, ParserFast_ExpectingStringSatisfyingPredicate (struct( s0.Row, (+) s0.Col 1L )) ))
        )

let rec ParserFast_skipWhileWhitespaceHelp (offset: int64) (row: int64) (col: int64) (src: StringRope) (indent: int64) : ParserFast_State =
    match String_slice offset ((+) offset 1L) src with
    | StringRopeOne(" ") ->
        ParserFast_skipWhileWhitespaceHelp ((+) offset 1L) row ((+) col 1L) src indent

    | StringRopeOne("\n") ->
        ParserFast_skipWhileWhitespaceHelp ((+) offset 1L) ((+) row 1L) 1L src indent

    | StringRopeOne("\r") ->
        ParserFast_skipWhileWhitespaceHelp ((+) offset 1L) row ((+) col 1L) src indent

    | _ ->
        { Col = col
        ; Indent = indent
        ; Offset = offset
        ; Row = row
        ; Src = src
        }

let rec ParserFast_skip0OrMoreDigits0To9 (offset: int64) (src: StringRope) : int64 =
    match String_slice offset ((+) offset 1L) src with
    | StringRopeOne("0") ->
