    | StringRopeOne("7") ->
        ParserFast_skip0OrMoreDigits0To9 ((+) offset 1L) src

    | StringRopeOne("8") ->
        ParserFast_skip0OrMoreDigits0To9 ((+) offset 1L) src

    | StringRopeOne("9") ->
        ParserFast_skip0OrMoreDigits0To9 ((+) offset 1L) src

    | _ ->
        offset

let ParserFast_skip1OrMoreDigits0To9 (offset: int64) (src: StringRope) : int64 =
    match String_slice offset ((+) offset 1L) src with
    | StringRopeOne("0") ->
        ParserFast_skip0OrMoreDigits0To9 ((+) offset 1L) src

    | StringRopeOne("1") ->
