let ParserFast_skipAfterFloatExponentMark (offset: int64) (src: StringRope) : int64 =
    match String_slice offset ((+) offset 1L) src with
    | StringRopeOne("+") ->
        ParserFast_skip1OrMoreDigits0To9 ((+) offset 1L) src

    | StringRopeOne("-") ->
        ParserFast_skip1OrMoreDigits0To9 ((+) offset 1L) src

    | _ ->
        ParserFast_skip1OrMoreDigits0To9 offset src

let ParserFast_skipFloatAfterIntegerDecimal (offset: int64) (src: StringRope) : int64 =
    match String_slice offset ((+) offset 1L) src with
    | StringRopeOne(".") ->
        let offsetAfterDigits: int64 =
            ParserFast_skip1OrMoreDigits0To9 ((+) offset 1L) src
        
        if Basics_eq offsetAfterDigits -1L then
            -1L

        else
            match String_slice offsetAfterDigits ((+) offsetAfterDigits 1L) src with
            | StringRopeOne("e") ->
                ParserFast_skipAfterFloatExponentMark ((+) offsetAfterDigits 1L) src

            | StringRopeOne("E") ->
                ParserFast_skipAfterFloatExponentMark ((+) offsetAfterDigits 1L) src

            | _ ->
                offsetAfterDigits

    | StringRopeOne("e") ->
        ParserFast_skipAfterFloatExponentMark ((+) offset 1L) src

    | StringRopeOne("E") ->
        ParserFast_skipAfterFloatExponentMark ((+) offset 1L) src

    | _ ->
        -1L

let rec ParserFast_ropeFilledToList (problemToConvert: ParserFast_Problem) (soFar: List<Parser_DeadEnd>) : List<Parser_DeadEnd> =
    match problemToConvert with
    | ParserFast_ExpectingOneOf(firstTry, secondTry, thirdTryUp) ->
        ParserFast_ropeFilledToList firstTry (ParserFast_ropeFilledToList secondTry (List_foldr ParserFast_ropeFilledToList soFar thirdTryUp))

    | ParserFast_ExpectingNumber(row, col) ->
        List_cons
            { Col = col
            ; Problem = Parser_ExpectingNumber
            ; Row = row
            }
            soFar

    | ParserFast_ExpectingSymbol(row, col, symbolString) ->
        List_cons
            { Col = col
            ; Problem = Parser_ExpectingSymbol symbolString
            ; Row = row
            }
            soFar

    | ParserFast_ExpectingAnyChar(row, col) ->
        List_cons
            { Col = col
            ; Problem = Parser_Problem (StringRopeOne "expecting any char")
            ; Row = row
            }
            soFar

    | ParserFast_ExpectingKeyword(row, col, keywordString) ->
        List_cons
            { Col = col
            ; Problem = Parser_ExpectingKeyword keywordString
            ; Row = row
            }
            soFar

    | ParserFast_ExpectingCharSatisfyingPredicate(row, col) ->
        List_cons
            { Col = col
            ; Problem = Parser_UnexpectedChar
            ; Row = row
            }
            soFar

    | ParserFast_ExpectingStringSatisfyingPredicate(row, col) ->
        List_cons
            { Col = col
            ; Problem = Parser_Problem (StringRopeOne "expected string to pass validation")
            ; Row = row
            }
            soFar

    | ParserFast_ExpectingCustom(row, col, customMessage) ->
        List_cons
            { Col = col
            ; Problem = Parser_Problem customMessage
            ; Row = row
            }
            soFar

let ParserFast_run (ParserFast_Parser(parse): ParserFast_Parser<'a>) (src: StringRope) : Result_Result<List<Generated_Col_Problem_Row<int64, Parser_Problem, int64>>, 'a> =
    match
        parse
            { Col = 1L
            ; Indent = 1L
            ; Offset = 0L
            ; Row = 1L
            ; Src = src
            }
    with
    | ParserFast_Good(value, finalState) ->
        if Basics_eq ((-) finalState.Offset (String_length finalState.Src)) 0L then
            Ok value

        else
            Error
                [ { Col = finalState.Col
                  ; Problem = Parser_ExpectingEnd
                  ; Row = finalState.Row
                  }
                ]

    | ParserFast_Bad(_, deadEnds) ->
        Error (ParserFast_ropeFilledToList deadEnds [])

let ParserFast_problem (msg: StringRope) : ParserFast_Parser<'a> =
    ParserFast_Parser
        (fun (s: Generated_Col_Indent_Offset_Row_Src<int64, int64, int64, int64, StringRope>) ->
            ParserFast_Bad (struct( false, ParserFast_ExpectingCustom (struct( s.Row, s.Col, msg )) ))
        )

let ParserFast_pStepCommit (pStep: ParserFast_PStep<'a>) : ParserFast_PStep<'a> =
    match pStep with
    | ParserFast_Good(_, _) as good ->
        good

    | ParserFast_Bad(_, x) ->
        ParserFast_Bad (struct( true, x ))

let ParserFast_skipWhileWhitespaceFollowedBy (ParserFast_Parser(parseNext): ParserFast_Parser<'next>) : ParserFast_Parser<'next> =
    ParserFast_Parser
        (fun (s0: Generated_Col_Indent_Offset_Row_Src<int64, int64, int64, int64, StringRope>) ->
            let s1: ParserFast_State =
                ParserFast_skipWhileWhitespaceHelp s0.Offset s0.Row s0.Col s0.Src s0.Indent
            
            ParserFast_pStepCommit (parseNext s1)
        )

let ParserFast_symbolFollowedBy (str: StringRope) (ParserFast_Parser(parseNext): ParserFast_Parser<'next>) : ParserFast_Parser<'next> =
    let strLength: int64 =
        String_length str
    
    ParserFast_Parser
        (fun (s: Generated_Col_Indent_Offset_Row_Src<int64, int64, int64, int64, StringRope>) ->
            let newOffset: int64 =
                (+) s.Offset strLength
            
            if Basics_eq (String_slice s.Offset newOffset s.Src) str then
                ParserFast_pStepCommit
                    (parseNext
                        { Col = (+) s.Col strLength
                        ; Indent = s.Indent
                        ; Offset = newOffset
                        ; Row = s.Row
                        ; Src = s.Src
                        }
                    )

            else
                ParserFast_Bad (struct( false, ParserFast_ExpectingSymbol (struct( s.Row, s.Col, str )) ))
        )

let ParserFast_whileWithoutLinebreakAnd2PartUtf16ToResultAndThen (whileCharIsOkay: int -> bool) (consumedStringToIntermediateOrErr: StringRope -> Result_Result<StringRope, 'intermediate>) (intermediateToFollowupParser: 'intermediate -> ParserFast_Parser<'res>) : ParserFast_Parser<'res> =
    ParserFast_Parser
        (fun (s0: Generated_Col_Indent_Offset_Row_Src<int64, int64, int64, int64, StringRope>) ->
            let s1Offset: int64 =
                ParserFast_skipWhileWithoutLinebreakAnd2PartUtf16Help whileCharIsOkay s0.Offset s0.Src
            
            let whileContent: StringRope =
                String_slice s0.Offset s1Offset s0.Src
            
            match consumedStringToIntermediateOrErr whileContent with
            | Error(problemMessage) ->
                ParserFast_Bad (struct( false, ParserFast_ExpectingCustom (struct( s0.Row, s0.Col, problemMessage )) ))

            | Ok(intermediate) ->
                let s1Column: int64 =
                    (+) s0.Col ((-) s1Offset s0.Offset)
                
                let (ParserFast_Parser(parseFollowup): ParserFast_Parser<'res>) =
                    intermediateToFollowupParser intermediate
                
                ParserFast_pStepCommit
                    (parseFollowup
                        { Col = s1Column
                        ; Indent = s0.Indent
                        ; Offset = s1Offset
                        ; Row = s0.Row
                        ; Src = s0.Src
                        }
                    )
        )

let ParserFast_orSucceed (ParserFast_Parser(attemptFirst): ParserFast_Parser<'a>) (secondRes: 'a) : ParserFast_Parser<'a> =
    ParserFast_Parser
        (fun (s: ParserFast_State) ->
            match attemptFirst s with
            | ParserFast_Good(_, _) as firstGood ->
                firstGood

            | ParserFast_Bad(firstCommitted, _) as firstBad ->
                if firstCommitted then
                    firstBad

                else
                    ParserFast_Good (struct( secondRes, s ))
        )

