let rec ParserFast_loopHelp (committedSoFar: bool) (state: 'state) ((ParserFast_Parser(parseElement) as element): ParserFast_Parser<'extension>) (reduce: 'extension -> 'state -> ParserFast_Step<'state, 'a>) (s0: ParserFast_State) : ParserFast_PStep<'a> =
    match parseElement s0 with
    | ParserFast_Good(step, s1) ->
        match reduce step state with
        | ParserFast_Loop(newState) ->
            ParserFast_loopHelp true newState element reduce s1

        | ParserFast_Done(result) ->
            ParserFast_Good (struct( result, s1 ))

    | ParserFast_Bad(elementCommitted, x) ->
        ParserFast_Bad (struct( Basics_or committedSoFar elementCommitted, x ))

