let ParserFast_followedBySymbol (str: StringRope) (ParserFast_Parser(parsePrevious): ParserFast_Parser<'a>) : ParserFast_Parser<'a> =
    let strLength: int64 =
        String_length str
    
    ParserFast_Parser
        (fun (s0: ParserFast_State) ->
            match parsePrevious s0 with
            | ParserFast_Good(res, s1) ->
                let newOffset: int64 =
                    (+) s1.Offset strLength
                
                if Basics_eq (String_slice s1.Offset newOffset s1.Src) str then
                    ParserFast_Good
                        (struct(
                          res
                        , { Col = (+) s1.Col strLength
                          ; Indent = s1.Indent
                          ; Offset = newOffset
                          ; Row = s1.Row
                          ; Src = s1.Src
                          }
                        ))

                else
                    ParserFast_Bad (struct( true, ParserFast_ExpectingSymbol (struct( s1.Row, s1.Col, str )) ))

            | bad ->
                bad
        )

