        ParserFast_convert0OrMoreHexadecimal 15L ((+) offset 1L) src

    | StringRopeOne("F") ->
        ParserFast_convert0OrMoreHexadecimal 15L ((+) offset 1L) src

    | _ ->
        { Int = 0L
        ; Offset = -1L
        }

let rec ParserFast_convert0OrMore0To9s (soFar: int64) (offset: int64) (src: StringRope) : Generated_Int_Offset<int64, int64> =
    match String_slice offset ((+) offset 1L) src with
    | StringRopeOne("0") ->
        ParserFast_convert0OrMore0To9s ((*) soFar 10L) ((+) offset 1L) src

    | StringRopeOne("1") ->
        ParserFast_convert0OrMore0To9s ((+) ((*) soFar 10L) 1L) ((+) offset 1L) src

    | StringRopeOne("2") ->
        ParserFast_convert0OrMore0To9s ((+) ((*) soFar 10L) 2L) ((+) offset 1L) src

    | StringRopeOne("3") ->
        ParserFast_convert0OrMore0To9s ((+) ((*) soFar 10L) 3L) ((+) offset 1L) src

    | StringRopeOne("4") ->
        ParserFast_convert0OrMore0To9s ((+) ((*) soFar 10L) 4L) ((+) offset 1L) src

    | StringRopeOne("5") ->
        ParserFast_convert0OrMore0To9s ((+) ((*) soFar 10L) 5L) ((+) offset 1L) src

    | StringRopeOne("6") ->
        ParserFast_convert0OrMore0To9s ((+) ((*) soFar 10L) 6L) ((+) offset 1L) src

    | StringRopeOne("7") ->
        ParserFast_convert0OrMore0To9s ((+) ((*) soFar 10L) 7L) ((+) offset 1L) src

    | StringRopeOne("8") ->
        ParserFast_convert0OrMore0To9s ((+) ((*) soFar 10L) 8L) ((+) offset 1L) src

    | StringRopeOne("9") ->
        ParserFast_convert0OrMore0To9s ((+) ((*) soFar 10L) 9L) ((+) offset 1L) src

    | _ ->
        { Int = soFar
        ; Offset = offset
        }

let ParserFast_convertIntegerDecimal (offset: int64) (src: StringRope) : Generated_Int_Offset<int64, int64> =
    match String_slice offset ((+) offset 1L) src with
    | StringRopeOne("0") ->
        { Int = 0L
        ; Offset = (+) offset 1L
        }

    | StringRopeOne("1") ->
        ParserFast_convert0OrMore0To9s 1L ((+) offset 1L) src

    | StringRopeOne("2") ->
        ParserFast_convert0OrMore0To9s 2L ((+) offset 1L) src

    | StringRopeOne("3") ->
        ParserFast_convert0OrMore0To9s 3L ((+) offset 1L) src

    | StringRopeOne("4") ->
        ParserFast_convert0OrMore0To9s 4L ((+) offset 1L) src

    | StringRopeOne("5") ->
        ParserFast_convert0OrMore0To9s 5L ((+) offset 1L) src

    | StringRopeOne("6") ->
        ParserFast_convert0OrMore0To9s 6L ((+) offset 1L) src

    | StringRopeOne("7") ->
        ParserFast_convert0OrMore0To9s 7L ((+) offset 1L) src

    | StringRopeOne("8") ->
        ParserFast_convert0OrMore0To9s 8L ((+) offset 1L) src

    | StringRopeOne("9") ->
        ParserFast_convert0OrMore0To9s 9L ((+) offset 1L) src

    | _ ->
        ParserFast_errorAsOffsetAndInt

let ParserFast_integerDecimalMapWithRange (rangeAndIntToRes: Generated_End_Start<Generated_Column_Row<int64, int64>, Generated_Column_Row<int64, int64>> -> int64 -> 'res) : ParserFast_Parser<'res> =
    ParserFast_Parser
        (fun (s0: Generated_Col_Indent_Offset_Row_Src<int64, int64, int64, int64, StringRope>) ->
            let s1: Generated_Int_Offset<int64, int64> =
                ParserFast_convertIntegerDecimal s0.Offset s0.Src
            
            if Basics_eq s1.Offset -1L then
                ParserFast_Bad (struct( false, ParserFast_ExpectingNumber (struct( s0.Row, s0.Col )) ))

            else
                let newColumn: int64 =
                    (+) s0.Col ((-) s1.Offset s0.Offset)
                
                ParserFast_Good
                    (struct(
                      rangeAndIntToRes
                        { End =
                            { Column = newColumn
                            ; Row = s0.Row
                            }
                        ; Start =
                            { Column = s0.Col
                            ; Row = s0.Row
                            }
                        }
                        s1.Int
                    , { Col = newColumn
                      ; Indent = s0.Indent
                      ; Offset = s1.Offset
                      ; Row = s0.Row
                      ; Src = s0.Src
                      }
                    ))
        )

let ParserFast_convertIntegerDecimalOrHexadecimal (offset: int64) (src: StringRope) : Generated_Base_OffsetAndInt<ParserFast_Base, Generated_Int_Offset<int64, int64>> =
    match String_slice offset ((+) offset 1L) src with
    | StringRopeOne("0") ->
        match String_slice ((+) offset 1L) ((+) offset 2L) src with
        | StringRopeOne("x") ->
            let hex: Generated_Int_Offset<int64, int64> =
                ParserFast_convert1OrMoreHexadecimal ((+) offset 2L) src
            
            { Base = ParserFast_Hexadecimal
            ; OffsetAndInt =
                { Int = hex.Int
                ; Offset = hex.Offset
                }
            }

        | _ ->
            { Base = ParserFast_Decimal
            ; OffsetAndInt =
                { Int = 0L
                ; Offset = (+) offset 1L
                }
            }

    | StringRopeOne("1") ->
        { Base = ParserFast_Decimal
        ; OffsetAndInt = ParserFast_convert0OrMore0To9s 1L ((+) offset 1L) src
        }

    | StringRopeOne("2") ->
        { Base = ParserFast_Decimal
        ; OffsetAndInt = ParserFast_convert0OrMore0To9s 2L ((+) offset 1L) src
        }

    | StringRopeOne("3") ->
        { Base = ParserFast_Decimal
        ; OffsetAndInt = ParserFast_convert0OrMore0To9s 3L ((+) offset 1L) src
        }

    | StringRopeOne("4") ->
        { Base = ParserFast_Decimal
        ; OffsetAndInt = ParserFast_convert0OrMore0To9s 4L ((+) offset 1L) src
        }

    | StringRopeOne("5") ->
        { Base = ParserFast_Decimal
        ; OffsetAndInt = ParserFast_convert0OrMore0To9s 5L ((+) offset 1L) src
        }

    | StringRopeOne("6") ->
        { Base = ParserFast_Decimal
        ; OffsetAndInt = ParserFast_convert0OrMore0To9s 6L ((+) offset 1L) src
        }

    | StringRopeOne("7") ->
        { Base = ParserFast_Decimal
        ; OffsetAndInt = ParserFast_convert0OrMore0To9s 7L ((+) offset 1L) src
        }

    | StringRopeOne("8") ->
        { Base = ParserFast_Decimal
        ; OffsetAndInt = ParserFast_convert0OrMore0To9s 8L ((+) offset 1L) src
        }

    | StringRopeOne("9") ->
        { Base = ParserFast_Decimal
        ; OffsetAndInt = ParserFast_convert0OrMore0To9s 9L ((+) offset 1L) src
        }

    | _ ->
        ParserFast_errorAsBaseOffsetAndInt__number_Int

let ParserFast_floatOrIntegerDecimalOrHexadecimalMapWithRange (rangeAndFloatToRes: Generated_End_Start<Generated_Column_Row<int64, int64>, Generated_Column_Row<int64, int64>> -> float -> 'res) (rangeAndIntDecimalToRes: ElmSyntaxRange_Range -> int64 -> 'res) (rangeAndIntHexadecimalToRes: ElmSyntaxRange_Range -> int64 -> 'res) : ParserFast_Parser<'res> =
    ParserFast_Parser
        (fun (s0: Generated_Col_Indent_Offset_Row_Src<int64, int64, int64, int64, StringRope>) ->
            let s1: Generated_Base_OffsetAndInt<ParserFast_Base, Generated_Int_Offset<int64, int64>> =
                ParserFast_convertIntegerDecimalOrHexadecimal s0.Offset s0.Src
            
            if Basics_eq s1.OffsetAndInt.Offset -1L then
                ParserFast_Bad (struct( false, ParserFast_ExpectingNumber (struct( s0.Row, s0.Col )) ))

            else
                let offsetAfterFloat: int64 =
                    ParserFast_skipFloatAfterIntegerDecimal s1.OffsetAndInt.Offset s0.Src
                
                if Basics_eq offsetAfterFloat -1L then
                    let newColumn: int64 =
                        (+) s0.Col ((-) s1.OffsetAndInt.Offset s0.Offset)
                    
                    let range: ElmSyntaxRange_Range =
                        { End =
                            { Column = newColumn
                            ; Row = s0.Row
                            }
                        ; Start =
                            { Column = s0.Col
                            ; Row = s0.Row
                            }
                        }
                    
                    ParserFast_Good
                        (struct(
                          match s1.Base with
                          | ParserFast_Decimal ->
                            rangeAndIntDecimalToRes range s1.OffsetAndInt.Int

                          | ParserFast_Hexadecimal ->
                            rangeAndIntHexadecimalToRes range s1.OffsetAndInt.Int
                        , { Col = newColumn
                          ; Indent = s0.Indent
                          ; Offset = s1.OffsetAndInt.Offset
                          ; Row = s0.Row
                          ; Src = s0.Src
                          }
                        ))

                else
                    match String_toFloat (String_slice s0.Offset offsetAfterFloat s0.Src) with
                    | ValueSome(float_) ->
                        let newColumn: int64 =
                            (+) s0.Col ((-) offsetAfterFloat s0.Offset)
                        
                        ParserFast_Good
                            (struct(
                              rangeAndFloatToRes
                                { End =
                                    { Column = newColumn
                                    ; Row = s0.Row
                                    }
                                ; Start =
                                    { Column = s0.Col
                                    ; Row = s0.Row
                                    }
                                }
                                float_
                            , { Col = newColumn
                              ; Indent = s0.Indent
                              ; Offset = offsetAfterFloat
                              ; Row = s0.Row
                              ; Src = s0.Src
                              }
                            ))

                    | ValueNone ->
                        ParserFast_Bad (struct( false, ParserFast_ExpectingNumber (struct( s0.Row, s0.Col )) ))
        )

let ParserFast_integerDecimalOrHexadecimalMapWithRange (rangeAndIntDecimalToRes: ElmSyntaxRange_Range -> int64 -> 'res) (rangeAndIntHexadecimalToRes: ElmSyntaxRange_Range -> int64 -> 'res) : ParserFast_Parser<'res> =
    ParserFast_Parser
        (fun (s0: Generated_Col_Indent_Offset_Row_Src<int64, int64, int64, int64, StringRope>) ->
            let s1: Generated_Base_OffsetAndInt<ParserFast_Base, Generated_Int_Offset<int64, int64>> =
                ParserFast_convertIntegerDecimalOrHexadecimal s0.Offset s0.Src
            
            if Basics_eq s1.OffsetAndInt.Offset -1L then
