                let range: ElmSyntaxRange_Range =
                    { End =
                        { Column = newColumn
                        ; Row = s0.Row
                        }
                    ; Start =
                        { Column = s0.Col
                        ; Row = s0.Row
                        }
                    }
                
                ParserFast_Good
                    (struct(
                      match s1.Base with
                      | ParserFast_Decimal ->
