            ParserAdvanced_Good (struct( false, a, s ))
        )

let Parser_succeed<'a>: 'a -> Parser_Parser<'a> =
    ParserAdvanced_succeed

let ParserAdvanced_revAlways (_: 'a) (b: 'b) : 'b =
    b

let rec ParserAdvanced_oneOfHelp (s0: ParserAdvanced_State<'c>) (bag: ParserAdvanced_Bag<'c, 'x>) (parsers: List<ParserAdvanced_Parser<'c, 'x, 'a>>) : ParserAdvanced_PStep<'c, 'x, 'a> =
    match parsers with
    | [] ->
        ParserAdvanced_Bad (struct( false, bag ))

    | ParserAdvanced_Parser(parse) :: remainingParsers ->
        match parse s0 with
        | ParserAdvanced_Good(_, _, _) as step ->
            step

        | ParserAdvanced_Bad(p, x) as step ->
            if p then
                step

            else
                ParserAdvanced_oneOfHelp s0 (ParserAdvanced_Append (struct( bag, x ))) remainingParsers

let ParserAdvanced_oneOf (parsers: List<ParserAdvanced_Parser<'c, 'x, 'a>>) : ParserAdvanced_Parser<'c, 'x, 'a> =
    ParserAdvanced_Parser
        (fun (s: ParserAdvanced_State<'c>) ->
            ParserAdvanced_oneOfHelp s ParserAdvanced_Empty parsers
        )

