    ParserAdvanced_oneOf

let ParserAdvanced_mapChompedString (func: StringRope -> 'a -> 'b) (ParserAdvanced_Parser(parse): ParserAdvanced_Parser<'c, 'x, 'a>) : ParserAdvanced_Parser<'c, 'x, 'b> =
    ParserAdvanced_Parser
        (fun (s0: ParserAdvanced_State<'c>) ->
            match parse s0 with
            | ParserAdvanced_Bad(p, x) ->
                ParserAdvanced_Bad (struct( p, x ))

            | ParserAdvanced_Good(p, a, s1) ->
                ParserAdvanced_Good (struct( p, func (String_slice s0.Offset s1.Offset s0.Src) a, s1 ))
        )

