    ParserAdvanced_map2 ParserAdvanced_revAlways iParser kParser

let ParserAdvanced_map (func: 'a -> 'b) (ParserAdvanced_Parser(parse): ParserAdvanced_Parser<'c, 'x, 'a>) : ParserAdvanced_Parser<'c, 'x, 'b> =
    ParserAdvanced_Parser
        (fun (s0: ParserAdvanced_State<'c>) ->
            match parse s0 with
            | ParserAdvanced_Good(p, a, s1) ->
                ParserAdvanced_Good (struct( p, func a, s1 ))

            | ParserAdvanced_Bad(p, x) ->
                ParserAdvanced_Bad (struct( p, x ))
        )

let rec ParserAdvanced_sequenceEndForbidden (ender: ParserAdvanced_Parser<'c, 'x, unit>) (ws: ParserAdvanced_Parser<'c, 'x, unit>) (parseItem: ParserAdvanced_Parser<'c, 'x, 'a>) (sep: ParserAdvanced_Parser<'c, 'x, unit>) (revItems: List<'a>) : ParserAdvanced_Parser<'c, 'x, ParserAdvanced_Step<List<'a>, List<'a>>> =
    let chompRest (item: 'a) : ParserAdvanced_Parser<'c, 'x, ParserAdvanced_Step<List<'a>, List<'a>>> =
        ParserAdvanced_sequenceEndForbidden ender ws parseItem sep (List_cons item revItems)
    
    ParserAdvanced_skip
        ws
        (ParserAdvanced_oneOf
            [ ParserAdvanced_skip
                sep
                (ParserAdvanced_skip
                    ws
                    (ParserAdvanced_map
                        (fun (item: 'a) ->
                            ParserAdvanced_Loop (List_cons item revItems)
                        )
                        parseItem
                    )
                );
              ParserAdvanced_map
                (fun (_: unit) ->
                    ParserAdvanced_Done (List.rev revItems)
                )
                ender
            ]
        )

let ParserAdvanced_sequenceEndOptional (ender: ParserAdvanced_Parser<'c, 'x, unit>) (ws: ParserAdvanced_Parser<'c, 'x, unit>) (parseItem: ParserAdvanced_Parser<'c, 'x, 'a>) (sep: ParserAdvanced_Parser<'c, 'x, unit>) (revItems: List<'a>) : ParserAdvanced_Parser<'c, 'x, ParserAdvanced_Step<List<'a>, List<'a>>> =
    let parseEnd: ParserAdvanced_Parser<'c, 'x, ParserAdvanced_Step<'state, List<'a>>> =
        ParserAdvanced_map
            (fun (_: unit) ->
                ParserAdvanced_Done (List.rev revItems)
            )
            ender
    
    ParserAdvanced_skip
        ws
        (ParserAdvanced_oneOf
            [ ParserAdvanced_skip
                sep
                (ParserAdvanced_skip
                    ws
                    (ParserAdvanced_oneOf
                        [ ParserAdvanced_map
                            (fun (item: 'a) ->
                                ParserAdvanced_Loop (List_cons item revItems)
                            )
                            parseItem;
                          parseEnd
                        ]
                    )
                );
              parseEnd
            ]
        )

