    ParserAdvanced_map

let rec ParserAdvanced_loopHelp (p: bool) (state: 'state) (callback: 'state -> ParserAdvanced_Parser<'c, 'x, ParserAdvanced_Step<'state, 'a>>) (s0: ParserAdvanced_State<'c>) : ParserAdvanced_PStep<'c, 'x, 'a> =
    let (ParserAdvanced_Parser(parse): ParserAdvanced_Parser<'c, 'x, ParserAdvanced_Step<'state, 'a>>) =
        callback state
    
    match parse s0 with
    | ParserAdvanced_Good(p1, step, s1) ->
        match step with
        | ParserAdvanced_Loop(newState) ->
            ParserAdvanced_loopHelp (Basics_or p p1) newState callback s1

        | ParserAdvanced_Done(result) ->
            ParserAdvanced_Good (struct( Basics_or p p1, result, s1 ))

    | ParserAdvanced_Bad(p1, x) ->
        ParserAdvanced_Bad (struct( Basics_or p p1, x ))

