let rec ParserAdvanced_varHelp (isGood: int -> bool) (offset: int64) (row: int64) (col: int64) (src: StringRope) (indent: int64) (context: List<ParserAdvanced_Located<'c>>) : Generated_Col_Context_Indent_Offset_Row_Src<int64, List<ParserAdvanced_Located<'c>>, int64, int64, int64, StringRope> =
    let newOffset: int64 =
        ParserAdvanced_isSubChar isGood offset src
    
    if Basics_eq newOffset -1L then
        { Col = col
        ; Context = context
        ; Indent = indent
        ; Offset = offset
        ; Row = row
        ; Src = src
        }

    else
        if Basics_eq newOffset -2L then
            ParserAdvanced_varHelp isGood ((+) offset 1L) ((+) row 1L) 1L src indent context

        else
            ParserAdvanced_varHelp isGood newOffset row ((+) col 1L) src indent context

