let ParserAdvanced_sequenceEndMandatory (ws: ParserAdvanced_Parser<'c, 'x, unit>) (parseItem: ParserAdvanced_Parser<'c, 'x, 'a>) (sep: ParserAdvanced_Parser<'c, 'x, unit>) (revItems: List<'a>) : ParserAdvanced_Parser<'c, 'x, ParserAdvanced_Step<List<'a>, List<'a>>> =
