let ParserAdvanced_keyword (ParserAdvanced_Token(kwd, expecting): ParserAdvanced_Token<'x>) : ParserAdvanced_Parser<'c, 'x, unit> =
    let progress: bool =
        not (String_isEmpty kwd)
    
    ParserAdvanced_Parser
        (fun (s: Generated_Col_Context_Indent_Offset_Row_Src<int64, List<ParserAdvanced_Located<'c>>, int64, int64, int64, StringRope>) ->
            let ((struct( newOffset, newRow, newCol )):
                    (struct(
                      int64
                    * int64
                    * int64
                    ))
                ) =
                ParserAdvanced_isSubString kwd s.Offset s.Row s.Col s.Src
            
            if
                Basics_or
                    (Basics_eq newOffset -1L)
                    ((<=)
                        0L
                        (ParserAdvanced_isSubChar
                            (fun (c: int) ->
                                Basics_or (Char_isAlphaNum c) (Basics_eq c 95)
                            )
                            newOffset
                            s.Src
                        )
                    )
            then
                ParserAdvanced_Bad (struct( false, ParserAdvanced_fromState s expecting ))

            else
                ParserAdvanced_Good
                    (struct(
                      progress
                    , ()
                    , { Col = newCol
                      ; Context = s.Context
                      ; Indent = s.Indent
                      ; Offset = newOffset
                      ; Row = newRow
                      ; Src = s.Src
                      }
                    ))
        )

