let ParserAdvanced_variable (i: Generated_Expecting_Inner_Reserved_Start<'x, int -> bool, Set<StringRope>, int -> bool>) : ParserAdvanced_Parser<'c, 'x, StringRope> =
    ParserAdvanced_Parser
        (fun (s: Generated_Col_Context_Indent_Offset_Row_Src<int64, List<ParserAdvanced_Located<'c>>, int64, int64, int64, StringRope>) ->
            let firstOffset: int64 =
                ParserAdvanced_isSubChar i.Start s.Offset s.Src
            
            if Basics_eq firstOffset -1L then
                ParserAdvanced_Bad (struct( false, ParserAdvanced_fromState s i.Expecting ))

            else
                let s1: ParserAdvanced_State<'c> =
                    if Basics_eq firstOffset -2L then
                        ParserAdvanced_varHelp i.Inner ((+) s.Offset 1L) ((+) s.Row 1L) 1L s.Src s.Indent s.Context

                    else
                        ParserAdvanced_varHelp i.Inner firstOffset s.Row ((+) s.Col 1L) s.Src s.Indent s.Context
                
                let name: StringRope =
                    String_slice s.Offset s1.Offset s.Src
                
                if Set.contains name i.Reserved then
                    ParserAdvanced_Bad (struct( false, ParserAdvanced_fromState s i.Expecting ))

                else
                    ParserAdvanced_Good (struct( true, name, s1 ))
        )

