let rec ParserAdvanced_chompWhileHelp (isGood: int -> bool) (offset: int64) (row: int64) (col: int64) (s0: Generated_Col_Context_Indent_Offset_Row_Src<int64, List<ParserAdvanced_Located<'c>>, int64, int64, int64, StringRope>) : ParserAdvanced_PStep<'c, 'x, unit> =
