              ; Context = s0.Context
              ; Indent = s0.Indent
              ; Offset = offset
              ; Row = row
              ; Src = s0.Src
              }
            ))

    else
        if Basics_eq newOffset -2L then
            ParserAdvanced_chompWhileHelp isGood ((+) offset 1L) ((+) row 1L) 1L s0

        else
            ParserAdvanced_chompWhileHelp isGood newOffset row ((+) col 1L) s0

