    ElmKernelParser_chompBase10

let ParserAdvanced_consumeExp (offset: int64) (src: StringRope) : int64 =
    if Basics_or (ParserAdvanced_isAsciiCode 101L offset src) (ParserAdvanced_isAsciiCode 69L offset src) then
        let eOffset: int64 =
            (+) offset 1L
        
        let expOffset: int64 =
            if Basics_or (ParserAdvanced_isAsciiCode 43L eOffset src) (ParserAdvanced_isAsciiCode 45L eOffset src) then
                (+) eOffset 1L

            else
                eOffset
        
        let newOffset: int64 =
            ParserAdvanced_chompBase10 expOffset src
        
        if Basics_eq expOffset newOffset then
            -newOffset

        else
            newOffset

    else
        offset

let ParserAdvanced_consumeDotAndExp (offset: int64) (src: StringRope) : int64 =
    if ParserAdvanced_isAsciiCode 46L offset src then
        ParserAdvanced_consumeExp (ParserAdvanced_chompBase10 ((+) offset 1L) src) src

    else
        ParserAdvanced_consumeExp offset src

