let ParserAdvanced_bumpOffset (newOffset: int64) (s: Generated_Col_Context_Indent_Offset_Row_Src<int64, List<ParserAdvanced_Located<'c>>, int64, int64, int64, StringRope>) : Generated_Col_Context_Indent_Offset_Row_Src<int64, List<ParserAdvanced_Located<'c>>, int64, int64, int64, StringRope> =
