let ParserAdvanced_finalizeInt
    (invalid: 'x)
    (handler: Result_Result<'x, int64 -> 'a>)
    (startOffset: int64)
    ((struct( endOffset, n )):
        (struct(
          int64
        * int64
        ))
    )
    (s: ParserAdvanced_State<'c>)
    : ParserAdvanced_PStep<'c, 'x, 'a> =
    match handler with
    | Error(x) ->
        ParserAdvanced_Bad (struct( true, ParserAdvanced_fromState s x ))

    | Ok(toValue) ->
        if Basics_eq startOffset endOffset then
            ParserAdvanced_Bad (struct( (<) s.Offset startOffset, ParserAdvanced_fromState s invalid ))

        else
            ParserAdvanced_Good (struct( true, toValue n, ParserAdvanced_bumpOffset endOffset s ))

let ParserAdvanced_finalizeFloat
    (invalid: 'x)
    (expecting: 'x)
    (intSettings: Result_Result<'x, int64 -> 'a>)
    (floatSettings: Result_Result<'x, float -> 'a>)
    (intPair:
        (struct(
          int64
        * int64
        ))
    )
    (s: Generated_Col_Context_Indent_Offset_Row_Src<int64, List<ParserAdvanced_Located<'c>>, int64, int64, int64, StringRope>)
    : ParserAdvanced_PStep<'c, 'x, 'a> =
    let intOffset: int64 =
        Tuple_first intPair
    
    let floatOffset: int64 =
        ParserAdvanced_consumeDotAndExp intOffset s.Src
    
    if (<) floatOffset 0L then
        ParserAdvanced_Bad (struct( true, ParserAdvanced_fromInfo s.Row ((-) s.Col ((+) floatOffset s.Offset)) invalid s.Context ))

    else
        if Basics_eq s.Offset floatOffset then
            ParserAdvanced_Bad (struct( false, ParserAdvanced_fromState s expecting ))

        else
            if Basics_eq intOffset floatOffset then
                ParserAdvanced_finalizeInt invalid intSettings s.Offset intPair s

            else
                match floatSettings with
                | Error(x) ->
                    ParserAdvanced_Bad (struct( true, ParserAdvanced_fromState s invalid ))

                | Ok(toValue) ->
                    match String_toFloat (String_slice s.Offset floatOffset s.Src) with
                    | ValueNone ->
                        ParserAdvanced_Bad (struct( true, ParserAdvanced_fromState s invalid ))

                    | ValueSome(n) ->
                        ParserAdvanced_Good (struct( true, toValue n, ParserAdvanced_bumpOffset floatOffset s ))

let ParserAdvanced_number (c: Generated_Binary_Expecting_Float_Hex_Int_Invalid_Octal<Result_Result<'x, int64 -> 'a>, 'x, Result_Result<'x, float -> 'a>, Result_Result<'x, int64 -> 'a>, Result_Result<'x, int64 -> 'a>, 'x, Result_Result<'x, int64 -> 'a>>) : ParserAdvanced_Parser<'c, 'x, 'a> =
    ParserAdvanced_Parser
        (fun (s: Generated_Col_Context_Indent_Offset_Row_Src<int64, List<ParserAdvanced_Located<'c>>, int64, int64, int64, StringRope>) ->
            if ParserAdvanced_isAsciiCode 48L s.Offset s.Src then
                let zeroOffset: int64 =
                    (+) s.Offset 1L
                
                let baseOffset: int64 =
                    (+) zeroOffset 1L
                
                if ParserAdvanced_isAsciiCode 120L zeroOffset s.Src then
                    ParserAdvanced_finalizeInt c.Invalid c.Hex baseOffset (ParserAdvanced_consumeBase16 baseOffset s.Src) s

                else
                    if ParserAdvanced_isAsciiCode 111L zeroOffset s.Src then
                        ParserAdvanced_finalizeInt c.Invalid c.Octal baseOffset (ParserAdvanced_consumeBase 8L baseOffset s.Src) s

                    else
                        if ParserAdvanced_isAsciiCode 98L zeroOffset s.Src then
                            ParserAdvanced_finalizeInt c.Invalid c.Binary baseOffset (ParserAdvanced_consumeBase 2L baseOffset s.Src) s

                        else
                            ParserAdvanced_finalizeFloat c.Invalid c.Expecting c.Int c.Float (struct( zeroOffset, 0L )) s

            else
                ParserAdvanced_finalizeFloat c.Invalid c.Expecting c.Int c.Float (ParserAdvanced_consumeBase 10L s.Offset s.Src) s
        )

let ParserAdvanced_float (expecting: 'x) (invalid: 'x) : ParserAdvanced_Parser<'c, 'x, float> =
    ParserAdvanced_number
        { Binary = Error invalid
        ; Expecting = expecting
        ; Float = Ok id
        ; Hex = Error invalid
        ; Int = Ok float
        ; Invalid = invalid
        ; Octal = Error invalid
        }

