        ; Invalid = Parser_ExpectingNumber
        ; Octal = Result_fromMaybe Parser_ExpectingOctal i.Octal
        }

let rec ParserAdvanced_bagToList (bag: ParserAdvanced_Bag<'c, 'x>) (list_: List<ParserAdvanced_DeadEnd<'c, 'x>>) : List<ParserAdvanced_DeadEnd<'c, 'x>> =
    match bag with
    | ParserAdvanced_Empty ->
        list_

    | ParserAdvanced_AddRight(bag1, x) ->
        ParserAdvanced_bagToList bag1 (List_cons x list_)

    | ParserAdvanced_Append(bag1, bag2) ->
        ParserAdvanced_bagToList bag1 (ParserAdvanced_bagToList bag2 list_)

let ParserAdvanced_run (ParserAdvanced_Parser(parse): ParserAdvanced_Parser<'c, 'x, 'a>) (src: StringRope) : Result_Result<List<ParserAdvanced_DeadEnd<'c, 'x>>, 'a> =
    match
        parse
            { Col = 1L
            ; Context = []
            ; Indent = 1L
            ; Offset = 0L
            ; Row = 1L
            ; Src = src
            }
    with
    | ParserAdvanced_Good(_, value, _) ->
        Ok value

    | ParserAdvanced_Bad(_, bag) ->
        Error (ParserAdvanced_bagToList bag [])

let Parser_run (parser: ParserAdvanced_Parser<Basics_Never, Parser_Problem, 'a>) (source: StringRope) : Result_Result<List<Parser_DeadEnd>, 'a> =
    match ParserAdvanced_run parser source with
    | Ok(a) ->
        Ok a

    | Error(problems) ->
        Error (List.map Parser_problemToDeadEnd problems)

let ParserAdvanced_backtrackable (ParserAdvanced_Parser(parse): ParserAdvanced_Parser<'c, 'x, 'a>) : ParserAdvanced_Parser<'c, 'x, 'a> =
    ParserAdvanced_Parser
        (fun (s0: ParserAdvanced_State<'c>) ->
            match parse s0 with
            | ParserAdvanced_Bad(_, x) ->
                ParserAdvanced_Bad (struct( false, x ))

            | ParserAdvanced_Good(_, a, s1) ->
                ParserAdvanced_Good (struct( false, a, s1 ))
        )

let Parser_backtrackable<'a>: Parser_Parser<'a> -> Parser_Parser<'a> =
    ParserAdvanced_backtrackable

let ParserAdvanced_andThen (callback: 'a -> ParserAdvanced_Parser<'c, 'x, 'b>) (ParserAdvanced_Parser(parseA): ParserAdvanced_Parser<'c, 'x, 'a>) : ParserAdvanced_Parser<'c, 'x, 'b> =
    ParserAdvanced_Parser
        (fun (s0: ParserAdvanced_State<'c>) ->
            match parseA s0 with
            | ParserAdvanced_Bad(p, x) ->
                ParserAdvanced_Bad (struct( p, x ))

            | ParserAdvanced_Good(p1, a, s1) ->
                let (ParserAdvanced_Parser(parseB): ParserAdvanced_Parser<'c, 'x, 'b>) =
                    callback a
                
                match parseB s1 with
                | ParserAdvanced_Bad(p2, x) ->
                    ParserAdvanced_Bad (struct( Basics_or p1 p2, x ))

                | ParserAdvanced_Good(p2, b, s2) ->
                    ParserAdvanced_Good (struct( Basics_or p1 p2, b, s2 ))
        )

let rec ParserAdvanced_nestableHelp (isNotRelevant: int -> bool) (open_: ParserAdvanced_Parser<'c, 'x, unit>) (close: ParserAdvanced_Parser<'c, 'x, unit>) (expectingClose: 'x) (nestLevel: int64) : ParserAdvanced_Parser<'c, 'x, unit> =
    ParserAdvanced_skip
        (ParserAdvanced_chompWhile isNotRelevant)
        (ParserAdvanced_oneOf
            [ if Basics_eq nestLevel 1L then
                close

              else
                ParserAdvanced_andThen
                    (fun (_: unit) ->
                        ParserAdvanced_nestableHelp isNotRelevant open_ close expectingClose ((-) nestLevel 1L)
                    )
                    close;
              ParserAdvanced_andThen
                (fun (_: unit) ->
                    ParserAdvanced_nestableHelp isNotRelevant open_ close expectingClose ((+) nestLevel 1L)
                )
                open_;
              ParserAdvanced_andThen
                (fun (_: unit) ->
                    ParserAdvanced_nestableHelp isNotRelevant open_ close expectingClose nestLevel
                )
                (ParserAdvanced_chompIf ParserAdvanced_isChar expectingClose)
            ]
        )

let ParserAdvanced_nestableComment ((ParserAdvanced_Token(oStr, oX) as open_): ParserAdvanced_Token<'x>) ((ParserAdvanced_Token(cStr, cX) as close): ParserAdvanced_Token<'x>) : ParserAdvanced_Parser<'c, 'x, unit> =
    match String_uncons oStr with
    | ValueNone ->
        ParserAdvanced_problem oX

    | ValueSome((struct( openChar, _ ))) ->
        match String_uncons cStr with
        | ValueNone ->
            ParserAdvanced_problem cX

        | ValueSome((struct( closeChar, _ ))) ->
            let isNotRelevant (char_: int) : bool =
                Basics_and (Basics_neq char_ openChar) (Basics_neq char_ closeChar)
            
            let chompOpen: ParserAdvanced_Parser<'c, 'x, unit> =
                ParserAdvanced_token open_
            
            ParserAdvanced_ignorer chompOpen (ParserAdvanced_nestableHelp isNotRelevant chompOpen (ParserAdvanced_token close) cX 1L)

let ParserAdvanced_multiComment (open_: ParserAdvanced_Token<'x>) (close: ParserAdvanced_Token<'x>) (nestable: ParserAdvanced_Nestable) : ParserAdvanced_Parser<'c, 'x, unit> =
    match nestable with
    | ParserAdvanced_NotNestable ->
        ParserAdvanced_ignorer (ParserAdvanced_token open_) (ParserAdvanced_chompUntil close)

    | ParserAdvanced_Nestable ->
        ParserAdvanced_nestableComment open_ close

let Parser_multiComment (open_: StringRope) (close: StringRope) (nestable: Parser_Nestable) : ParserAdvanced_Parser<Basics_Never, Parser_Problem, unit> =
    ParserAdvanced_multiComment (Parser_toToken open_) (Parser_toToken close) (Parser_toAdvancedNestable nestable)

let ParserAdvanced_sequenceEnd (ender: ParserAdvanced_Parser<'c, 'x, unit>) (ws: ParserAdvanced_Parser<'c, 'x, unit>) (parseItem: ParserAdvanced_Parser<'c, 'x, 'a>) (sep: ParserAdvanced_Parser<'c, 'x, unit>) (trailing: ParserAdvanced_Trailing) : ParserAdvanced_Parser<'c, 'x, List<'a>> =
    let chompRest (item: 'a) : ParserAdvanced_Parser<'c, 'x, List<'a>> =
        match trailing with
        | ParserAdvanced_Forbidden ->
            ParserAdvanced_loop [ item ] (ParserAdvanced_sequenceEndForbidden ender ws parseItem sep)

        | ParserAdvanced_Optional ->
            ParserAdvanced_loop [ item ] (ParserAdvanced_sequenceEndOptional ender ws parseItem sep)

        | ParserAdvanced_Mandatory ->
            ParserAdvanced_ignorer (ParserAdvanced_skip ws (ParserAdvanced_skip sep (ParserAdvanced_skip ws (ParserAdvanced_loop [ item ] (ParserAdvanced_sequenceEndMandatory ws parseItem sep))))) ender
    
    ParserAdvanced_oneOf
        [ ParserAdvanced_andThen chompRest parseItem;
          ParserAdvanced_map
            (fun (_: unit) ->
                []
            )
            ender
        ]

let ParserAdvanced_sequence (i: Generated_End_Item_Separator_Spaces_Start_Trailing<ParserAdvanced_Token<'x>, ParserAdvanced_Parser<'c, 'x, 'a>, ParserAdvanced_Token<'x>, ParserAdvanced_Parser<'c, 'x, unit>, ParserAdvanced_Token<'x>, ParserAdvanced_Trailing>) : ParserAdvanced_Parser<'c, 'x, List<'a>> =
    ParserAdvanced_skip (ParserAdvanced_token i.Start) (ParserAdvanced_skip i.Spaces (ParserAdvanced_sequenceEnd (ParserAdvanced_token i.End) i.Spaces i.Item (ParserAdvanced_token i.Separator) i.Trailing))

let Parser_sequence (i: Generated_End_Item_Separator_Spaces_Start_Trailing<StringRope, Parser_Parser<'a>, StringRope, Parser_Parser<unit>, StringRope, Parser_Trailing>) : ParserAdvanced_Parser<Basics_Never, Parser_Problem, List<'a>> =
    ParserAdvanced_sequence
        { End = Parser_toToken i.End
        ; Item = i.Item
        ; Separator = Parser_toToken i.Separator
        ; Spaces = i.Spaces
        ; Start = Parser_toToken i.Start
        ; Trailing = Parser_toAdvancedTrailing i.Trailing
        }

let Parser_andThen<'a, 'b>: ('a -> Parser_Parser<'b>) -> Parser_Parser<'a> -> Parser_Parser<'b> =
    ParserAdvanced_andThen

let rec ListExtra_uniqueHelp (existing: List<'a>) (remaining: List<'a>) (accumulator: List<'a>) : List<'a> =
    match remaining with
    | [] ->
        accumulator

    | first :: rest ->
        if List_member first existing then
            ListExtra_uniqueHelp existing rest accumulator

        else
            ListExtra_uniqueHelp (List_cons first existing) rest (List_cons first accumulator)

let ListExtra_unique (list_: List<'a>) : List<'a> =
    ListExtra_uniqueHelp [] list_ []

let rec ListExtra_find (predicate: 'a -> bool) (list_: List<'a>) : ValueOption<'a> =
    match list_ with
    | [] ->
        ValueNone

    | x :: xs ->
        if predicate x then
            ValueSome x

        else
            ListExtra_find predicate xs

let rec Hex_unsafeToDigit (num: int64) : int =
    match num with
    | 0L ->
        48

    | 1L ->
        49

    | 2L ->
        50

    | 3L ->
        51

    | 4L ->
        52

    | 5L ->
        53

    | 6L ->
        54

    | 7L ->
        55

    | 8L ->
        56

    | 9L ->
        57

    | 10L ->
        97

    | 11L ->
        98

    | 12L ->
        99

    | 13L ->
        100

    | 14L ->
        101

    | 15L ->
        102

    | _ ->
        Hex_unsafeToDigit num

let rec Hex_unsafePositiveToDigits (digits: List<int>) (num: int64) : List<int> =
    if (<) num 16L then
        List_cons (Hex_unsafeToDigit num) digits

    else
        Hex_unsafePositiveToDigits (List_cons (Hex_unsafeToDigit (Basics_modBy 16L num)) digits) ((/) num 16L)

let Hex_toString (num: int64) : StringRope =
    String_fromList
        (if (<) num 0L then
            List_cons 45 (Hex_unsafePositiveToDigits [] (Basics_inegate num))

         else
            Hex_unsafePositiveToDigits [] num
        )

let rec Hex_fromStringHelp (position: int64) (chars: List<int>) (accumulated: int64) : Result_Result<StringRope, int64> =
    match chars with
    | [] ->
        Ok accumulated

    | char_ :: rest ->
        match char_ with
        | 48 ->
            Hex_fromStringHelp ((-) position 1L) rest accumulated

        | 49 ->
            Hex_fromStringHelp ((-) position 1L) rest ((+) accumulated (Basics_ipow 16L position))

        | 50 ->
            Hex_fromStringHelp ((-) position 1L) rest ((+) accumulated ((*) 2L (Basics_ipow 16L position)))

        | 51 ->
            Hex_fromStringHelp ((-) position 1L) rest ((+) accumulated ((*) 3L (Basics_ipow 16L position)))

        | 52 ->
            Hex_fromStringHelp ((-) position 1L) rest ((+) accumulated ((*) 4L (Basics_ipow 16L position)))

        | 53 ->
            Hex_fromStringHelp ((-) position 1L) rest ((+) accumulated ((*) 5L (Basics_ipow 16L position)))

        | 54 ->
            Hex_fromStringHelp ((-) position 1L) rest ((+) accumulated ((*) 6L (Basics_ipow 16L position)))

        | 55 ->
            Hex_fromStringHelp ((-) position 1L) rest ((+) accumulated ((*) 7L (Basics_ipow 16L position)))

        | 56 ->
            Hex_fromStringHelp ((-) position 1L) rest ((+) accumulated ((*) 8L (Basics_ipow 16L position)))

        | 57 ->
            Hex_fromStringHelp ((-) position 1L) rest ((+) accumulated ((*) 9L (Basics_ipow 16L position)))

        | 97 ->
            Hex_fromStringHelp ((-) position 1L) rest ((+) accumulated ((*) 10L (Basics_ipow 16L position)))

        | 98 ->
            Hex_fromStringHelp ((-) position 1L) rest ((+) accumulated ((*) 11L (Basics_ipow 16L position)))

        | 99 ->
            Hex_fromStringHelp ((-) position 1L) rest ((+) accumulated ((*) 12L (Basics_ipow 16L position)))

        | 100 ->
            Hex_fromStringHelp ((-) position 1L) rest ((+) accumulated ((*) 13L (Basics_ipow 16L position)))

        | 101 ->
            Hex_fromStringHelp ((-) position 1L) rest ((+) accumulated ((*) 14L (Basics_ipow 16L position)))

        | 102 ->
            Hex_fromStringHelp ((-) position 1L) rest ((+) accumulated ((*) 15L (Basics_ipow 16L position)))

        | nonHex ->
            Error (String_append (String_fromChar nonHex) (StringRopeOne " is not a valid hexadecimal character."))

let Hex_fromString (str: StringRope) : Result_Result<StringRope, int64> =
    if String_isEmpty str then
        Error (StringRopeOne "Empty strings are not valid hexadecimal strings.")

    else
        let result: Result_Result<StringRope, int64> =
            if String_startsWith (StringRopeOne "-") str then
                let list_: List<int> =
                    ValueOption.defaultValue [] (List_tail (String_toList str))
                
                Result.map Basics_inegate (Hex_fromStringHelp ((-) (List_length list_) 1L) list_ 0L)

            else
                Hex_fromStringHelp ((-) (String_length str) 1L) (String_toList str) 0L
        
        let formatError (err: StringRope) : StringRope =
            String_join
                (StringRopeOne " ")
                [ String_append (StringRopeOne "\"") (String_append str (StringRopeOne "\""));
                  StringRopeOne "is not a valid hexadecimal string because";
                  err
                ]
        
        Result.mapError formatError result

let ElmWriter_writeModuleName (moduleName: List<StringRope>) : StructuredWriter_Writer =
    StructuredWriter_string (String_join (StringRopeOne ".") moduleName)

let ElmWriter_writeQualifiedNameRef ({ ModuleName = moduleName; Name = name }: Generated_ModuleName_Name<List<StringRope>, StringRope>) : StructuredWriter_Writer =
    match moduleName with
    | [] ->
        StructuredWriter_string name

    | _ ->
        StructuredWriter_join
            [ ElmWriter_writeModuleName moduleName;
              StructuredWriter_string (StringRopeOne ".");
              StructuredWriter_string name
            ]

let ElmWriter_writeExpose (ElmSyntaxNode_Node(_, exp): ElmSyntaxNode_Node<ElmSyntaxExposing_TopLevelExpose>) : StructuredWriter_Writer =
    match exp with
    | ElmSyntaxExposing_InfixExpose(x) ->
        StructuredWriter_string (String_append (StringRopeOne "(") (String_append x (StringRopeOne ")")))

    | ElmSyntaxExposing_FunctionExpose(f) ->
        StructuredWriter_string f

    | ElmSyntaxExposing_TypeOrAliasExpose(t) ->
        StructuredWriter_string t

    | ElmSyntaxExposing_TypeExpose({ Name = name; Open = open_ }) ->
        match open_ with
        | ValueSome(_) ->
            StructuredWriter_spaced
                [ StructuredWriter_string name;
                  StructuredWriter_string (StringRopeOne "(..)")
                ]

        | ValueNone ->
            StructuredWriter_string name

let ElmWriter_writeChar (c: int) : StructuredWriter_Writer =
    let escape: StringRope =
        match c with
        | 9 ->
            StringRopeOne "'\\"

        | 39 ->
            StringRopeOne "'\\"

        | 92 ->
            StringRopeOne "'\\"

        | _ ->
            StringRopeOne "'"
    
    StructuredWriter_string (String_append escape (String_append (String_fromChar c) (StringRopeOne "'")))

let ElmWriter_write: StructuredWriter_Writer -> StringRope =
    StructuredWriter_write

let ElmWriter_startOnDifferentLines (xs: List<Generated_End_Start<ElmSyntaxRange_Location, Generated_Column_Row<int64, int64>>>) : bool =
    (>)
        (List_length
            (ListExtra_unique
                (List.map
                    ((>>)
                        (fun (generated_record: Generated_End_Start<ElmSyntaxRange_Location, Generated_Column_Row<int64, int64>>) ->
                            generated_record.Start
                        )
                        (fun (generated_record: Generated_Column_Row<int64, int64>) ->
                            generated_record.Row
                        )
                    )
                    xs
                )
            )
        )
        1L

let ElmWriter_parensIfContainsSpaces (w: StructuredWriter_Writer) : StructuredWriter_Writer =
    if String_contains (StringRopeOne " ") (StructuredWriter_write w) then
        StructuredWriter_join
            [ StructuredWriter_string (StringRopeOne "(");
              w;
              StructuredWriter_string (StringRopeOne ")")
            ]

    else
        w

let ElmWriter_escapeString: StringRope -> StringRope =
    String_replace (StringRopeOne "\"") (StringRopeOne "\\\"")

let ElmSyntaxRange_fromList (input: List<int64>) : JsonDecode_Decoder<Generated_End_Start<Generated_Column_Row<int64, int64>, Generated_Column_Row<int64, int64>>> =
    match input with
    | [ a; b; c; d ] ->
        JsonDecode_succeed
            { End =
                { Column = d
                ; Row = c
                }
            ; Start =
                { Column = b
                ; Row = a
                }
            }

    | _ ->
        JsonDecode_fail (StringRopeOne "Invalid input list")

let ElmSyntaxRange_encode ({ End = end_; Start = start }: Generated_End_Start<ElmSyntaxRange_Location, ElmSyntaxRange_Location>) : System.Text.Json.Nodes.JsonNode =
    JsonEncode_list
        JsonEncode_int
        [ start.Row;
          start.Column;
          end_.Row;
          end_.Column
        ]

let ElmSyntaxRange_empty: ElmSyntaxRange_Range =
    { End =
        { Column = 0L
        ; Row = 0L
        }
    ; Start =
        { Column = 0L
        ; Row = 0L
        }
    }

let ElmSyntaxRange_emptyRange: ElmSyntaxRange_Range =
    ElmSyntaxRange_empty

let ElmSyntaxRange_decoder: JsonDecode_Decoder<ElmSyntaxRange_Range> =
    JsonDecode_andThen ElmSyntaxRange_fromList (JsonDecode_list JsonDecode_int)

let ElmSyntaxRange_compareLocations (left: Generated_Column_Row<int64, int64>) (right: Generated_Column_Row<int64, int64>) : Basics_Order =
    if (<) left.Row right.Row then
        Basics_Order.LT

    else
        if (>) left.Row right.Row then
            Basics_Order.GT

        else
            Basics_compare left.Column right.Column

let ElmSyntaxRange_compare (left: Generated_End_Start<ElmSyntaxRange_Location, ElmSyntaxRange_Location>) (right: Generated_End_Start<ElmSyntaxRange_Location, ElmSyntaxRange_Location>) : Basics_Order =
    match ElmSyntaxRange_compareLocations left.Start right.Start with
    | Basics_Order.EQ ->
        ElmSyntaxRange_compareLocations left.End right.End

    | order ->
        order

let rec ElmSyntaxRange_combineHelp (ranges: List<Generated_End_Start<ElmSyntaxRange_Location, ElmSyntaxRange_Location>>) (previousStart: ElmSyntaxRange_Location) (previousEnd: ElmSyntaxRange_Location) : Generated_End_Start<ElmSyntaxRange_Location, ElmSyntaxRange_Location> =
    match ranges with
    | [] ->
        { End = previousEnd
        ; Start = previousStart
        }

    | { End = end_; Start = start } :: rest ->
        let newStart: ElmSyntaxRange_Location =
            match ElmSyntaxRange_compareLocations start previousStart with
            | Basics_Order.LT ->
                start

            | _ ->
                previousStart
        
        let newEnd: ElmSyntaxRange_Location =
            match ElmSyntaxRange_compareLocations end_ previousEnd with
            | Basics_Order.GT ->
                end_

            | _ ->
                previousEnd
        
        ElmSyntaxRange_combineHelp rest newStart newEnd

let ElmSyntaxRange_combine (ranges: List<Generated_End_Start<ElmSyntaxRange_Location, ElmSyntaxRange_Location>>) : ElmSyntaxRange_Range =
    match ranges with
    | [] ->
        ElmSyntaxRange_empty

    | head :: tail ->
        ElmSyntaxRange_combineHelp tail head.Start head.End

