let rec ElmSyntaxPrintDefunctionalized_typeToNotParenthesized (ElmSyntaxNode_Node(typeRange, syntaxType): ElmSyntaxNode_Node<ElmSyntaxTypeAnnotation_TypeAnnotation>) : ElmSyntaxNode_Node<ElmSyntaxTypeAnnotation_TypeAnnotation> =
    match syntaxType with
    | ElmSyntaxTypeAnnotation_GenericType(name) ->
        ElmSyntaxNode_Node (struct( typeRange, ElmSyntaxTypeAnnotation_GenericType name ))

    | ElmSyntaxTypeAnnotation_Typed(reference, arguments) ->
        ElmSyntaxNode_Node (struct( typeRange, ElmSyntaxTypeAnnotation_Typed (struct( reference, arguments )) ))

    | ElmSyntaxTypeAnnotation_Unit ->
        ElmSyntaxNode_Node (struct( typeRange, ElmSyntaxTypeAnnotation_Unit ))

    | ElmSyntaxTypeAnnotation_Tupled(parts) ->
        match parts with
        | [ inParens ] ->
            ElmSyntaxPrintDefunctionalized_typeToNotParenthesized inParens

        | [] ->
            ElmSyntaxNode_Node (struct( typeRange, ElmSyntaxTypeAnnotation_Unit ))

        | [ part0; part1 ] ->
            ElmSyntaxNode_Node
                (struct(
                  typeRange
                , ElmSyntaxTypeAnnotation_Tupled
                    [ part0;
                      part1
                    ]
                ))

        | [ part0; part1; part2 ] ->
            ElmSyntaxNode_Node
                (struct(
                  typeRange
                , ElmSyntaxTypeAnnotation_Tupled
                    [ part0;
                      part1;
                      part2
                    ]
                ))

        | part0 :: (part1 :: (part2 :: (part3 :: part4Up))) ->
            ElmSyntaxNode_Node (struct( typeRange, ElmSyntaxTypeAnnotation_Tupled (List_cons part0 (List_cons part1 (List_cons part2 (List_cons part3 part4Up)))) ))

    | ElmSyntaxTypeAnnotation_Record(fields) ->
        ElmSyntaxNode_Node (struct( typeRange, ElmSyntaxTypeAnnotation_Record fields ))

    | ElmSyntaxTypeAnnotation_GenericRecord(extendedRecordVariableName, additionalFieldsNode) ->
        ElmSyntaxNode_Node (struct( typeRange, ElmSyntaxTypeAnnotation_GenericRecord (struct( extendedRecordVariableName, additionalFieldsNode )) ))

    | ElmSyntaxTypeAnnotation_FunctionTypeAnnotation(inType, outType) ->
        ElmSyntaxNode_Node (struct( typeRange, ElmSyntaxTypeAnnotation_FunctionTypeAnnotation (struct( inType, outType )) ))

let rec ElmSyntaxPrintDefunctionalized_typeIsSpaceSeparated (syntaxType: ElmSyntaxTypeAnnotation_TypeAnnotation) : bool =
    match syntaxType with
    | ElmSyntaxTypeAnnotation_GenericType(_) ->
        false

    | ElmSyntaxTypeAnnotation_Typed(_, arguments) ->
        match arguments with
        | [] ->
            false

        | _ :: _ ->
            true

    | ElmSyntaxTypeAnnotation_Unit ->
        false

    | ElmSyntaxTypeAnnotation_Tupled(parts) ->
        match parts with
        | [] ->
            false

        | [ ElmSyntaxNode_Node(_, inParens) ] ->
            ElmSyntaxPrintDefunctionalized_typeIsSpaceSeparated inParens

        | [ _; _ ] ->
            false

        | [ _; _; _ ] ->
            false

        | _ :: (_ :: (_ :: (_ :: _))) ->
            false

    | ElmSyntaxTypeAnnotation_Record(_) ->
        false

    | ElmSyntaxTypeAnnotation_GenericRecord(_, _) ->
        false

    | ElmSyntaxTypeAnnotation_FunctionTypeAnnotation(_, _) ->
        true

let rec ElmSyntaxPrintDefunctionalized_typeFunctionExpand (typeNode: ElmSyntaxNode_Node<ElmSyntaxTypeAnnotation_TypeAnnotation>) : Generated_BeforeRightest_Rightest<List<ElmSyntaxNode_Node<ElmSyntaxTypeAnnotation_TypeAnnotation>>, ElmSyntaxNode_Node<ElmSyntaxTypeAnnotation_TypeAnnotation>> =
    match typeNode with
    | ElmSyntaxNode_Node(_, ElmSyntaxTypeAnnotation_FunctionTypeAnnotation(inType, outType)) ->
        let outTypeExpanded: Generated_BeforeRightest_Rightest<List<ElmSyntaxNode_Node<ElmSyntaxTypeAnnotation_TypeAnnotation>>, ElmSyntaxNode_Node<ElmSyntaxTypeAnnotation_TypeAnnotation>> =
            ElmSyntaxPrintDefunctionalized_typeFunctionExpand outType
        
        { BeforeRightest = List_cons inType outTypeExpanded.BeforeRightest
        ; Rightest = outTypeExpanded.Rightest
        }

    | typeNodeNotFunction ->
        { BeforeRightest = []
        ; Rightest = typeNodeNotFunction
        }

let ElmSyntaxPrintDefunctionalized_stringUnicodeLength (string_: StringRope) : int64 =
