let rec ElmSyntaxPrintDefunctionalized_patternToNotParenthesized (ElmSyntaxNode_Node(fullRange, syntaxPattern): ElmSyntaxNode_Node<ElmSyntaxPattern_Pattern>) : ElmSyntaxNode_Node<ElmSyntaxPattern_Pattern> =
    match syntaxPattern with
    | ElmSyntaxPattern_ParenthesizedPattern(inParens) ->
        ElmSyntaxPrintDefunctionalized_patternToNotParenthesized inParens

    | ElmSyntaxPattern_TuplePattern(parts) ->
        match parts with
        | [ inParens ] ->
            ElmSyntaxPrintDefunctionalized_patternToNotParenthesized inParens

        | [ part0; part1 ] ->
            ElmSyntaxNode_Node
                (struct(
                  fullRange
                , ElmSyntaxPattern_TuplePattern
                    [ part0;
                      part1
                    ]
                ))

        | [ part0; part1; part2 ] ->
            ElmSyntaxNode_Node
                (struct(
                  fullRange
                , ElmSyntaxPattern_TuplePattern
                    [ part0;
                      part1;
                      part2
                    ]
                ))

        | [] ->
            ElmSyntaxNode_Node (struct( fullRange, ElmSyntaxPattern_UnitPattern ))

        | part0 :: (part1 :: (part2 :: (part3 :: part4Up))) ->
            ElmSyntaxNode_Node (struct( fullRange, ElmSyntaxPattern_TuplePattern (List_cons part0 (List_cons part1 (List_cons part2 (List_cons part3 part4Up)))) ))

    | ElmSyntaxPattern_AllPattern ->
        ElmSyntaxNode_Node (struct( fullRange, ElmSyntaxPattern_AllPattern ))

    | ElmSyntaxPattern_UnitPattern ->
        ElmSyntaxNode_Node (struct( fullRange, ElmSyntaxPattern_UnitPattern ))

    | ElmSyntaxPattern_VarPattern(name) ->
        ElmSyntaxNode_Node (struct( fullRange, ElmSyntaxPattern_VarPattern name ))

    | ElmSyntaxPattern_CharPattern(char_) ->
        ElmSyntaxNode_Node (struct( fullRange, ElmSyntaxPattern_CharPattern char_ ))

    | ElmSyntaxPattern_StringPattern(string_) ->
        ElmSyntaxNode_Node (struct( fullRange, ElmSyntaxPattern_StringPattern string_ ))

    | ElmSyntaxPattern_IntPattern(int_) ->
        ElmSyntaxNode_Node (struct( fullRange, ElmSyntaxPattern_IntPattern int_ ))

    | ElmSyntaxPattern_HexPattern(int_) ->
        ElmSyntaxNode_Node (struct( fullRange, ElmSyntaxPattern_HexPattern int_ ))

    | ElmSyntaxPattern_FloatPattern(float_) ->
        ElmSyntaxNode_Node (struct( fullRange, ElmSyntaxPattern_FloatPattern float_ ))

    | ElmSyntaxPattern_RecordPattern(fields) ->
        ElmSyntaxNode_Node (struct( fullRange, ElmSyntaxPattern_RecordPattern fields ))

    | ElmSyntaxPattern_UnConsPattern(headPattern, tailPattern) ->
        ElmSyntaxNode_Node (struct( fullRange, ElmSyntaxPattern_UnConsPattern (struct( headPattern, tailPattern )) ))

    | ElmSyntaxPattern_ListPattern(elementPatterns) ->
        ElmSyntaxNode_Node (struct( fullRange, ElmSyntaxPattern_ListPattern elementPatterns ))

    | ElmSyntaxPattern_NamedPattern(syntaxQualifiedNameRef, argumentPatterns) ->
        ElmSyntaxNode_Node (struct( fullRange, ElmSyntaxPattern_NamedPattern (struct( syntaxQualifiedNameRef, argumentPatterns )) ))

    | ElmSyntaxPattern_AsPattern(aliasedPattern, aliasNameNode) ->
        ElmSyntaxNode_Node (struct( fullRange, ElmSyntaxPattern_AsPattern (struct( aliasedPattern, aliasNameNode )) ))

let rec ElmSyntaxPrintDefunctionalized_patternIsSpaceSeparated (syntaxPattern: ElmSyntaxPattern_Pattern) : bool =
    match syntaxPattern with
    | ElmSyntaxPattern_AllPattern ->
        false

    | ElmSyntaxPattern_UnitPattern ->
        false

    | ElmSyntaxPattern_VarPattern(_) ->
        false

    | ElmSyntaxPattern_CharPattern(_) ->
        false

    | ElmSyntaxPattern_StringPattern(_) ->
        false

    | ElmSyntaxPattern_IntPattern(_) ->
        false

    | ElmSyntaxPattern_HexPattern(_) ->
        false

    | ElmSyntaxPattern_FloatPattern(_) ->
        false

    | ElmSyntaxPattern_ParenthesizedPattern(ElmSyntaxNode_Node(_, inParens)) ->
        ElmSyntaxPrintDefunctionalized_patternIsSpaceSeparated inParens

    | ElmSyntaxPattern_TuplePattern(parts) ->
        match parts with
        | [ ElmSyntaxNode_Node(_, inParens) ] ->
            ElmSyntaxPrintDefunctionalized_patternIsSpaceSeparated inParens

        | [] ->
            false

        | [ _; _ ] ->
            false

        | [ _; _; _ ] ->
            false

        | _ :: (_ :: (_ :: (_ :: _))) ->
            false

    | ElmSyntaxPattern_RecordPattern(_) ->
        false

    | ElmSyntaxPattern_UnConsPattern(_, _) ->
        true

    | ElmSyntaxPattern_ListPattern(_) ->
        false

    | ElmSyntaxPattern_NamedPattern(_, argumentPatterns) ->
        match argumentPatterns with
        | [] ->
            false

        | _ :: _ ->
            true

    | ElmSyntaxPattern_AsPattern(_, _) ->
        true

let rec ElmSyntaxPrintDefunctionalized_patternConsExpand (ElmSyntaxNode_Node(fulRange, syntaxPattern): ElmSyntaxNode_Node<ElmSyntaxPattern_Pattern>) : List<ElmSyntaxNode_Node<ElmSyntaxPattern_Pattern>> =
    match syntaxPattern with
    | ElmSyntaxPattern_UnConsPattern(headPattern, tailPattern) ->
        List_cons headPattern (ElmSyntaxPrintDefunctionalized_patternConsExpand tailPattern)

    | ElmSyntaxPattern_AllPattern ->
        [ ElmSyntaxNode_Node (struct( fulRange, ElmSyntaxPattern_AllPattern )) ]

    | ElmSyntaxPattern_UnitPattern ->
        [ ElmSyntaxNode_Node (struct( fulRange, ElmSyntaxPattern_UnitPattern )) ]

    | ElmSyntaxPattern_CharPattern(char_) ->
        [ ElmSyntaxNode_Node (struct( fulRange, ElmSyntaxPattern_CharPattern char_ )) ]

    | ElmSyntaxPattern_StringPattern(string_) ->
        [ ElmSyntaxNode_Node (struct( fulRange, ElmSyntaxPattern_StringPattern string_ )) ]

    | ElmSyntaxPattern_IntPattern(int_) ->
        [ ElmSyntaxNode_Node (struct( fulRange, ElmSyntaxPattern_IntPattern int_ )) ]

    | ElmSyntaxPattern_HexPattern(int_) ->
        [ ElmSyntaxNode_Node (struct( fulRange, ElmSyntaxPattern_HexPattern int_ )) ]

    | ElmSyntaxPattern_FloatPattern(float_) ->
        [ ElmSyntaxNode_Node (struct( fulRange, ElmSyntaxPattern_FloatPattern float_ )) ]

    | ElmSyntaxPattern_TuplePattern(parts) ->
        match parts with
        | [ part0; part1 ] ->
            [ ElmSyntaxNode_Node
                (struct(
                  fulRange
                , ElmSyntaxPattern_TuplePattern
                    [ part0;
                      part1
                    ]
                ))
            ]

        | [ part0; part1; part2 ] ->
            [ ElmSyntaxNode_Node
                (struct(
                  fulRange
                , ElmSyntaxPattern_TuplePattern
                    [ part0;
                      part1;
                      part2
                    ]
                ))
            ]

        | [] ->
            [ ElmSyntaxNode_Node (struct( fulRange, ElmSyntaxPattern_UnitPattern )) ]

        | [ inParens ] ->
            [ ElmSyntaxNode_Node (struct( fulRange, ElmSyntaxPattern_TuplePattern [ inParens ] )) ]

        | part0 :: (part1 :: (part2 :: (part3 :: part4Up))) ->
            [ ElmSyntaxNode_Node (struct( fulRange, ElmSyntaxPattern_TuplePattern (List_cons part0 (List_cons part1 (List_cons part2 (List_cons part3 part4Up)))) )) ]

    | ElmSyntaxPattern_RecordPattern(fields) ->
        [ ElmSyntaxNode_Node (struct( fulRange, ElmSyntaxPattern_RecordPattern fields )) ]

    | ElmSyntaxPattern_ListPattern(elements) ->
        [ ElmSyntaxNode_Node (struct( fulRange, ElmSyntaxPattern_ListPattern elements )) ]

    | ElmSyntaxPattern_VarPattern(variableName) ->
        [ ElmSyntaxNode_Node (struct( fulRange, ElmSyntaxPattern_VarPattern variableName )) ]

    | ElmSyntaxPattern_NamedPattern(reference, parameters) ->
        [ ElmSyntaxNode_Node (struct( fulRange, ElmSyntaxPattern_NamedPattern (struct( reference, parameters )) )) ]

    | ElmSyntaxPattern_AsPattern(aliasedPattern, aliasName) ->
        [ ElmSyntaxNode_Node (struct( fulRange, ElmSyntaxPattern_AsPattern (struct( aliasedPattern, aliasName )) )) ]

    | ElmSyntaxPattern_ParenthesizedPattern(inParens) ->
        [ ElmSyntaxNode_Node (struct( fulRange, ElmSyntaxPattern_ParenthesizedPattern inParens )) ]

