let ElmSyntaxPrintDefunctionalized_moduleLevelMultiLneCommentWithoutWhitespace: Print_Print =
    Print_followedBy Print_linebreak (Print_followedBy ElmSyntaxPrintDefunctionalized_printExactlyCurlyOpeningDotDotCurlyClosing ElmSyntaxPrintDefunctionalized_printLinebreakLinebreak)

let ElmSyntaxPrintDefunctionalized_moduleDocumentationParse (moduleDocumentationContent: StringRope) : Generated_RawAfterAtDocsLines_WhileAtDocsLines<StringRope, List<Generated_AtDocsLine_RawBefore<List<StringRope>, StringRope>>> =
    let parsed: Generated_FinishedBlocks_RawSinceAtDocs<List<Generated_AtDocsLine_RawBefore<List<StringRope>, StringRope>>, StringRope> =
        List_foldl
            (fun (line: StringRope) (soFar: Generated_FinishedBlocks_RawSinceAtDocs<List<Generated_AtDocsLine_RawBefore<List<StringRope>, StringRope>>, StringRope>) ->
                if String_startsWith (StringRopeOne "@docs ") line then
                    { FinishedBlocks =
                        List_cons
                            { AtDocsLine = List.map String_trim (String_split (StringRopeOne ",") (String_slice 6L (String_length line) line))
                            ; RawBefore = soFar.RawSinceAtDocs
                            }
                            soFar.FinishedBlocks
                    ; RawSinceAtDocs = StringRopeOne ""
                    }

                else
                    match line with
                    | StringRopeOne("@docs") ->
                        { FinishedBlocks =
                            List_cons
                                { AtDocsLine = []
                                ; RawBefore = soFar.RawSinceAtDocs
                                }
                                soFar.FinishedBlocks
                        ; RawSinceAtDocs = StringRopeOne ""
                        }

                    | _ ->
                        { FinishedBlocks = soFar.FinishedBlocks
                        ; RawSinceAtDocs = String_append soFar.RawSinceAtDocs (String_append line (StringRopeOne "\n"))
                        }
            )
            ElmSyntaxPrintDefunctionalized_rawSinceAtDocsEmptyFinishedBlocksEmpty
            (String_lines (String_trimLeft (String_slice 3L ((-) (String_length moduleDocumentationContent) 2L) moduleDocumentationContent)))
    
    { RawAfterAtDocsLines = parsed.RawSinceAtDocs
    ; WhileAtDocsLines = List.rev parsed.FinishedBlocks
    }

let rec ElmSyntaxPrintDefunctionalized_moduleDocumentationBeforeCutOffLine (cutOffLine: int64) (allComments: List<ElmSyntaxNode_Node<StringRope>>) : ValueOption<ElmSyntaxNode_Node<StringRope>> =
    match allComments with
    | [] ->
        ValueNone

    | headComment :: restOfComments ->
        let (ElmSyntaxNode_Node(range, content): ElmSyntaxNode_Node<StringRope>) =
            headComment
        
        if (>) range.Start.Row cutOffLine then
            ValueNone

        else
            if String_startsWith (StringRopeOne "{-|") content then
                ValueSome headComment

            else
                ElmSyntaxPrintDefunctionalized_moduleDocumentationBeforeCutOffLine cutOffLine restOfComments

let ElmSyntaxPrintDefunctionalized_moduleDocumentation (ast: Generated_Comments_Declarations_Imports_ModuleDefinition<List<ElmSyntaxNode_Node<ElmSyntaxComments_Comment>>, List<ElmSyntaxNode_Node<ElmSyntaxDeclaration_Declaration>>, List<ElmSyntaxNode_Node<ElmSyntaxImport_Import>>, ElmSyntaxNode_Node<ElmSyntaxModule_Module>>) : ValueOption<ElmSyntaxNode_Node<StringRope>> =
    let cutOffLine: int64 =
        match ast.Imports with
        | ElmSyntaxNode_Node(firstImportRange, _) :: _ ->
            firstImportRange.Start.Row

        | [] ->
            match ast.Declarations with
            | ElmSyntaxNode_Node(firstDeclarationRange, _) :: _ ->
                firstDeclarationRange.Start.Row

            | [] ->
                0L
    
    ElmSyntaxPrintDefunctionalized_moduleDocumentationBeforeCutOffLine cutOffLine ast.Comments

let ElmSyntaxPrintDefunctionalized_maybeLineSpread (valueToLineSpread: 'a -> Print_LineSpread) (maybe: ValueOption<'a>) : Print_LineSpread =
    match maybe with
    | ValueNone ->
        Print_SingleLine

    | ValueSome(value) ->
        valueToLineSpread value

let ElmSyntaxPrintDefunctionalized_locationCompareFast (left: Generated_Column_Row<int64, int64>) (right: Generated_Column_Row<int64, int64>) : Basics_Order =
    if (<) ((-) left.Row right.Row) 0L then
        Basics_Order.LT

    else
        if (>) ((-) left.Row right.Row) 0L then
            Basics_Order.GT

        else
            Basics_compare left.Column right.Column

let ElmSyntaxPrintDefunctionalized_listMapAndIntersperseAndFlattenToString (elementToString: 'a -> StringRope) (betweenElements: StringRope) (elements: List<'a>) : StringRope =
    match elements with
    | [] ->
        StringRopeOne ""

    | head :: tail ->
        List_foldl
            (fun (next: 'a) (soFar: StringRope) ->
                String_append soFar (String_append betweenElements (elementToString next))
            )
            (elementToString head)
            tail

let ElmSyntaxPrintDefunctionalized_listMapAndFlattenToString (elementToString: 'a -> StringRope) (elements: List<'a>) : StringRope =
    List_foldl
        (fun (next: 'a) (soFar: StringRope) ->
            String_append soFar (elementToString next)
        )
        (StringRopeOne "")
        elements

let ElmSyntaxPrintDefunctionalized_printModuleDocumentation (moduleDocumentationBlocks: Generated_RawAfterAtDocsLines_WhileAtDocsLines<StringRope, List<Generated_AtDocsLine_RawBefore<List<StringRope>, StringRope>>>) : Print_Print =
    let content: StringRope =
        String_trimRight
            (String_append
                (ElmSyntaxPrintDefunctionalized_listMapAndFlattenToString
                    (fun (atDocsLineAndBefore: Generated_AtDocsLine_RawBefore<List<StringRope>, StringRope>) ->
                        String_append
                            atDocsLineAndBefore.RawBefore
                            (match atDocsLineAndBefore.AtDocsLine with
                             | [] ->
                                StringRopeOne ""

                             | atDocsExpose0 :: atDocsExpose1Up ->
                                String_append (StringRopeOne "@docs ") (String_append (String_join (StringRopeOne ", ") (List_cons atDocsExpose0 atDocsExpose1Up)) (StringRopeOne "\n"))
                            )
                    )
                    moduleDocumentationBlocks.WhileAtDocsLines
                )
                moduleDocumentationBlocks.RawAfterAtDocsLines
            )
    
    Print_exactly
        (String_append
            (StringRopeOne "{-|")
            (String_append
                (if String_startsWith (StringRopeOne "@docs ") content then
                    StringRopeOne "\n\n"

                 else
                    StringRopeOne " "
                )
                (String_append
                    content
                    (if String_contains (StringRopeOne "\n") content then
                        StringRopeOne "\n\n-}"

                     else
                        StringRopeOne "\n-}"
                    )
                )
            )
        )

let ElmSyntaxPrintDefunctionalized_qualifiedReference (syntaxReference: Generated_Qualification_Unqualified<List<StringRope>, StringRope>) : StringRope =
    match syntaxReference.Qualification with
    | [] ->
        syntaxReference.Unqualified

    | modulePartHead :: modulePartTail ->
        String_append
            modulePartHead
            (String_append
                (ElmSyntaxPrintDefunctionalized_listMapAndFlattenToString
                    (fun (modulePart: StringRope) ->
                        String_append (StringRopeOne ".") modulePart
                    )
                    modulePartTail
                )
                (String_append (StringRopeOne ".") syntaxReference.Unqualified)
            )

