let rec ElmSyntaxPrintDefunctionalized_listDropLastIfEmpty (list_: List<StringRope>) : List<StringRope> =
    match list_ with
    | [] ->
        []

    | [ onlyElement ] ->
        match String_trim onlyElement with
        | StringRopeOne("") ->
            []

        | _ ->
            [ onlyElement ]

    | element0 :: (element1 :: element2Up) ->
        List_cons element0 (ElmSyntaxPrintDefunctionalized_listDropLastIfEmpty (List_cons element1 element2Up))

