let ElmSyntaxPrintDefunctionalized_printDocumentationComment (documentationCommentIncludingOpeningAndClosingTokens: StringRope) : Print_Print =
    let contentLines: List<StringRope> =
        List.map String_trimRight (String_lines (String_trim (String_dropRight 2L (String_dropLeft 3L documentationCommentIncludingOpeningAndClosingTokens))))
    
    if List.forall String_isEmpty contentLines then
        ElmSyntaxPrintDefunctionalized_printDocumentationCommentEmpty

    else
        Print_followedBy
            (if List.exists String_isEmpty contentLines then
                ElmSyntaxPrintDefunctionalized_linebreakFollowedByLinebreakFollowedByMinusCurlyBraceClosing

             else
                ElmSyntaxPrintDefunctionalized_linebreakFollowedByMinusCurlyBraceClosing
            )
            (Print_followedBy (Print_listMapAndIntersperseAndFlatten Print_exactly Print_linebreak contentLines) ElmSyntaxPrintDefunctionalized_printExactlyCurlyBraceOpeningMinusVerticalBar)

