let ElmSyntaxPrintDefunctionalized_lineIndentation (line: StringRope) : int64 =
    (String_foldl
        (fun (char_: int) (soFar: Generated_OnlySpaces_SpaceCount<bool, int64>) ->
            if soFar.OnlySpaces then
                match char_ with
                | 32 ->
                    { OnlySpaces = true
                    ; SpaceCount = (+) soFar.SpaceCount 1L
                    }

                | _ ->
                    { OnlySpaces = false
                    ; SpaceCount = soFar.SpaceCount
                    }

            else
                soFar
        )
        ElmSyntaxPrintDefunctionalized_spaceCount0OnlySpacesTrue
        line
    ).SpaceCount

let ElmSyntaxPrintDefunctionalized_linesUnindentAndTrimRight (lines: List<StringRope>) : List<StringRope> =
    let nonBlankLinesIndentationMinimum: ValueOption<int64> =
        List_foldl
            (fun (line: StringRope) (soFarMinimumIndentationOrNothing: ValueOption<int64>) ->
                match String_trim line with
                | StringRopeOne("") ->
                    soFarMinimumIndentationOrNothing

                | _ ->
                    let currentLineIndentation: int64 =
                        ElmSyntaxPrintDefunctionalized_lineIndentation line
                    
                    ValueSome
                        (match soFarMinimumIndentationOrNothing with
                         | ValueNone ->
                            currentLineIndentation

                         | ValueSome(soFarMinimumIndentation) ->
                            min soFarMinimumIndentation currentLineIndentation
                        )
            )
            ValueNone
            lines
    
    match nonBlankLinesIndentationMinimum with
    | ValueNone ->
        List.map
            (fun (_: StringRope) ->
                StringRopeOne ""
            )
            lines

    | ValueSome(minimumIndentation) ->
        List.map
            (fun (line: StringRope) ->
                String_trimRight (String_dropLeft minimumIndentation line)
            )
            lines

let ElmSyntaxPrintDefunctionalized_invalidNTuple (printPartNotParenthesized: 'b -> 'a -> Print_Print) (syntaxComments: 'b) (syntaxTuple: Generated_FullRange_Part0_Part1_Part2_Part3_Part4Up<ElmSyntaxRange_Range, 'a, 'a, 'a, 'a, List<'a>>) : Print_Print =
