                    (fun (part: 'a) ->
                        Print_withIndentIncreasedBy 2L (printPartNotParenthesized syntaxComments part)
                    )
                    (Print_followedBy ElmSyntaxPrintDefunctionalized_printExactlyCommaSpace (Print_emptyOrLinebreakIndented lineSpread))
                    (List_cons syntaxTuple.Part0 (List_cons syntaxTuple.Part1 (List_cons syntaxTuple.Part2 (List_cons syntaxTuple.Part3 syntaxTuple.Part4Up))))
