let rec ElmSyntaxPrintDefunctionalized_intToHexString (int_: int64) : StringRope =
    if (<) int_ 16L then
        ElmSyntaxPrintDefunctionalized_unsafeHexDigitIntToString int_

    else
        String_append (ElmSyntaxPrintDefunctionalized_intToHexString ((/) int_ 16L)) (ElmSyntaxPrintDefunctionalized_unsafeHexDigitIntToString (Basics_remainderBy 16L int_))

let ElmSyntaxPrintDefunctionalized_intLiteral: int64 -> StringRope =
    String_fromInt

let ElmSyntaxPrintDefunctionalized_infixDirection (syntaxInfixDirection: ElmSyntaxInfix_InfixDirection) : StringRope =
    match syntaxInfixDirection with
    | ElmSyntaxInfix_Left ->
        StringRopeOne "left "

    | ElmSyntaxInfix_Right ->
        StringRopeOne "right"

    | ElmSyntaxInfix_Non ->
        StringRopeOne "non  "

let ElmSyntaxPrintDefunctionalized_hexLiteral (int_: int64) : StringRope =
    let maybeSignPrint: StringRope =
        if (<) int_ 0L then
            StringRopeOne "-"

        else
            StringRopeOne ""
    
    let intAbs: int64 =
        System.Int64.Abs int_
    
    let digitCountToPrint: int64 =
        if (<=) intAbs 255L then
            2L

        else
            if (<=) intAbs 65535L then
                4L

            else
                if (<=) intAbs 4294967295L then
                    8L

                else
                    16L
    
    String_append maybeSignPrint (String_append (StringRopeOne "0x") (ElmSyntaxPrintDefunctionalized_stringResizePadLeftWith0s digitCountToPrint (ElmSyntaxPrintDefunctionalized_intToHexString int_)))

let ElmSyntaxPrintDefunctionalized_floatLiteral (float_: float) : StringRope =
    if Basics_eq (float (int64 float_)) float_ then
        String_append (String_fromFloat float_) (StringRopeOne ".0")

    else
        String_fromFloat float_

let rec ElmSyntaxPrintDefunctionalized_firstCommentInRange (range: Generated_End_Start<ElmSyntaxRange_Location, ElmSyntaxRange_Location>) (sortedComments: List<ElmSyntaxNode_Node<StringRope>>) : ValueOption<ElmSyntaxNode_Node<StringRope>> =
