                ValueSome (ElmSyntaxNode_Node (struct( headCommentRange, headComment )))

let rec ElmSyntaxPrintDefunctionalized_expressionToNotParenthesized (ElmSyntaxNode_Node(fullRange, syntaxExpression): ElmSyntaxNode_Node<ElmSyntaxExpression_Expression>) : ElmSyntaxNode_Node<ElmSyntaxExpression_Expression> =
    match syntaxExpression with
    | ElmSyntaxExpression_ParenthesizedExpression(inParens) ->
        ElmSyntaxPrintDefunctionalized_expressionToNotParenthesized inParens

    | ElmSyntaxExpression_TupledExpression(parts) ->
        match parts with
        | [ inParens ] ->
            ElmSyntaxPrintDefunctionalized_expressionToNotParenthesized inParens

        | [] ->
            ElmSyntaxNode_Node (struct( fullRange, ElmSyntaxExpression_UnitExpr ))

        | [ part0; part1 ] ->
            ElmSyntaxNode_Node
                (struct(
                  fullRange
                , ElmSyntaxExpression_TupledExpression
                    [ part0;
                      part1
                    ]
                ))

        | [ part0; part1; part2 ] ->
            ElmSyntaxNode_Node
                (struct(
                  fullRange
                , ElmSyntaxExpression_TupledExpression
                    [ part0;
                      part1;
                      part2
                    ]
                ))

        | part0 :: (part1 :: (part2 :: (part3 :: part4Up))) ->
            ElmSyntaxNode_Node (struct( fullRange, ElmSyntaxExpression_TupledExpression (List_cons part0 (List_cons part1 (List_cons part2 (List_cons part3 part4Up)))) ))

    | syntaxExpressionNotParenthesized ->
        ElmSyntaxNode_Node (struct( fullRange, syntaxExpressionNotParenthesized ))

let rec ElmSyntaxPrintDefunctionalized_expressionOperationExpand (left: ElmSyntaxNode_Node<ElmSyntaxExpression_Expression>) (operator: StringRope) (right: ElmSyntaxNode_Node<ElmSyntaxExpression_Expression>) : Generated_BeforeRightestOperatorExpressionChain_Leftest_RightestExpression_RightestOperator<List<Generated_Expression_Operator<ElmSyntaxNode_Node<ElmSyntaxExpression_Expression>, StringRope>>, ElmSyntaxNode_Node<ElmSyntaxExpression_Expression>, ElmSyntaxNode_Node<ElmSyntaxExpression_Expression>, StringRope> =
