        match right with
        | ElmSyntaxNode_Node(_, ElmSyntaxExpression_OperatorApplication(rightOperator, _, rightLeft, rightRight)) ->
            let rightOperationExpanded: Generated_BeforeRightestOperatorExpressionChain_Leftest_RightestExpression_RightestOperator<List<Generated_Expression_Operator<ElmSyntaxNode_Node<ElmSyntaxExpression_Expression>, StringRope>>, ElmSyntaxNode_Node<ElmSyntaxExpression_Expression>, ElmSyntaxNode_Node<ElmSyntaxExpression_Expression>, StringRope> =
                ElmSyntaxPrintDefunctionalized_expressionOperationExpand rightLeft rightOperator rightRight
            
            { BeforeRightestOperatorExpressionChain =
                List_cons
                    { Expression = rightOperationExpanded.Leftest
                    ; Operator = operator
                    }
                    rightOperationExpanded.BeforeRightestOperatorExpressionChain
            ; RightestExpression = rightOperationExpanded.RightestExpression
            ; RightestOperator = rightOperationExpanded.RightestOperator
            }

        | rightNotOperation ->
            { BeforeRightestOperatorExpressionChain = []
            ; RightestExpression = rightNotOperation
            ; RightestOperator = operator
            }
    
    match left with
    | ElmSyntaxNode_Node(_, ElmSyntaxExpression_OperatorApplication(leftOperator, _, leftLeft, leftRight)) ->
        let leftOperationExpanded: Generated_BeforeRightestOperatorExpressionChain_Leftest_RightestExpression_RightestOperator<List<Generated_Expression_Operator<ElmSyntaxNode_Node<ElmSyntaxExpression_Expression>, StringRope>>, ElmSyntaxNode_Node<ElmSyntaxExpression_Expression>, ElmSyntaxNode_Node<ElmSyntaxExpression_Expression>, StringRope> =
            ElmSyntaxPrintDefunctionalized_expressionOperationExpand leftLeft leftOperator leftRight
        
        { BeforeRightestOperatorExpressionChain =
            List.append
                leftOperationExpanded.BeforeRightestOperatorExpressionChain
                (List_cons
                    { Expression = leftOperationExpanded.RightestExpression
                    ; Operator = leftOperationExpanded.RightestOperator
                    }
                    rightExpanded.BeforeRightestOperatorExpressionChain
                )
        ; Leftest = leftOperationExpanded.Leftest
        ; RightestExpression = rightExpanded.RightestExpression
        ; RightestOperator = rightExpanded.RightestOperator
        }

    | leftNotOperation ->
        { BeforeRightestOperatorExpressionChain = rightExpanded.BeforeRightestOperatorExpressionChain
        ; Leftest = leftNotOperation
        ; RightestExpression = rightExpanded.RightestExpression
        ; RightestOperator = rightExpanded.RightestOperator
        }

let rec ElmSyntaxPrintDefunctionalized_expressionIsSpaceSeparated (syntaxExpression: ElmSyntaxExpression_Expression) : bool =
    match syntaxExpression with
    | ElmSyntaxExpression_UnitExpr ->
        false

    | ElmSyntaxExpression_Application(application) ->
        match application with
        | [] ->
            false

        | [ ElmSyntaxNode_Node(_, notActuallyApplied) ] ->
            ElmSyntaxPrintDefunctionalized_expressionIsSpaceSeparated notActuallyApplied

        | _ :: (_ :: _) ->
            true

    | ElmSyntaxExpression_OperatorApplication(_, _, _, _) ->
        true

    | ElmSyntaxExpression_FunctionOrValue(_, _) ->
        false

    | ElmSyntaxExpression_IfBlock(_, _, _) ->
        true

    | ElmSyntaxExpression_PrefixOperator(_) ->
        false

    | ElmSyntaxExpression_Operator(_) ->
        false

    | ElmSyntaxExpression_Integer(_) ->
        false

    | ElmSyntaxExpression_Hex(_) ->
        false

    | ElmSyntaxExpression_Floatable(_) ->
        false

    | ElmSyntaxExpression_Negation(_) ->
        false

    | ElmSyntaxExpression_Literal(_) ->
        false

    | ElmSyntaxExpression_CharLiteral(_) ->
        false

    | ElmSyntaxExpression_TupledExpression(parts) ->
        match parts with
        | [] ->
            false

        | [ ElmSyntaxNode_Node(_, inParens) ] ->
            ElmSyntaxPrintDefunctionalized_expressionIsSpaceSeparated inParens

        | [ _; _ ] ->
            false

        | [ _; _; _ ] ->
            false

        | _ :: (_ :: (_ :: (_ :: _))) ->
            false

    | ElmSyntaxExpression_ParenthesizedExpression(ElmSyntaxNode_Node(_, inParens)) ->
        ElmSyntaxPrintDefunctionalized_expressionIsSpaceSeparated inParens

    | ElmSyntaxExpression_LetExpression(_) ->
        true

    | ElmSyntaxExpression_CaseExpression(_) ->
        true

    | ElmSyntaxExpression_LambdaExpression(_) ->
        true

    | ElmSyntaxExpression_RecordExpr(_) ->
        false

    | ElmSyntaxExpression_ListExpr(_) ->
        false

    | ElmSyntaxExpression_RecordAccess(_, _) ->
        false

    | ElmSyntaxExpression_RecordAccessFunction(_) ->
        false

    | ElmSyntaxExpression_RecordUpdateExpression(_, _) ->
        false

    | ElmSyntaxExpression_GLSLExpression(_) ->
        false

