let ElmSyntaxPrintDefunctionalized_exposeMerge (a: ElmSyntaxExposing_TopLevelExpose) (b: ElmSyntaxExposing_TopLevelExpose) : ElmSyntaxExposing_TopLevelExpose =
    match a with
    | ElmSyntaxExposing_TypeExpose(aTypeExpose) ->
        match b with
        | ElmSyntaxExposing_TypeExpose(bTypeExpose) ->
            ElmSyntaxExposing_TypeExpose
                { Name = aTypeExpose.Name
                ; Open =
                    match aTypeExpose.Open with
                    | ValueSome(openRange) ->
                        ValueSome openRange

                    | ValueNone ->
                        bTypeExpose.Open
                }

        | ElmSyntaxExposing_InfixExpose(_) ->
            ElmSyntaxExposing_TypeExpose aTypeExpose

        | ElmSyntaxExposing_FunctionExpose(_) ->
            ElmSyntaxExposing_TypeExpose aTypeExpose

        | ElmSyntaxExposing_TypeOrAliasExpose(_) ->
            ElmSyntaxExposing_TypeExpose aTypeExpose

    | ElmSyntaxExposing_InfixExpose(_) ->
        b

    | ElmSyntaxExposing_FunctionExpose(_) ->
        b

    | ElmSyntaxExposing_TypeOrAliasExpose(_) ->
        b

let ElmSyntaxPrintDefunctionalized_exposeCompare (a: ElmSyntaxExposing_TopLevelExpose) (b: ElmSyntaxExposing_TopLevelExpose) : Basics_Order =
    match a with
    | ElmSyntaxExposing_InfixExpose(aOperatorSymbol) ->
        match b with
        | ElmSyntaxExposing_InfixExpose(bOperatorSymbol) ->
            Basics_compare aOperatorSymbol bOperatorSymbol

        | ElmSyntaxExposing_FunctionExpose(_) ->
            Basics_Order.LT

        | ElmSyntaxExposing_TypeOrAliasExpose(_) ->
            Basics_Order.LT

        | ElmSyntaxExposing_TypeExpose(_) ->
            Basics_Order.LT

    | ElmSyntaxExposing_FunctionExpose(aName) ->
        match b with
        | ElmSyntaxExposing_InfixExpose(_) ->
            Basics_Order.GT

        | ElmSyntaxExposing_FunctionExpose(bName) ->
            Basics_compare aName bName

        | ElmSyntaxExposing_TypeOrAliasExpose(_) ->
            Basics_Order.GT

        | ElmSyntaxExposing_TypeExpose(_) ->
            Basics_Order.GT

    | ElmSyntaxExposing_TypeOrAliasExpose(aName) ->
        match b with
        | ElmSyntaxExposing_InfixExpose(_) ->
            Basics_Order.GT

        | ElmSyntaxExposing_FunctionExpose(_) ->
            Basics_Order.LT

        | ElmSyntaxExposing_TypeOrAliasExpose(bName) ->
            Basics_compare aName bName

        | ElmSyntaxExposing_TypeExpose(bTypeExpose) ->
            Basics_compare aName bTypeExpose.Name

    | ElmSyntaxExposing_TypeExpose(aTypeExpose) ->
        match b with
        | ElmSyntaxExposing_InfixExpose(_) ->
            Basics_Order.GT

        | ElmSyntaxExposing_FunctionExpose(_) ->
            Basics_Order.LT

        | ElmSyntaxExposing_TypeOrAliasExpose(bName) ->
            Basics_compare aTypeExpose.Name bName

        | ElmSyntaxExposing_TypeExpose(bTypeExpose) ->
            Basics_compare aTypeExpose.Name bTypeExpose.Name

let rec ElmSyntaxPrintDefunctionalized_exposesCombine (syntaxExposes: List<ElmSyntaxNode_Node<ElmSyntaxExposing_TopLevelExpose>>) : List<ElmSyntaxNode_Node<ElmSyntaxExposing_TopLevelExpose>> =
    match syntaxExposes with
    | [] ->
        []

    | [ _ ] as onlyExposeList ->
        onlyExposeList

    | expose0Node :: (expose1Node :: expose2Up) ->
        let (ElmSyntaxNode_Node(_, expose1): ElmSyntaxNode_Node<ElmSyntaxExposing_TopLevelExpose>) =
            expose1Node
        
        let (ElmSyntaxNode_Node(expose0Range, expose0): ElmSyntaxNode_Node<ElmSyntaxExposing_TopLevelExpose>) =
            expose0Node
        
        match ElmSyntaxPrintDefunctionalized_exposeCompare expose0 expose1 with
        | Basics_Order.EQ ->
            ElmSyntaxPrintDefunctionalized_exposesCombine (List_cons (ElmSyntaxNode_Node (struct( expose0Range, ElmSyntaxPrintDefunctionalized_exposeMerge expose0 expose1 ))) expose2Up)

        | Basics_Order.LT ->
            List_cons expose0Node (ElmSyntaxPrintDefunctionalized_exposesCombine (List_cons expose1Node expose2Up))

        | Basics_Order.GT ->
            List_cons expose0Node (ElmSyntaxPrintDefunctionalized_exposesCombine (List_cons expose1Node expose2Up))

let ElmSyntaxPrintDefunctionalized_exposeListToNormal (syntaxExposeList: List<ElmSyntaxNode_Node<ElmSyntaxExposing_TopLevelExpose>>) : List<ElmSyntaxNode_Node<ElmSyntaxExposing_TopLevelExpose>> =
    ElmSyntaxPrintDefunctionalized_exposesCombine
        (List_sortWith
            (fun (ElmSyntaxNode_Node(_, a): ElmSyntaxNode_Node<ElmSyntaxExposing_TopLevelExpose>) (ElmSyntaxNode_Node(_, b): ElmSyntaxNode_Node<ElmSyntaxExposing_TopLevelExpose>) ->
                ElmSyntaxPrintDefunctionalized_exposeCompare a b
