let ElmSyntaxPrintDefunctionalized_exposingCombine (a: ValueOption<ElmSyntaxNode_Node<ElmSyntaxExposing_Exposing>>) (b: ValueOption<ElmSyntaxNode_Node<ElmSyntaxExposing_Exposing>>) : ValueOption<ElmSyntaxNode_Node<ElmSyntaxExposing_Exposing>> =
    match a with
    | ValueSome(ElmSyntaxNode_Node(exposingAllRange, ElmSyntaxExposing_All(allRange))) ->
        ValueSome (ElmSyntaxNode_Node (struct( exposingAllRange, ElmSyntaxExposing_All allRange )))

    | ValueSome(ElmSyntaxNode_Node(earlierExposingExplicitRange, ElmSyntaxExposing_Explicit(earlierExposeSet))) ->
        ValueSome
            (match b with
             | ValueSome(ElmSyntaxNode_Node(exposingAllRange, ElmSyntaxExposing_All(allRange))) ->
                ElmSyntaxNode_Node (struct( exposingAllRange, ElmSyntaxExposing_All allRange ))

             | ValueSome(ElmSyntaxNode_Node(laterExposingExplicitRange, ElmSyntaxExposing_Explicit(laterExposeSet))) ->
                ElmSyntaxNode_Node
                    (struct(
                      match ElmSyntaxPrintDefunctionalized_lineSpreadInRange earlierExposingExplicitRange with
                      | Print_MultipleLines ->
                        earlierExposingExplicitRange

                      | Print_SingleLine ->
                        laterExposingExplicitRange
                    , ElmSyntaxExposing_Explicit (ElmSyntaxPrintDefunctionalized_exposeListToNormal (List.append earlierExposeSet laterExposeSet))
                    ))

             | ValueNone ->
                ElmSyntaxNode_Node (struct( earlierExposingExplicitRange, ElmSyntaxExposing_Explicit earlierExposeSet ))
            )

    | ValueNone ->
        b

