let ElmSyntaxPrintDefunctionalized_consecutiveDoubleQuoteCountResultStringEmpty: Generated_ConsecutiveDoubleQuoteCount_Result<int64, StringRope> =
    { ConsecutiveDoubleQuoteCount = 0L
    ; Result = StringRopeOne ""
    }

let ElmSyntaxPrintDefunctionalized_tripleDoubleQuotedStringEscapeDoubleQuotes (string_: StringRope) : StringRope =
    let beforeLastCharEscaped: Generated_ConsecutiveDoubleQuoteCount_Result<int64, StringRope> =
        String_foldl
            (fun (char_: int) (soFar: Generated_ConsecutiveDoubleQuoteCount_Result<int64, StringRope>) ->
                match char_ with
                | 34 ->
                    { ConsecutiveDoubleQuoteCount = (+) soFar.ConsecutiveDoubleQuoteCount 1L
                    ; Result = soFar.Result
                    }

                | firstCharNotDoubleQuote ->
                    { ConsecutiveDoubleQuoteCount = 0L
                    ; Result =
                        String_append
                            soFar.Result
                            (String_append
                                (match soFar.ConsecutiveDoubleQuoteCount with
                                 | 0L ->
                                    StringRopeOne ""

                                 | 1L ->
                                    StringRopeOne "\""

                                 | 2L ->
                                    StringRopeOne "\"\""

                                 | atLeast3ConsecutiveDoubleQuoteCount ->
                                    String_repeat atLeast3ConsecutiveDoubleQuoteCount (StringRopeOne "\\\"")
                                )
                                (String_fromChar firstCharNotDoubleQuote)
                            )
                    }
            )
            ElmSyntaxPrintDefunctionalized_consecutiveDoubleQuoteCountResultStringEmpty
            string_
    
    String_append beforeLastCharEscaped.Result (String_repeat beforeLastCharEscaped.ConsecutiveDoubleQuoteCount (StringRopeOne "\\\""))

