let ElmSyntaxPrintDefunctionalized_commentCanBePartOfCollapsible (syntaxComment: StringRope) : bool =
    match syntaxComment with
    | StringRopeOne("{--}") ->
        false

    | commentNotDirectlyClosed ->
        Basics_and (String_startsWith (StringRopeOne "{-") commentNotDirectlyClosed) (not (String_contains (StringRopeOne "\n") commentNotDirectlyClosed))

let ElmSyntaxPrintDefunctionalized_comment (syntaxComment: StringRope) : Print_Print =
    match syntaxComment with
    | StringRopeOne("{--}") ->
        ElmSyntaxPrintDefunctionalized_printExactlyCurlyOpeningDotDotCurlyClosing

    | nonDirectlyClosingMultiLineComment ->
        if String_startsWith (StringRopeOne "--") nonDirectlyClosingMultiLineComment then
            Print_exactly (String_trimRight nonDirectlyClosingMultiLineComment)

        else
            let commentContentLines: List<StringRope> =
