let rec ElmSyntaxPattern_moduleNames (p: ElmSyntaxPattern_Pattern) : List<ElmSyntaxModuleName_ModuleName> =
    match p with
    | ElmSyntaxPattern_TuplePattern(xs) ->
        List.collect
            (fun (ElmSyntaxNode_Node(_, x): ElmSyntaxNode_Node<ElmSyntaxPattern_Pattern>) ->
                ElmSyntaxPattern_moduleNames x
            )
            xs

    | ElmSyntaxPattern_RecordPattern(_) ->
        []

    | ElmSyntaxPattern_UnConsPattern(ElmSyntaxNode_Node(_, left), ElmSyntaxNode_Node(_, right)) ->
        List.append (ElmSyntaxPattern_moduleNames left) (ElmSyntaxPattern_moduleNames right)

    | ElmSyntaxPattern_ListPattern(xs) ->
        List.collect
            (fun (ElmSyntaxNode_Node(_, x): ElmSyntaxNode_Node<ElmSyntaxPattern_Pattern>) ->
                ElmSyntaxPattern_moduleNames x
            )
            xs

    | ElmSyntaxPattern_NamedPattern(qualifiedNameRef, subPatterns) ->
        List_cons
            qualifiedNameRef.ModuleName
            (List.collect
                (fun (ElmSyntaxNode_Node(_, x): ElmSyntaxNode_Node<ElmSyntaxPattern_Pattern>) ->
                    ElmSyntaxPattern_moduleNames x
                )
                subPatterns
            )

    | ElmSyntaxPattern_AsPattern(ElmSyntaxNode_Node(_, inner), _) ->
        ElmSyntaxPattern_moduleNames inner

    | ElmSyntaxPattern_ParenthesizedPattern(ElmSyntaxNode_Node(_, inner)) ->
        ElmSyntaxPattern_moduleNames inner

    | _ ->
        []

