let rec ElmSyntaxPrintDefunctionalized_commentsAfter (end_: ElmSyntaxRange_Location) (sortedComments: List<ElmSyntaxNode_Node<StringRope>>) : List<StringRope> =
    match sortedComments with
    | [] ->
        []

    | ElmSyntaxNode_Node(headCommentRange, headComment) :: tailComments ->
        match ElmSyntaxPrintDefunctionalized_locationCompareFast headCommentRange.Start end_ with
        | Basics_Order.LT ->
            ElmSyntaxPrintDefunctionalized_commentsAfter end_ tailComments

        | Basics_Order.GT ->
            List_cons headComment (List.map ElmSyntaxNode_value tailComments)

        | Basics_Order.EQ ->
            List_cons headComment (List.map ElmSyntaxNode_value tailComments)

let ElmSyntaxPrintDefunctionalized_declarationInfix (syntaxInfixDeclaration: Generated_Direction_Function_Operator_Precedence<ElmSyntaxNode_Node<ElmSyntaxInfix_InfixDirection>, ElmSyntaxNode_Node<StringRope>, ElmSyntaxNode_Node<StringRope>, ElmSyntaxNode_Node<int64>>) : Print_Print =
    Print_exactly (String_append (StringRopeOne "infix ") (String_append (ElmSyntaxPrintDefunctionalized_infixDirection (ElmSyntaxNode_value syntaxInfixDeclaration.Direction)) (String_append (StringRopeOne " ") (String_append (String_fromInt (ElmSyntaxNode_value syntaxInfixDeclaration.Precedence)) (String_append (StringRopeOne " (") (String_append (ElmSyntaxNode_value syntaxInfixDeclaration.Operator) (String_append (StringRopeOne ") = ") (ElmSyntaxNode_value syntaxInfixDeclaration.Function))))))))

