let ElmSyntaxPrintDefunctionalized_moduleExposing (context: Generated_AtDocsLines_Comments<List<List<StringRope>>, List<ElmSyntaxNode_Node<StringRope>>>) (ElmSyntaxNode_Node(exposingRange, syntaxExposing): ElmSyntaxNode_Node<ElmSyntaxExposing_Exposing>) : Print_Print =
    match syntaxExposing with
    | ElmSyntaxExposing_All(_) ->
        ElmSyntaxPrintDefunctionalized_printExactlyParensOpeningDotDotParensClosing

    | ElmSyntaxExposing_Explicit(exposingSet) ->
        match ElmSyntaxPrintDefunctionalized_exposeListToNormal exposingSet with
        | [] ->
            ElmSyntaxPrintDefunctionalized_printExactlyParensOpeningParensClosed

        | [ ElmSyntaxNode_Node(_, onlySyntaxExpose) ] ->
            let containedComments: List<StringRope> =
                ElmSyntaxPrintDefunctionalized_commentsInRange exposingRange context.Comments
            
            let lineSpread: Print_LineSpread =
                match containedComments with
                | _ :: _ ->
                    Print_MultipleLines

                | [] ->
                    Print_SingleLine
            
            Print_followedBy
                (match containedComments with
                 | [] ->
                    ElmSyntaxPrintDefunctionalized_printExactlyParensClosing

                 | comment0 :: comment1Up ->
                    Print_followedBy ElmSyntaxPrintDefunctionalized_printExactlyParensClosing (Print_followedBy (Print_emptyOrLinebreakIndented lineSpread) (ElmSyntaxPrintDefunctionalized_comments (List_cons comment0 comment1Up)))
                )
                (Print_followedBy
                    (Print_emptyOrLinebreakIndented lineSpread)
                    (Print_exactly
                        (String_append
                            (match lineSpread with
                             | Print_SingleLine ->
                                StringRopeOne "("

                             | Print_MultipleLines ->
                                StringRopeOne "( "
                            )
                            (ElmSyntaxPrintDefunctionalized_expose onlySyntaxExpose)
                        )
                    )
                )

        | expose0 :: (expose1 :: expose2Up) ->
            match context.AtDocsLines with
            | atDocsLine0 :: atDocsLine1Up ->
                let atDocsExposeLines: Generated_AtDocsExposeLines_RemainingExposes<List<List<ElmSyntaxExposing_TopLevelExpose>>, List<ElmSyntaxExposing_TopLevelExpose>> =
                    List_foldr
                        (fun (atDocsLine: List<StringRope>) (soFar: Generated_AtDocsExposeLines_RemainingExposes<List<List<ElmSyntaxExposing_TopLevelExpose>>, List<ElmSyntaxExposing_TopLevelExpose>>) ->
                            let atDocsExposeLine: Generated_Exposes_Remaining<List<ElmSyntaxExposing_TopLevelExpose>, List<ElmSyntaxExposing_TopLevelExpose>> =
                                ElmSyntaxPrintDefunctionalized_atDocsLineToExposesAndRemaining atDocsLine soFar.RemainingExposes
                            
                            { AtDocsExposeLines = List_cons atDocsExposeLine.Exposes soFar.AtDocsExposeLines
                            ; RemainingExposes = atDocsExposeLine.Remaining
                            }
                        )
                        { AtDocsExposeLines = []
                        ; RemainingExposes = List.map ElmSyntaxNode_value (List_cons expose0 (List_cons expose1 expose2Up))
                        }
                        (List_cons atDocsLine0 atDocsLine1Up)
                
                match
                    List.filter
                        (fun (line: List<ElmSyntaxExposing_TopLevelExpose>) ->
                            match line with
                            | [] ->
                                false

                            | _ :: _ ->
                                true
                        )
                        atDocsExposeLines.AtDocsExposeLines
                with
                | [] ->
                    ElmSyntaxPrintDefunctionalized_exposingMulti
                        context.Comments
                        { Expose0 = expose0
                        ; Expose1Up = List_cons expose1 expose2Up
                        ; FullRange = exposingRange
                        }

                | atDocsExposeLine0 :: atDocsExposeLine1Up ->
                    Print_followedBy
                        (match atDocsExposeLines.RemainingExposes with
                         | [] ->
                            ElmSyntaxPrintDefunctionalized_printExactlyParensClosing

                         | remainingExpose0 :: remainingExpose1Up ->
                            Print_followedBy ElmSyntaxPrintDefunctionalized_printExactlyParensClosing (Print_followedBy Print_linebreakIndented (Print_exactly (String_append (StringRopeOne ", ") (ElmSyntaxPrintDefunctionalized_listMapAndIntersperseAndFlattenToString ElmSyntaxPrintDefunctionalized_expose (StringRopeOne ", ") (List_cons remainingExpose0 remainingExpose1Up)))))
                        )
                        (Print_followedBy
                            Print_linebreakIndented
                            (Print_followedBy
                                (Print_listMapAndIntersperseAndFlatten
                                    (fun (atDocsLine: List<ElmSyntaxExposing_TopLevelExpose>) ->
                                        Print_exactly (ElmSyntaxPrintDefunctionalized_listMapAndIntersperseAndFlattenToString ElmSyntaxPrintDefunctionalized_expose (StringRopeOne ", ") atDocsLine)
                                    )
                                    ElmSyntaxPrintDefunctionalized_printLinebreakIndentedCommaSpace
                                    (List_cons atDocsExposeLine0 atDocsExposeLine1Up)
                                )
                                ElmSyntaxPrintDefunctionalized_printExactlyParensOpeningSpace
                            )
                        )

            | [] ->
                ElmSyntaxPrintDefunctionalized_exposingMulti
                    context.Comments
                    { Expose0 = expose0
                    ; Expose1Up = List_cons expose1 expose2Up
                    ; FullRange = exposingRange
                    }

let ElmSyntaxPrint_moduleExposing (context: Generated_AtDocsLines_Comments<List<List<StringRope>>, List<ElmSyntaxNode_Node<StringRope>>>) (moduleExposingNode: ElmSyntaxNode_Node<ElmSyntaxExposing_Exposing>) : Generated_Indent<int64> -> StringRope =
