let ElmSyntaxPrintDefunctionalized_moduleHeader (context: Generated_AtDocsLines_Comments<List<List<StringRope>>, List<ElmSyntaxNode_Node<StringRope>>>) (syntaxModuleHeader: ElmSyntaxModule_Module) : Print_Print =
    match syntaxModuleHeader with
    | ElmSyntaxModule_NormalModule(defaultModuleData) ->
        let exposingPrint: Print_Print =
            ElmSyntaxPrintDefunctionalized_moduleExposing context defaultModuleData.ExposingList
        
        let lineSpread: Print_LineSpread =
            Print_lineSpread exposingPrint
        
        Print_followedBy (Print_withIndentAtNextMultipleOf4 (Print_followedBy exposingPrint (Print_spaceOrLinebreakIndented lineSpread))) (Print_exactly (String_append (StringRopeOne "module ") (String_append (ElmSyntaxPrintDefunctionalized_moduleName (ElmSyntaxNode_value defaultModuleData.ModuleName)) (StringRopeOne " exposing"))))

    | ElmSyntaxModule_PortModule(defaultModuleData) ->
        let exposingPrint: Print_Print =
            ElmSyntaxPrintDefunctionalized_moduleExposing context defaultModuleData.ExposingList
        
        let lineSpread: Print_LineSpread =
            Print_lineSpread exposingPrint
        
        Print_followedBy (Print_withIndentAtNextMultipleOf4 (Print_followedBy exposingPrint (Print_spaceOrLinebreakIndented lineSpread))) (Print_exactly (String_append (StringRopeOne "port module ") (String_append (ElmSyntaxPrintDefunctionalized_moduleName (ElmSyntaxNode_value defaultModuleData.ModuleName)) (StringRopeOne " exposing"))))

    | ElmSyntaxModule_EffectModule(effectModuleData) ->
        let exposingPrint: Print_Print =
            ElmSyntaxPrintDefunctionalized_moduleExposing context effectModuleData.ExposingList
        
        let lineSpread: Print_LineSpread =
            Print_lineSpread exposingPrint
        
        Print_followedBy
            (Print_withIndentAtNextMultipleOf4 (Print_followedBy exposingPrint (Print_spaceOrLinebreakIndented lineSpread)))
            (Print_exactly
                (String_append
                    (StringRopeOne "effect module ")
                    (String_append
                        (ElmSyntaxPrintDefunctionalized_moduleName (ElmSyntaxNode_value effectModuleData.ModuleName))
                        (String_append
                            (StringRopeOne " where { ")
                            (String_append
                                (String_join
                                    (StringRopeOne ", ")
                                    (List_filterMap
                                        id
                                        [ match effectModuleData.Command with
                                          | ValueNone ->
                                            ValueNone

                                          | ValueSome(ElmSyntaxNode_Node(_, name)) ->
                                            ValueSome (String_append (StringRopeOne "command = ") name);
                                          match effectModuleData.Subscription with
                                          | ValueNone ->
                                            ValueNone

                                          | ValueSome(ElmSyntaxNode_Node(_, name)) ->
                                            ValueSome (String_append (StringRopeOne "subscription = ") name)
                                        ]
                                    )
                                )
                                (StringRopeOne " } exposing")
                            )
                        )
                    )
                )
            )

let ElmSyntaxPrint_moduleHeader (context: Generated_AtDocsLines_Comments<List<List<StringRope>>, List<ElmSyntaxNode_Node<StringRope>>>) (syntaxModuleHeader: ElmSyntaxModule_Module) : Generated_Indent<int64> -> StringRope =
    fun (state: Generated_Indent<int64>) ->
        Print_toStringWithIndent state.Indent (ElmSyntaxPrintDefunctionalized_moduleHeader context syntaxModuleHeader)

let ElmSyntaxPrintDefunctionalized_splitOffPortDocumentationComments (commentsAndPortDocumentationComments: List<ElmSyntaxNode_Node<StringRope>>) : Generated_PortDocumentationComments_RemainingComments<List<ElmSyntaxNode_Node<StringRope>>, List<ElmSyntaxNode_Node<StringRope>>> =
    List_foldr
        (fun (commentOrPortDocumentationComments: ElmSyntaxNode_Node<StringRope>) (soFar: Generated_PortDocumentationComments_RemainingComments<List<ElmSyntaxNode_Node<StringRope>>, List<ElmSyntaxNode_Node<StringRope>>>) ->
            if String_startsWith (StringRopeOne "{-|") (ElmSyntaxNode_value commentOrPortDocumentationComments) then
                { PortDocumentationComments = List_cons commentOrPortDocumentationComments soFar.PortDocumentationComments
                ; RemainingComments = soFar.RemainingComments
                }

            else
                { PortDocumentationComments = soFar.PortDocumentationComments
                ; RemainingComments = List_cons commentOrPortDocumentationComments soFar.RemainingComments
                }
        )
        ElmSyntaxPrintDefunctionalized_commentsEmptyPortDocumentationRemainingCommentsEmpty
        commentsAndPortDocumentationComments

let ElmSyntaxPrintDefunctionalized_typeToFunction (typeNode: ElmSyntaxNode_Node<ElmSyntaxTypeAnnotation_TypeAnnotation>) : ValueOption<Generated_InType_OutType<ElmSyntaxNode_Node<ElmSyntaxTypeAnnotation_TypeAnnotation>, ElmSyntaxNode_Node<ElmSyntaxTypeAnnotation_TypeAnnotation>>> =
    match ElmSyntaxNode_value (ElmSyntaxPrintDefunctionalized_typeToNotParenthesized typeNode) with
    | ElmSyntaxTypeAnnotation_FunctionTypeAnnotation(inType, outType) ->
        ValueSome
            { InType = inType
            ; OutType = outType
            }

    | ElmSyntaxTypeAnnotation_GenericType(_) ->
        ValueNone

    | ElmSyntaxTypeAnnotation_Typed(_, _) ->
        ValueNone

    | ElmSyntaxTypeAnnotation_Unit ->
        ValueNone

    | ElmSyntaxTypeAnnotation_Tupled(_) ->
        ValueNone

    | ElmSyntaxTypeAnnotation_Record(_) ->
        ValueNone

    | ElmSyntaxTypeAnnotation_GenericRecord(_, _) ->
        ValueNone

let ElmWriter_writeDocumentation: ElmSyntaxNode_Node<ElmSyntaxDocumentation_Documentation> -> StructuredWriter_Writer =
    (>>) ElmSyntaxNode_value StructuredWriter_string

let ElmWriter_writeInfix ({ Direction = direction; Function = function_; Operator = operator; Precedence = precedence }: Generated_Direction_Function_Operator_Precedence<ElmSyntaxNode_Node<ElmSyntaxInfix_InfixDirection>, ElmSyntaxNode_Node<StringRope>, ElmSyntaxNode_Node<StringRope>, ElmSyntaxNode_Node<int64>>) : StructuredWriter_Writer =
    StructuredWriter_spaced
        [ StructuredWriter_string (StringRopeOne "infix");
          match ElmSyntaxNode_value direction with
          | ElmSyntaxInfix_Left ->
            StructuredWriter_string (StringRopeOne "left")

          | ElmSyntaxInfix_Right ->
            StructuredWriter_string (StringRopeOne "right")

          | ElmSyntaxInfix_Non ->
            StructuredWriter_string (StringRopeOne "non");
          StructuredWriter_string (String_fromInt (ElmSyntaxNode_value precedence));
          StructuredWriter_string (ElmSyntaxNode_value operator);
          StructuredWriter_string (StringRopeOne "=");
          StructuredWriter_string (ElmSyntaxNode_value function_)
        ]

let rec ElmWriter_writePattern (ElmSyntaxNode_Node(_, p): ElmSyntaxNode_Node<ElmSyntaxPattern_Pattern>) : StructuredWriter_Writer =
    match p with
    | ElmSyntaxPattern_AllPattern ->
        StructuredWriter_string (StringRopeOne "_")

    | ElmSyntaxPattern_UnitPattern ->
        StructuredWriter_string (StringRopeOne "()")

    | ElmSyntaxPattern_CharPattern(c) ->
        ElmWriter_writeChar c

    | ElmSyntaxPattern_StringPattern(s) ->
        StructuredWriter_string (String_append (StringRopeOne "\"") (String_append (ElmWriter_escapeString s) (StringRopeOne "\"")))

    | ElmSyntaxPattern_HexPattern(h) ->
        StructuredWriter_join
            [ StructuredWriter_string (StringRopeOne "0x");
              StructuredWriter_string (Hex_toString h)
            ]

    | ElmSyntaxPattern_IntPattern(i) ->
        StructuredWriter_string (String_fromInt i)

    | ElmSyntaxPattern_FloatPattern(f) ->
        StructuredWriter_string (String_fromFloat f)

    | ElmSyntaxPattern_TuplePattern(inner) ->
        StructuredWriter_parensComma false (List.map ElmWriter_writePattern inner)

    | ElmSyntaxPattern_RecordPattern(inner) ->
        StructuredWriter_bracesComma false (List.map ((>>) ElmSyntaxNode_value StructuredWriter_string) inner)

    | ElmSyntaxPattern_UnConsPattern(left, right) ->
        StructuredWriter_spaced
            [ ElmWriter_writePattern left;
              StructuredWriter_string (StringRopeOne "::");
              ElmWriter_writePattern right
            ]

    | ElmSyntaxPattern_ListPattern(inner) ->
        StructuredWriter_bracketsComma false (List.map ElmWriter_writePattern inner)

    | ElmSyntaxPattern_VarPattern(var) ->
        StructuredWriter_string var

    | ElmSyntaxPattern_NamedPattern(qnr, others) ->
        StructuredWriter_spaced
            [ ElmWriter_writeQualifiedNameRef qnr;
              StructuredWriter_spaced (List.map ElmWriter_writePattern others)
            ]

    | ElmSyntaxPattern_AsPattern(innerPattern, asName) ->
        StructuredWriter_spaced
            [ ElmWriter_writePattern innerPattern;
              StructuredWriter_string (StringRopeOne "as");
              StructuredWriter_string (ElmSyntaxNode_value asName)
            ]

    | ElmSyntaxPattern_ParenthesizedPattern(innerPattern) ->
        StructuredWriter_spaced
            [ StructuredWriter_string (StringRopeOne "(");
              ElmWriter_writePattern innerPattern;
              StructuredWriter_string (StringRopeOne ")")
            ]

let rec ElmWriter_writeTypeAnnotation (ElmSyntaxNode_Node(_, typeAnnotation): ElmSyntaxNode_Node<ElmSyntaxTypeAnnotation_TypeAnnotation>) : StructuredWriter_Writer =
    match typeAnnotation with
    | ElmSyntaxTypeAnnotation_GenericType(s) ->
        StructuredWriter_string s

    | ElmSyntaxTypeAnnotation_Typed(ElmSyntaxNode_Node(_, (struct( moduleName, name ))), args) ->
        StructuredWriter_spaced (List_cons (StructuredWriter_string (String_join (StringRopeOne ".") (List.append moduleName [ name ]))) (List.map ((>>) ElmWriter_writeTypeAnnotation ElmWriter_parensIfContainsSpaces) args))

    | ElmSyntaxTypeAnnotation_Unit ->
        StructuredWriter_string (StringRopeOne "()")

    | ElmSyntaxTypeAnnotation_Tupled(xs) ->
        StructuredWriter_parensComma false (List.map ElmWriter_writeTypeAnnotation xs)

    | ElmSyntaxTypeAnnotation_Record(xs) ->
        StructuredWriter_bracesComma false (List.map ElmWriter_writeRecordField xs)

    | ElmSyntaxTypeAnnotation_GenericRecord(name, fields) ->
        StructuredWriter_spaced
            [ StructuredWriter_string (StringRopeOne "{");
              StructuredWriter_string (ElmSyntaxNode_value name);
              StructuredWriter_string (StringRopeOne "|");
              StructuredWriter_sepByComma false (List.map ElmWriter_writeRecordField (ElmSyntaxNode_value fields));
              StructuredWriter_string (StringRopeOne "}")
            ]

    | ElmSyntaxTypeAnnotation_FunctionTypeAnnotation(left, right) ->
        let addParensForSubTypeAnnotation (type__: ElmSyntaxNode_Node<ElmSyntaxTypeAnnotation_TypeAnnotation>) : StructuredWriter_Writer =
            match type__ with
            | ElmSyntaxNode_Node(_, ElmSyntaxTypeAnnotation_FunctionTypeAnnotation(_, _)) ->
                StructuredWriter_join
                    [ StructuredWriter_string (StringRopeOne "(");
                      ElmWriter_writeTypeAnnotation type__;
                      StructuredWriter_string (StringRopeOne ")")
                    ]

            | _ ->
                ElmWriter_writeTypeAnnotation type__
        
        StructuredWriter_spaced
            [ addParensForSubTypeAnnotation left;
              StructuredWriter_string (StringRopeOne "->");
              addParensForSubTypeAnnotation right
            ]

and ElmWriter_writeRecordField
    (ElmSyntaxNode_Node(_, (struct( name, ref ))):
        ElmSyntaxNode_Node<
            (struct(
              ElmSyntaxNode_Node<StringRope>
            * ElmSyntaxNode_Node<ElmSyntaxTypeAnnotation_TypeAnnotation>
            ))
            >
    )
    : StructuredWriter_Writer =
    StructuredWriter_spaced
        [ StructuredWriter_string (ElmSyntaxNode_value name);
          StructuredWriter_string (StringRopeOne ":");
          ElmWriter_writeTypeAnnotation ref
        ]

let ElmWriter_writeSignature (signature: Generated_Name_TypeAnnotation<ElmSyntaxNode_Node<StringRope>, ElmSyntaxNode_Node<ElmSyntaxTypeAnnotation_TypeAnnotation>>) : StructuredWriter_Writer =
    StructuredWriter_spaced
        [ StructuredWriter_string (ElmSyntaxNode_value signature.Name);
          StructuredWriter_string (StringRopeOne ":");
          ElmWriter_writeTypeAnnotation signature.TypeAnnotation
        ]

let ElmWriter_writePortDeclaration (signature: ElmSyntaxSignature_Signature) : StructuredWriter_Writer =
    StructuredWriter_spaced
        [ StructuredWriter_string (StringRopeOne "port");
          ElmWriter_writeSignature signature
        ]

let ElmWriter_writeTypeAlias (typeAlias: Generated_Documentation_Generics_Name_TypeAnnotation<ValueOption<ElmSyntaxNode_Node<ElmSyntaxDocumentation_Documentation>>, List<ElmSyntaxNode_Node<StringRope>>, ElmSyntaxNode_Node<StringRope>, ElmSyntaxNode_Node<ElmSyntaxTypeAnnotation_TypeAnnotation>>) : StructuredWriter_Writer =
    StructuredWriter_breaked
        [ StructuredWriter_spaced
            [ StructuredWriter_string (StringRopeOne "type alias");
              StructuredWriter_string (ElmSyntaxNode_value typeAlias.Name);
              StructuredWriter_spaced (List.map ((>>) ElmSyntaxNode_value StructuredWriter_string) typeAlias.Generics);
              StructuredWriter_string (StringRopeOne "=")
            ];
          StructuredWriter_indent 4L (ElmWriter_writeTypeAnnotation typeAlias.TypeAnnotation)
        ]

let ElmWriter_writeWhere
    (input:
        (struct(
          ValueOption<ElmSyntaxNode_Node<StringRope>>
        * ValueOption<ElmSyntaxNode_Node<StringRope>>
        ))
    )
    : StructuredWriter_Writer =
    match input with
    | (struct( ValueNone, ValueNone )) ->
        StructuredWriter_epsilon

    | (struct( ValueSome(x), ValueNone )) ->
        StructuredWriter_spaced
            [ StructuredWriter_string (StringRopeOne "where { command =");
              StructuredWriter_string (ElmSyntaxNode_value x);
              StructuredWriter_string (StringRopeOne "}")
            ]

    | (struct( ValueNone, ValueSome(x) )) ->
        StructuredWriter_spaced
            [ StructuredWriter_string (StringRopeOne "where { subscription =");
              StructuredWriter_string (ElmSyntaxNode_value x);
              StructuredWriter_string (StringRopeOne "}")
            ]

    | (struct( ValueSome(x), ValueSome(y) )) ->
        StructuredWriter_spaced
            [ StructuredWriter_string (StringRopeOne "where { command =");
              StructuredWriter_string (ElmSyntaxNode_value x);
              StructuredWriter_string (StringRopeOne ", subscription =");
              StructuredWriter_string (ElmSyntaxNode_value y);
              StructuredWriter_string (StringRopeOne "}")
            ]

let ElmSyntaxNode_range (ElmSyntaxNode_Node(r, _): ElmSyntaxNode_Node<'a>) : ElmSyntaxRange_Range =
    r

let ElmSyntaxPrintDefunctionalized_construct (specific: Generated_LineSpreadMinimum_PrintArgumentParenthesizedIfSpaceSeparated<Print_LineSpread, List<ElmSyntaxNode_Node<StringRope>> -> ElmSyntaxNode_Node<'a> -> Print_Print>) (syntaxComments: List<ElmSyntaxNode_Node<StringRope>>) (syntaxConstruct: Generated_Arguments_FullRange_Start<List<ElmSyntaxNode_Node<'a>>, ElmSyntaxRange_Range, StringRope>) : Print_Print =
    let argumentPrintsAndCommentsBeforeReverse: List<Print_Print> =
        (List_foldl
            (fun (argument: ElmSyntaxNode_Node<'a>) (soFar: Generated_EndLocation_Reverse<ElmSyntaxRange_Location, List<Print_Print>>) ->
                let print: Print_Print =
                    specific.PrintArgumentParenthesizedIfSpaceSeparated syntaxComments argument
                
                { EndLocation = (ElmSyntaxNode_range argument).End
                ; Reverse =
                    List_cons
                        (match
                            ElmSyntaxPrintDefunctionalized_commentsInRange
                                { End = (ElmSyntaxNode_range argument).Start
                                ; Start = soFar.EndLocation
                                }
                                syntaxComments
                         with
                         | [] ->
                            print

                         | comment0 :: comment1Up ->
                            let commentsBeforeArgument: Generated_LineSpread_Print<Print_LineSpread, Print_Print> =
                                ElmSyntaxPrintDefunctionalized_collapsibleComments (List_cons comment0 comment1Up)
                            
                            Print_followedBy
                                print
                                (Print_followedBy
                                    (Print_spaceOrLinebreakIndented
                                        (Print_lineSpreadMergeWith
                                            (fun (_: unit) ->
                                                Print_lineSpread print
                                            )
                                            commentsBeforeArgument.LineSpread
                                        )
                                    )
                                    commentsBeforeArgument.Print
                                )
                        )
                        soFar.Reverse
                }
            )
            { EndLocation = syntaxConstruct.FullRange.Start
            ; Reverse = []
            }
            syntaxConstruct.Arguments
        ).Reverse
    
    let lineSpread: Print_LineSpread =
        Print_lineSpreadMergeWith
            (fun (_: unit) ->
                Print_lineSpreadListMapAndCombine Print_lineSpread argumentPrintsAndCommentsBeforeReverse
            )
            specific.LineSpreadMinimum
    
    Print_followedBy
        (Print_withIndentAtNextMultipleOf4
            (Print_listReverseAndMapAndFlatten
                (fun (argumentPrintWithCommentsBefore: Print_Print) ->
                    Print_followedBy argumentPrintWithCommentsBefore (Print_spaceOrLinebreakIndented lineSpread)
                )
                argumentPrintsAndCommentsBeforeReverse
            )
        )
        (Print_exactly syntaxConstruct.Start)

let ElmSyntaxPrintDefunctionalized_parenthesized (printNotParenthesized: List<ElmSyntaxNode_Node<StringRope>> -> ElmSyntaxNode_Node<'a> -> Print_Print) (syntax: Generated_FullRange_NotParenthesized<Generated_End_Start<ElmSyntaxRange_Location, ElmSyntaxRange_Location>, ElmSyntaxNode_Node<'a>>) (syntaxComments: List<ElmSyntaxNode_Node<StringRope>>) : Print_Print =
    let notParenthesizedPrint: Print_Print =
        printNotParenthesized syntaxComments syntax.NotParenthesized
    
    let commentsBeforeInner: List<StringRope> =
        ElmSyntaxPrintDefunctionalized_commentsInRange
            { End = (ElmSyntaxNode_range syntax.NotParenthesized).Start
            ; Start = syntax.FullRange.Start
            }
            syntaxComments
    
    let commentsBeforeInnerCollapsible: Generated_LineSpread_Print<Print_LineSpread, Print_Print> =
        ElmSyntaxPrintDefunctionalized_collapsibleComments commentsBeforeInner
    
    let commentsAfterInner: List<StringRope> =
        ElmSyntaxPrintDefunctionalized_commentsInRange
            { End = syntax.FullRange.End
            ; Start = (ElmSyntaxNode_range syntax.NotParenthesized).End
            }
            syntaxComments
    
    let commentsAfterInnerCollapsible: Generated_LineSpread_Print<Print_LineSpread, Print_Print> =
        ElmSyntaxPrintDefunctionalized_collapsibleComments commentsAfterInner
    
    let lineSpread: Print_LineSpread =
        Print_lineSpreadMergeWithStrict commentsAfterInnerCollapsible.LineSpread (Print_lineSpreadMergeWithStrict commentsBeforeInnerCollapsible.LineSpread (Print_lineSpread notParenthesizedPrint))
    
    Print_followedBy
        ElmSyntaxPrintDefunctionalized_printExactlyParensClosing
        (Print_followedBy
            (Print_emptyOrLinebreakIndented lineSpread)
            (Print_followedBy
                (Print_withIndentIncreasedBy
                    1L
                    (Print_followedBy
                        (match commentsAfterInner with
                         | [] ->
                            Print_empty

                         | _ :: _ ->
                            Print_followedBy commentsAfterInnerCollapsible.Print (Print_spaceOrLinebreakIndented lineSpread)
                        )
                        (match commentsBeforeInner with
                         | [] ->
                            notParenthesizedPrint

                         | _ :: _ ->
                            Print_followedBy notParenthesizedPrint (Print_followedBy (Print_spaceOrLinebreakIndented lineSpread) commentsBeforeInnerCollapsible.Print)
                        )
                    )
                )
                ElmSyntaxPrintDefunctionalized_printExactlyParensOpening
            )
        )

let ElmSyntaxPrintDefunctionalized_recordLiteral
    (fieldSpecific: Generated_NameValueSeparator_PrintValueNotParenthesized<StringRope, List<ElmSyntaxNode_Node<StringRope>> -> ElmSyntaxNode_Node<'fieldValue> -> Print_Print>)
    (syntaxComments: List<ElmSyntaxNode_Node<StringRope>>)
    (syntaxRecord:
        Generated_Fields_FullRange<
            List<
                ElmSyntaxNode_Node<
                    (struct(
                      ElmSyntaxNode_Node<StringRope>
                    * ElmSyntaxNode_Node<'fieldValue>
                    ))
                    >
                >,
            ElmSyntaxRange_Range
            >
    )
    : Print_Print =
    match syntaxRecord.Fields with
    | [] ->
        Print_followedBy
            (match ElmSyntaxPrintDefunctionalized_commentsInRange syntaxRecord.FullRange syntaxComments with
             | [] ->
                ElmSyntaxPrintDefunctionalized_printExactlyCurlyClosing

             | comment0 :: comment1Up ->
                let commentsCollapsed: Generated_LineSpread_Print<Print_LineSpread, Print_Print> =
                    ElmSyntaxPrintDefunctionalized_collapsibleComments (List_cons comment0 comment1Up)
                
                Print_followedBy ElmSyntaxPrintDefunctionalized_printExactlyCurlyClosing (Print_followedBy (Print_emptyOrLinebreakIndented commentsCollapsed.LineSpread) (Print_withIndentIncreasedBy 1L commentsCollapsed.Print))
            )
            ElmSyntaxPrintDefunctionalized_printExactlyCurlyOpening

    | field0 :: field1Up ->
        let fieldPrintsAndComments:
                Generated_EndLocation_Reverse<
                    ElmSyntaxRange_Location,
                    List<
                        Generated_MaybeCommentsBeforeName_MaybeCommentsBetweenNameAndValue_Syntax_ValuePrint<
                            ValueOption<Generated_LineSpread_Print<Print_LineSpread, Print_Print>>,
                            ValueOption<Generated_LineSpread_Print<Print_LineSpread, Print_Print>>,
                            (struct(
                              ElmSyntaxNode_Node<StringRope>
                            * ElmSyntaxNode_Node<'fieldValue>
                            )),
                            Print_Print
                            >
                        >
                    > =
            List_foldl
                (fun (ElmSyntaxNode_Node(_, (struct( ElmSyntaxNode_Node(fieldNameRange, fieldName), fieldValueNode ))):
                        ElmSyntaxNode_Node<
                            (struct(
                              ElmSyntaxNode_Node<StringRope>
                            * ElmSyntaxNode_Node<'fieldValue>
                            ))
                            >
                     )
                     (soFar:
                        Generated_EndLocation_Reverse<
                            ElmSyntaxRange_Location,
                            List<
                                Generated_MaybeCommentsBeforeName_MaybeCommentsBetweenNameAndValue_Syntax_ValuePrint<
                                    ValueOption<Generated_LineSpread_Print<Print_LineSpread, Print_Print>>,
                                    ValueOption<Generated_LineSpread_Print<Print_LineSpread, Print_Print>>,
                                    (struct(
                                      ElmSyntaxNode_Node<StringRope>
                                    * ElmSyntaxNode_Node<'fieldValue>
                                    )),
                                    Print_Print
                                    >
                                >
                            >
                     ) ->
                    let (ElmSyntaxNode_Node(fieldValueRange, _): ElmSyntaxNode_Node<'fieldValue>) =
                        fieldValueNode
                    
                    let commentsBetweenNameAndValue: List<StringRope> =
                        ElmSyntaxPrintDefunctionalized_commentsInRange
                            { End = fieldValueRange.Start
                            ; Start = fieldNameRange.Start
                            }
                            syntaxComments
                    
                    let commentsBeforeName: List<StringRope> =
                        ElmSyntaxPrintDefunctionalized_commentsInRange
                            { End = fieldNameRange.Start
                            ; Start = soFar.EndLocation
                            }
                            syntaxComments
                    
                    { EndLocation = fieldValueRange.End
                    ; Reverse =
                        List_cons
                            { MaybeCommentsBeforeName =
                                match commentsBeforeName with
                                | [] ->
                                    ValueNone

                                | comment0 :: comment1Up ->
                                    ValueSome (ElmSyntaxPrintDefunctionalized_collapsibleComments (List_cons comment0 comment1Up))
                            ; MaybeCommentsBetweenNameAndValue =
                                match commentsBetweenNameAndValue with
                                | [] ->
                                    ValueNone

                                | comment0 :: comment1Up ->
                                    ValueSome (ElmSyntaxPrintDefunctionalized_collapsibleComments (List_cons comment0 comment1Up))
                            ; Syntax = (struct( ElmSyntaxNode_Node (struct( fieldNameRange, fieldName )), fieldValueNode ))
                            ; ValuePrint = fieldSpecific.PrintValueNotParenthesized syntaxComments fieldValueNode
                            }
                            soFar.Reverse
                    }
                )
                { EndLocation = syntaxRecord.FullRange.Start
                ; Reverse = []
                }
                (List_cons field0 field1Up)
        
        let commentsAfterFields: List<StringRope> =
            ElmSyntaxPrintDefunctionalized_commentsInRange
                { End = syntaxRecord.FullRange.End
                ; Start = fieldPrintsAndComments.EndLocation
                }
                syntaxComments
        
        let lineSpread: Print_LineSpread =
            Print_lineSpreadMergeWith
                (fun (_: unit) ->
                    match commentsAfterFields with
                    | [] ->
                        Print_SingleLine

                    | _ :: _ ->
                        Print_MultipleLines
                )
                (Print_lineSpreadMergeWith
                    (fun (_: unit) ->
                        Print_lineSpreadListMapAndCombine
                            (fun (field:
                                    Generated_MaybeCommentsBeforeName_MaybeCommentsBetweenNameAndValue_Syntax_ValuePrint<
                                        ValueOption<Generated_LineSpread_Print<Print_LineSpread, Print_Print>>,
                                        ValueOption<Generated_LineSpread_Print<Print_LineSpread, Print_Print>>,
                                        (struct(
                                          ElmSyntaxNode_Node<StringRope>
                                        * ElmSyntaxNode_Node<'fieldValue>
                                        )),
                                        Print_Print
                                        >
                                 ) ->
                                Print_lineSpreadMergeWith
                                    (fun (_: unit) ->
                                        match field.MaybeCommentsBetweenNameAndValue with
                                        | ValueNone ->
                                            Print_SingleLine

                                        | ValueSome(commentsBetweenNameAndValue) ->
                                            commentsBetweenNameAndValue.LineSpread
                                    )
                                    (Print_lineSpreadMergeWith
                                        (fun (_: unit) ->
                                            match field.MaybeCommentsBeforeName with
                                            | ValueNone ->
                                                Print_SingleLine

                                            | ValueSome(commentsBeforeName) ->
                                                commentsBeforeName.LineSpread
                                        )
                                        (Print_lineSpread field.ValuePrint)
                                    )
                            )
                            fieldPrintsAndComments.Reverse
                    )
                    (ElmSyntaxPrintDefunctionalized_lineSpreadInRange syntaxRecord.FullRange)
                )
        
        Print_followedBy
            ElmSyntaxPrintDefunctionalized_printExactlyCurlyClosing
            (Print_followedBy
                (match commentsAfterFields with
                 | [] ->
                    Print_spaceOrLinebreakIndented lineSpread

                 | comment0 :: comment1Up ->
                    Print_followedBy (Print_spaceOrLinebreakIndented lineSpread) (Print_followedBy (ElmSyntaxPrintDefunctionalized_comments (List_cons comment0 comment1Up)) (Print_followedBy (Print_spaceOrLinebreakIndented lineSpread) Print_linebreak))
                )
                (Print_followedBy
                    (Print_listReverseAndMapAndIntersperseAndFlatten
                        (fun (field:
                                Generated_MaybeCommentsBeforeName_MaybeCommentsBetweenNameAndValue_Syntax_ValuePrint<
                                    ValueOption<Generated_LineSpread_Print<Print_LineSpread, Print_Print>>,
                                    ValueOption<Generated_LineSpread_Print<Print_LineSpread, Print_Print>>,
                                    (struct(
                                      ElmSyntaxNode_Node<StringRope>
                                    * ElmSyntaxNode_Node<'fieldValue>
                                    )),
                                    Print_Print
                                    >
                             ) ->
                            let ((struct( ElmSyntaxNode_Node(fieldNameRange, fieldName), fieldValue )):
                                    (struct(
                                      ElmSyntaxNode_Node<StringRope>
                                    * ElmSyntaxNode_Node<'fieldValue>
                                    ))
                                ) =
                                field.Syntax
                            
                            let lineSpreadBetweenNameAndValueNotConsideringComments (_: unit) : Print_LineSpread =
                                Print_lineSpreadMergeWith
                                    (fun (_: unit) ->
                                        Print_lineSpread field.ValuePrint
                                    )
                                    (ElmSyntaxPrintDefunctionalized_lineSpreadInRange
                                        { End = (ElmSyntaxNode_range fieldValue).End
                                        ; Start = fieldNameRange.Start
                                        }
                                    )
                            
                            let nameSeparatorValuePrint: Print_Print =
                                Print_followedBy
                                    (Print_withIndentAtNextMultipleOf4
                                        (Print_followedBy
                                            field.ValuePrint
                                            (match field.MaybeCommentsBetweenNameAndValue with
                                             | ValueNone ->
                                                Print_spaceOrLinebreakIndented (lineSpreadBetweenNameAndValueNotConsideringComments ())

                                             | ValueSome(commentsBetweenNameAndValue) ->
                                                Print_followedBy
                                                    (Print_spaceOrLinebreakIndented
                                                        (Print_lineSpreadMergeWith
                                                            (fun (_: unit) ->
                                                                Print_lineSpread field.ValuePrint
                                                            )
                                                            commentsBetweenNameAndValue.LineSpread
                                                        )
                                                    )
                                                    (Print_followedBy commentsBetweenNameAndValue.Print (Print_spaceOrLinebreakIndented (Print_lineSpreadMergeWith lineSpreadBetweenNameAndValueNotConsideringComments commentsBetweenNameAndValue.LineSpread)))
                                            )
                                        )
                                    )
                                    (Print_exactly (String_append fieldName (String_append (StringRopeOne " ") fieldSpecific.NameValueSeparator)))
                            
                            Print_withIndentIncreasedBy
                                2L
                                (match field.MaybeCommentsBeforeName with
                                 | ValueNone ->
                                    nameSeparatorValuePrint

                                 | ValueSome(commentsBeforeName) ->
                                    Print_followedBy nameSeparatorValuePrint (Print_followedBy (Print_spaceOrLinebreakIndented commentsBeforeName.LineSpread) commentsBeforeName.Print)
                                )
                        )
                        (Print_followedBy ElmSyntaxPrintDefunctionalized_printExactlyCommaSpace (Print_emptyOrLinebreakIndented lineSpread))
                        fieldPrintsAndComments.Reverse
                    )
                    ElmSyntaxPrintDefunctionalized_printExactlyCurlyOpeningSpace
                )
            )

let ElmSyntaxPrintDefunctionalized_triple (config: Generated_LineSpreadMinimum_PrintPartNotParenthesized<Print_LineSpread, List<ElmSyntaxNode_Node<StringRope>> -> ElmSyntaxNode_Node<'part> -> Print_Print>) (syntaxComments: List<ElmSyntaxNode_Node<StringRope>>) (syntaxTriple: Generated_FullRange_Part0_Part1_Part2<Generated_End_Start<ElmSyntaxRange_Location, ElmSyntaxRange_Location>, ElmSyntaxNode_Node<'part>, ElmSyntaxNode_Node<'part>, ElmSyntaxNode_Node<'part>>) : Print_Print =
    let part2Print: Print_Print =
        config.PrintPartNotParenthesized syntaxComments syntaxTriple.Part2
    
    let part1Print: Print_Print =
        config.PrintPartNotParenthesized syntaxComments syntaxTriple.Part1
    
    let part0Print: Print_Print =
        config.PrintPartNotParenthesized syntaxComments syntaxTriple.Part0
    
    let beforePart2Comments: List<StringRope> =
        ElmSyntaxPrintDefunctionalized_commentsInRange
            { End = (ElmSyntaxNode_range syntaxTriple.Part2).Start
