and ElmSyntaxPrintDefunctionalized_typeNotParenthesized (syntaxComments: List<ElmSyntaxNode_Node<StringRope>>) (ElmSyntaxNode_Node(fullRange, syntaxType): ElmSyntaxNode_Node<ElmSyntaxTypeAnnotation_TypeAnnotation>) : Print_Print =
    match syntaxType with
    | ElmSyntaxTypeAnnotation_Unit ->
        ElmSyntaxPrintDefunctionalized_printExactlyParensOpeningParensClosed

    | ElmSyntaxTypeAnnotation_GenericType(name) ->
        Print_exactly name

    | ElmSyntaxTypeAnnotation_Typed(ElmSyntaxNode_Node(_, (struct( referenceQualification, referenceUnqualified ))), arguments) ->
        ElmSyntaxPrintDefunctionalized_construct
            { LineSpreadMinimum = ElmSyntaxPrintDefunctionalized_lineSpreadInRange fullRange
            ; PrintArgumentParenthesizedIfSpaceSeparated = ElmSyntaxPrintDefunctionalized_typeParenthesizedIfSpaceSeparated
            }
            syntaxComments
            { Arguments = arguments
            ; FullRange = fullRange
            ; Start =
                ElmSyntaxPrintDefunctionalized_qualifiedReference
                    { Qualification = referenceQualification
                    ; Unqualified = referenceUnqualified
                    }
            }

    | ElmSyntaxTypeAnnotation_Tupled(parts) ->
        match parts with
        | [] ->
            ElmSyntaxPrintDefunctionalized_printExactlyParensOpeningParensClosed

        | [ inParens ] ->
            let commentsBeforeInParens: List<StringRope> =
                ElmSyntaxPrintDefunctionalized_commentsInRange
                    { End = (ElmSyntaxNode_range inParens).Start
                    ; Start = fullRange.Start
                    }
                    syntaxComments
            
            let commentsAfterInParens: List<StringRope> =
                ElmSyntaxPrintDefunctionalized_commentsInRange
                    { End = fullRange.End
                    ; Start = (ElmSyntaxNode_range inParens).End
                    }
                    syntaxComments
            
            match (struct( commentsBeforeInParens, commentsAfterInParens )) with
            | (struct( [], [] )) ->
                ElmSyntaxPrintDefunctionalized_typeNotParenthesized syntaxComments inParens

            | _ ->
                ElmSyntaxPrintDefunctionalized_parenthesized
                    ElmSyntaxPrintDefunctionalized_typeNotParenthesized
                    { FullRange = fullRange
                    ; NotParenthesized = ElmSyntaxPrintDefunctionalized_typeToNotParenthesized inParens
                    }
                    syntaxComments

        | [ part0; part1 ] ->
            ElmSyntaxPrintDefunctionalized_tuple
                { LineSpreadMinimum = ElmSyntaxPrintDefunctionalized_lineSpreadInRange fullRange
                ; PrintPartNotParenthesized = ElmSyntaxPrintDefunctionalized_typeNotParenthesized
                }
                syntaxComments
                { FullRange = fullRange
                ; Part0 = part0
                ; Part1 = part1
                }

        | [ part0; part1; part2 ] ->
            ElmSyntaxPrintDefunctionalized_triple
                { LineSpreadMinimum = ElmSyntaxPrintDefunctionalized_lineSpreadInRange fullRange
                ; PrintPartNotParenthesized = ElmSyntaxPrintDefunctionalized_typeNotParenthesized
                }
                syntaxComments
                { FullRange = fullRange
                ; Part0 = part0
                ; Part1 = part1
                ; Part2 = part2
                }

        | part0 :: (part1 :: (part2 :: (part3 :: part4Up))) ->
            ElmSyntaxPrintDefunctionalized_invalidNTuple
                ElmSyntaxPrintDefunctionalized_typeNotParenthesized
                syntaxComments
                { FullRange = fullRange
                ; Part0 = part0
                ; Part1 = part1
                ; Part2 = part2
                ; Part3 = part3
                ; Part4Up = part4Up
                }

    | ElmSyntaxTypeAnnotation_Record(fields) ->
        ElmSyntaxPrintDefunctionalized_recordLiteral
            { NameValueSeparator = StringRopeOne ":"
            ; PrintValueNotParenthesized = ElmSyntaxPrintDefunctionalized_typeNotParenthesized
            }
            syntaxComments
            { Fields = fields
            ; FullRange = fullRange
            }

    | ElmSyntaxTypeAnnotation_GenericRecord(recordVariable, ElmSyntaxNode_Node(_, fields)) ->
        ElmSyntaxPrintDefunctionalized_typeRecordExtension
            syntaxComments
            { Fields = fields
            ; FullRange = fullRange
            ; RecordVariable = recordVariable
            }

    | ElmSyntaxTypeAnnotation_FunctionTypeAnnotation(inType, outType) ->
        ElmSyntaxPrintDefunctionalized_typeFunctionNotParenthesized
            syntaxComments
            { FullRange = fullRange
            ; InType = inType
            ; OutType = outType
            }

and ElmSyntaxPrintDefunctionalized_typeFunctionNotParenthesized (syntaxComments: List<ElmSyntaxNode_Node<StringRope>>) (function_: Generated_FullRange_InType_OutType<ElmSyntaxRange_Range, ElmSyntaxNode_Node<ElmSyntaxTypeAnnotation_TypeAnnotation>, ElmSyntaxNode_Node<ElmSyntaxTypeAnnotation_TypeAnnotation>>) : Print_Print =
