and ElmSyntaxPrintDefunctionalized_typeParenthesizedIfSpaceSeparated (syntaxComments: List<ElmSyntaxNode_Node<StringRope>>) (typeNode: ElmSyntaxNode_Node<ElmSyntaxTypeAnnotation_TypeAnnotation>) : Print_Print =
    if ElmSyntaxPrintDefunctionalized_typeIsSpaceSeparated (ElmSyntaxNode_value typeNode) then
