let ElmSyntaxPrintDefunctionalized_declarationSignature (syntaxComments: List<ElmSyntaxNode_Node<StringRope>>) (signature: Generated_Name_TypeAnnotation<ElmSyntaxNode_Node<StringRope>, ElmSyntaxNode_Node<ElmSyntaxTypeAnnotation_TypeAnnotation>>) : Print_Print =
