let ElmSyntaxPrintDefunctionalized_declarationTypeAlias (syntaxComments: List<ElmSyntaxNode_Node<StringRope>>) (syntaxTypeAliasDeclaration: Generated_Documentation_Generics_Name_TypeAnnotation<ValueOption<ElmSyntaxNode_Node<ElmSyntaxDocumentation_Documentation>>, List<ElmSyntaxNode_Node<StringRope>>, ElmSyntaxNode_Node<StringRope>, ElmSyntaxNode_Node<ElmSyntaxTypeAnnotation_TypeAnnotation>>) : Print_Print =
