            ; Start = (ElmSyntaxNode_range syntaxTypeAliasDeclaration.Name).End
            }

        | parameter0 :: parameter1Up ->
            { End = (ElmSyntaxNode_range syntaxTypeAliasDeclaration.TypeAnnotation).Start
            ; Start = (ElmSyntaxNode_range (ElmSyntaxPrintDefunctionalized_listFilledLast parameter0 parameter1Up)).End
            }
    
    let parameterPrintsWithCommentsBeforeReverse: List<Print_Print> =
        (List_foldl
            (fun (parameterName: ElmSyntaxNode_Node<StringRope>) (soFar: Generated_EndLocation_Reverse<ElmSyntaxRange_Location, List<Print_Print>>) ->
                let parameterPrintedRange: ElmSyntaxRange_Range =
                    ElmSyntaxNode_range parameterName
                
                let parameterNamePrint: Print_Print =
                    Print_exactly (ElmSyntaxNode_value parameterName)
                
                { EndLocation = parameterPrintedRange.End
                ; Reverse =
                    List_cons
                        (match
                            ElmSyntaxPrintDefunctionalized_commentsInRange
                                { End = parameterPrintedRange.Start
                                ; Start = soFar.EndLocation
                                }
                                syntaxComments
                         with
                         | [] ->
                            parameterNamePrint

                         | comment0 :: comment1Up ->
                            let commentsCollapsible: Generated_LineSpread_Print<Print_LineSpread, Print_Print> =
                                ElmSyntaxPrintDefunctionalized_collapsibleComments (List_cons comment0 comment1Up)
                            
                            Print_followedBy parameterNamePrint (Print_followedBy (Print_spaceOrLinebreakIndented commentsCollapsible.LineSpread) commentsCollapsible.Print)
                        )
                        soFar.Reverse
                }
            )
            { EndLocation = (ElmSyntaxNode_range syntaxTypeAliasDeclaration.Name).End
            ; Reverse = []
            }
            syntaxTypeAliasDeclaration.Generics
        ).Reverse
    
    let parametersLineSpread: Print_LineSpread =
        Print_lineSpreadListMapAndCombine Print_lineSpread parameterPrintsWithCommentsBeforeReverse
    
    let aliasedTypePrint: Print_Print =
        ElmSyntaxPrintDefunctionalized_typeNotParenthesized syntaxComments syntaxTypeAliasDeclaration.TypeAnnotation
    
    Print_followedBy
        (Print_withIndentAtNextMultipleOf4
            (Print_followedBy
                (Print_followedBy
                    (match ElmSyntaxPrintDefunctionalized_commentsInRange rangeBetweenParametersAndType syntaxComments with
                     | [] ->
                        aliasedTypePrint

                     | comment0 :: comment1Up ->
                        Print_followedBy aliasedTypePrint (Print_followedBy Print_linebreakIndented (ElmSyntaxPrintDefunctionalized_comments (List_cons comment0 comment1Up)))
                    )
                    Print_linebreakIndented
                )
                (Print_followedBy
                    ElmSyntaxPrintDefunctionalized_printExactlyEquals
                    (Print_followedBy
                        (Print_spaceOrLinebreakIndented parametersLineSpread)
                        (Print_followedBy
                            (Print_withIndentAtNextMultipleOf4
                                (Print_listReverseAndMapAndFlatten
                                    (fun (parameterPrint: Print_Print) ->
                                        Print_followedBy parameterPrint (Print_spaceOrLinebreakIndented parametersLineSpread)
                                    )
                                    parameterPrintsWithCommentsBeforeReverse
                                )
                            )
                            (Print_followedBy (Print_exactly (ElmSyntaxNode_value syntaxTypeAliasDeclaration.Name)) (Print_spaceOrLinebreakIndented parametersLineSpread))
                        )
                    )
                )
            )
        )
        (match syntaxTypeAliasDeclaration.Documentation with
         | ValueNone ->
            ElmSyntaxPrintDefunctionalized_printExactlyTypeSpaceAlias

         | ValueSome(ElmSyntaxNode_Node(documentationRange, documentation)) ->
            Print_followedBy
                ElmSyntaxPrintDefunctionalized_printExactlyTypeSpaceAlias
                (Print_followedBy
                    (ElmSyntaxPrintDefunctionalized_commentsBetweenDocumentationAndDeclaration
                        (ElmSyntaxPrintDefunctionalized_commentsInRange
                            { End = (ElmSyntaxNode_range syntaxTypeAliasDeclaration.Name).Start
                            ; Start = documentationRange.Start
                            }
