let ElmSyntaxPrintDefunctionalized_declarationChoiceType (syntaxComments: List<ElmSyntaxNode_Node<StringRope>>) (syntaxChoiceTypeDeclaration: Generated_Constructors_Documentation_Generics_Name<List<ElmSyntaxNode_Node<ElmSyntaxType_ValueConstructor>>, ValueOption<ElmSyntaxNode_Node<ElmSyntaxDocumentation_Documentation>>, List<ElmSyntaxNode_Node<StringRope>>, ElmSyntaxNode_Node<StringRope>>) : Print_Print =
    let parameterPrints: Generated_EndLocation_Reverse<ElmSyntaxRange_Location, List<Print_Print>> =
        List_foldl
            (fun (parameterName: ElmSyntaxNode_Node<StringRope>) (soFar: Generated_EndLocation_Reverse<ElmSyntaxRange_Location, List<Print_Print>>) ->
                let parameterPrintedRange: ElmSyntaxRange_Range =
                    ElmSyntaxNode_range parameterName
                
                let parameterNamePrint: Print_Print =
                    Print_exactly (ElmSyntaxNode_value parameterName)
                
                { EndLocation = parameterPrintedRange.End
                ; Reverse =
                    List_cons
                        (match
                            ElmSyntaxPrintDefunctionalized_commentsInRange
                                { End = parameterPrintedRange.Start
                                ; Start = soFar.EndLocation
                                }
                                syntaxComments
                         with
                         | [] ->
                            parameterNamePrint

                         | comment0 :: comment1Up ->
                            let commentsCollapsible: Generated_LineSpread_Print<Print_LineSpread, Print_Print> =
                                ElmSyntaxPrintDefunctionalized_collapsibleComments (List_cons comment0 comment1Up)
                            
