            ; Reverse = []
            }
            syntaxChoiceTypeDeclaration.Generics
    
    let parametersLineSpread: Print_LineSpread =
        Print_lineSpreadListMapAndCombine Print_lineSpread parameterPrints.Reverse
    
    let variantPrintsWithCommentsBeforeReverse: List<Print_Print> =
        (List_foldl
            (fun (ElmSyntaxNode_Node(variantRange, variant): ElmSyntaxNode_Node<Generated_Arguments_Name<List<ElmSyntaxNode_Node<ElmSyntaxTypeAnnotation_TypeAnnotation>>, ElmSyntaxNode_Node<StringRope>>>) (soFar: Generated_EndLocation_Reverse<ElmSyntaxRange_Location, List<Print_Print>>) ->
                let variantPrint: Print_Print =
                    ElmSyntaxPrintDefunctionalized_construct
                        { LineSpreadMinimum = Print_SingleLine
                        ; PrintArgumentParenthesizedIfSpaceSeparated = ElmSyntaxPrintDefunctionalized_typeParenthesizedIfSpaceSeparated
