let ElmWriter_writeExposureExpose (x: ElmSyntaxExposing_Exposing) : StructuredWriter_Writer =
    match x with
    | ElmSyntaxExposing_All(_) ->
        StructuredWriter_string (StringRopeOne "exposing (..)")

    | ElmSyntaxExposing_Explicit(exposeList) ->
        let diffLines: bool =
            ElmWriter_startOnDifferentLines (List.map ElmSyntaxNode_range exposeList)
        
        StructuredWriter_spaced
            [ StructuredWriter_string (StringRopeOne "exposing");
              StructuredWriter_parensComma diffLines (List.map ElmWriter_writeExpose exposeList)
            ]

let ElmWriter_writeDefaultModuleData ({ ExposingList = exposingList; ModuleName = moduleName }: Generated_ExposingList_ModuleName<ElmSyntaxNode_Node<ElmSyntaxExposing_Exposing>, ElmSyntaxNode_Node<ElmSyntaxModuleName_ModuleName>>) : StructuredWriter_Writer =
    StructuredWriter_spaced
        [ StructuredWriter_string (StringRopeOne "module");
          ElmWriter_writeModuleName (ElmSyntaxNode_value moduleName);
          ElmWriter_writeExposureExpose (ElmSyntaxNode_value exposingList)
        ]

let ElmWriter_writeEffectModuleData ({ Command = command; ExposingList = exposingList; ModuleName = moduleName; Subscription = subscription }: Generated_Command_ExposingList_ModuleName_Subscription<ValueOption<ElmSyntaxNode_Node<StringRope>>, ElmSyntaxNode_Node<ElmSyntaxExposing_Exposing>, ElmSyntaxNode_Node<ElmSyntaxModuleName_ModuleName>, ValueOption<ElmSyntaxNode_Node<StringRope>>>) : StructuredWriter_Writer =
    StructuredWriter_spaced
        [ StructuredWriter_string (StringRopeOne "effect");
          StructuredWriter_string (StringRopeOne "module");
          ElmWriter_writeModuleName (ElmSyntaxNode_value moduleName);
          ElmWriter_writeWhere (struct( command, subscription ));
          ElmWriter_writeExposureExpose (ElmSyntaxNode_value exposingList)
        ]

let ElmWriter_writeModule (m: ElmSyntaxModule_Module) : StructuredWriter_Writer =
    match m with
    | ElmSyntaxModule_NormalModule(defaultModuleData) ->
        ElmWriter_writeDefaultModuleData defaultModuleData

    | ElmSyntaxModule_PortModule(defaultModuleData) ->
        StructuredWriter_spaced
            [ StructuredWriter_string (StringRopeOne "port");
              ElmWriter_writeDefaultModuleData defaultModuleData
            ]

    | ElmSyntaxModule_EffectModule(effectModuleData) ->
        ElmWriter_writeEffectModuleData effectModuleData

let ElmWriter_writeImport ({ ExposingList = exposingList; ModuleAlias = moduleAlias; ModuleName = moduleName }: Generated_ExposingList_ModuleAlias_ModuleName<ValueOption<ElmSyntaxNode_Node<ElmSyntaxExposing_Exposing>>, ValueOption<ElmSyntaxNode_Node<ElmSyntaxModuleName_ModuleName>>, ElmSyntaxNode_Node<ElmSyntaxModuleName_ModuleName>>) : StructuredWriter_Writer =
    StructuredWriter_spaced
        [ StructuredWriter_string (StringRopeOne "import");
          ElmWriter_writeModuleName (ElmSyntaxNode_value moduleName);
          StructuredWriter_maybe
            (ValueOption.map
                ((>>)
                    ElmSyntaxNode_value
                    ((>>)
                        ElmWriter_writeModuleName
                        (fun (x: StructuredWriter_Writer) ->
                            StructuredWriter_spaced
                                [ StructuredWriter_string (StringRopeOne "as");
                                  x
                                ]
                        )
                    )
                )
                moduleAlias
            );
          StructuredWriter_maybe (ValueOption.map ((>>) ElmSyntaxNode_value ElmWriter_writeExposureExpose) exposingList)
        ]

let rec ElmWriter_writeExpression (ElmSyntaxNode_Node(range, inner): ElmSyntaxNode_Node<ElmSyntaxExpression_Expression>) : StructuredWriter_Writer =
    let writeRecordSetter
        ((struct( name, expr )):
            (struct(
              ElmSyntaxNode_Node<StringRope>
            * ElmSyntaxNode_Node<ElmSyntaxExpression_Expression>
            ))
        )
        : (struct(
            ElmSyntaxRange_Range
          * StructuredWriter_Writer
          )) =
        (struct(
          ElmSyntaxNode_range expr
        , StructuredWriter_spaced
            [ StructuredWriter_string (ElmSyntaxNode_value name);
              StructuredWriter_string (StringRopeOne "=");
              ElmWriter_writeExpression expr
            ]
        ))
    
    let sepHelper
        (f: bool -> List<StructuredWriter_Writer> -> StructuredWriter_Writer)
        (l:
            List<
                (struct(
                  ElmSyntaxRange_Range
                * StructuredWriter_Writer
                ))
                >
        )
        : StructuredWriter_Writer =
        let diffLines: bool =
            ElmWriter_startOnDifferentLines (List.map Tuple_first l)
        
        f diffLines (List.map Tuple_second l)
    
    let recurRangeHelper
        (ElmSyntaxNode_Node(x, y): ElmSyntaxNode_Node<ElmSyntaxExpression_Expression>)
        : (struct(
            ElmSyntaxRange_Range
          * StructuredWriter_Writer
          )) =
        (struct( x, ElmWriter_writeExpression (ElmSyntaxNode_Node (struct( x, y ))) ))
    
    match inner with
    | ElmSyntaxExpression_UnitExpr ->
        StructuredWriter_string (StringRopeOne "()")

    | ElmSyntaxExpression_Application(xs) ->
        match xs with
        | [] ->
            StructuredWriter_epsilon

        | [ x ] ->
            ElmWriter_writeExpression x

        | x :: rest ->
            StructuredWriter_spaced
                [ ElmWriter_writeExpression x;
                  sepHelper StructuredWriter_sepBySpace (List.map recurRangeHelper rest)
                ]

    | ElmSyntaxExpression_OperatorApplication(x, dir, left, right) ->
        match dir with
        | ElmSyntaxInfix_Left ->
            sepHelper
                StructuredWriter_sepBySpace
                [ (struct( ElmSyntaxNode_range left, ElmWriter_writeExpression left ));
                  (struct(
                    range
                  , StructuredWriter_spaced
                        [ StructuredWriter_string x;
                          ElmWriter_writeExpression right
                        ]
                  ))
                ]

        | ElmSyntaxInfix_Right ->
            sepHelper
                StructuredWriter_sepBySpace
                [ (struct(
                    ElmSyntaxNode_range left
                  , StructuredWriter_spaced
                        [ ElmWriter_writeExpression left;
                          StructuredWriter_string x
                        ]
                  ));
                  (struct( ElmSyntaxNode_range right, ElmWriter_writeExpression right ))
                ]

        | ElmSyntaxInfix_Non ->
            sepHelper
                StructuredWriter_sepBySpace
                [ (struct(
                    ElmSyntaxNode_range left
                  , StructuredWriter_spaced
                        [ ElmWriter_writeExpression left;
                          StructuredWriter_string x
                        ]
                  ));
                  (struct( ElmSyntaxNode_range right, ElmWriter_writeExpression right ))
                ]

    | ElmSyntaxExpression_FunctionOrValue(moduleName, name) ->
        match moduleName with
        | [] ->
            StructuredWriter_string name

        | _ ->
            StructuredWriter_join
                [ ElmWriter_writeModuleName moduleName;
                  StructuredWriter_string (StringRopeOne ".");
                  StructuredWriter_string name
                ]

    | ElmSyntaxExpression_IfBlock(condition, thenCase, elseCase) ->
        StructuredWriter_breaked
            [ StructuredWriter_spaced
                [ StructuredWriter_string (StringRopeOne "if");
                  ElmWriter_writeExpression condition;
                  StructuredWriter_string (StringRopeOne "then")
                ];
              StructuredWriter_indent 2L (ElmWriter_writeExpression thenCase);
              StructuredWriter_string (StringRopeOne "else");
              StructuredWriter_indent 2L (ElmWriter_writeExpression elseCase)
            ]

    | ElmSyntaxExpression_PrefixOperator(x) ->
        StructuredWriter_string (String_append (StringRopeOne "(") (String_append x (StringRopeOne ")")))

    | ElmSyntaxExpression_Operator(x) ->
        StructuredWriter_string x

    | ElmSyntaxExpression_Hex(h) ->
        StructuredWriter_join
            [ StructuredWriter_string (StringRopeOne "0x");
              StructuredWriter_string (Hex_toString h)
            ]

    | ElmSyntaxExpression_Integer(i) ->
        StructuredWriter_string (String_fromInt i)

    | ElmSyntaxExpression_Floatable(f) ->
        StructuredWriter_string (String_fromFloat f)

    | ElmSyntaxExpression_Negation(x) ->
        StructuredWriter_append (StructuredWriter_string (StringRopeOne "-")) (ElmWriter_writeExpression x)

    | ElmSyntaxExpression_Literal(s) ->
        StructuredWriter_string (String_append (StringRopeOne "\"") (String_append s (StringRopeOne "\"")))

    | ElmSyntaxExpression_CharLiteral(c) ->
        ElmWriter_writeChar c

    | ElmSyntaxExpression_TupledExpression(t) ->
        StructuredWriter_join
            [ StructuredWriter_string (StringRopeOne "(");
              sepHelper StructuredWriter_sepByComma (List.map recurRangeHelper t);
              StructuredWriter_string (StringRopeOne ")")
            ]

    | ElmSyntaxExpression_ParenthesizedExpression(x) ->
        StructuredWriter_join
            [ StructuredWriter_string (StringRopeOne "(");
              ElmWriter_writeExpression x;
              StructuredWriter_string (StringRopeOne ")")
            ]

    | ElmSyntaxExpression_LetExpression(letBlock) ->
        StructuredWriter_breaked
            [ StructuredWriter_string (StringRopeOne "let");
              StructuredWriter_indent 2L (StructuredWriter_breaked (List.map ElmWriter_writeLetDeclaration letBlock.Declarations));
              StructuredWriter_string (StringRopeOne "in");
              StructuredWriter_indent 2L (ElmWriter_writeExpression letBlock.Expression)
            ]

    | ElmSyntaxExpression_CaseExpression(caseBlock) ->
        let writeCaseBranch
            ((struct( pattern, expression )):
                (struct(
                  ElmSyntaxNode_Node<ElmSyntaxPattern_Pattern>
                * ElmSyntaxNode_Node<ElmSyntaxExpression_Expression>
                ))
            )
            : StructuredWriter_Writer =
            StructuredWriter_indent
                2L
                (StructuredWriter_breaked
                    [ StructuredWriter_spaced
                        [ ElmWriter_writePattern pattern;
                          StructuredWriter_string (StringRopeOne "->")
                        ];
                      StructuredWriter_indent 2L (ElmWriter_writeExpression expression)
                    ]
                )
        
        StructuredWriter_breaked
            [ StructuredWriter_string (StringRopeOne "");
              StructuredWriter_spaced
                [ StructuredWriter_string (StringRopeOne "case");
                  ElmWriter_writeExpression caseBlock.Expression;
                  StructuredWriter_string (StringRopeOne "of")
                ];
              StructuredWriter_breaked (List.map writeCaseBranch caseBlock.Cases);
              StructuredWriter_string (StringRopeOne "")
            ]

    | ElmSyntaxExpression_LambdaExpression(lambda) ->
        StructuredWriter_spaced
            [ StructuredWriter_join
                [ StructuredWriter_string (StringRopeOne "\\");
                  StructuredWriter_spaced (List.map ElmWriter_writePattern lambda.Args)
                ];
              StructuredWriter_string (StringRopeOne "->");
              ElmWriter_writeExpression lambda.Expression
            ]

    | ElmSyntaxExpression_RecordExpr(setters) ->
        sepHelper StructuredWriter_bracesComma (List.map ((>>) ElmSyntaxNode_value writeRecordSetter) setters)

    | ElmSyntaxExpression_ListExpr(xs) ->
        sepHelper StructuredWriter_bracketsComma (List.map recurRangeHelper xs)

    | ElmSyntaxExpression_RecordAccess(expression, accessor) ->
        StructuredWriter_join
            [ ElmWriter_writeExpression expression;
              StructuredWriter_string (StringRopeOne ".");
              StructuredWriter_string (ElmSyntaxNode_value accessor)
            ]

    | ElmSyntaxExpression_RecordAccessFunction(s) ->
        if String_startsWith (StringRopeOne ".") s then
            StructuredWriter_string s

        else
            StructuredWriter_join
                [ StructuredWriter_string (StringRopeOne ".");
                  StructuredWriter_string s
                ]

    | ElmSyntaxExpression_RecordUpdateExpression(name, updates) ->
        StructuredWriter_spaced
            [ StructuredWriter_string (StringRopeOne "{");
              StructuredWriter_string (ElmSyntaxNode_value name);
              StructuredWriter_string (StringRopeOne "|");
              sepHelper StructuredWriter_sepByComma (List.map ((>>) ElmSyntaxNode_value writeRecordSetter) updates);
              StructuredWriter_string (StringRopeOne "}")
            ]

    | ElmSyntaxExpression_GLSLExpression(s) ->
        StructuredWriter_join
            [ StructuredWriter_string (StringRopeOne "[glsl|");
              StructuredWriter_string s;
              StructuredWriter_string (StringRopeOne "|]")
            ]

and ElmWriter_writeLetDeclaration (ElmSyntaxNode_Node(_, letDeclaration): ElmSyntaxNode_Node<ElmSyntaxExpression_LetDeclaration>) : StructuredWriter_Writer =
    match letDeclaration with
    | ElmSyntaxExpression_LetFunction(function_) ->
        ElmWriter_writeFunction function_

    | ElmSyntaxExpression_LetDestructuring(pattern, expression) ->
        ElmWriter_writeDestructuring pattern expression

and ElmWriter_writeDestructuring (pattern: ElmSyntaxNode_Node<ElmSyntaxPattern_Pattern>) (expression: ElmSyntaxNode_Node<ElmSyntaxExpression_Expression>) : StructuredWriter_Writer =
    StructuredWriter_breaked
        [ StructuredWriter_spaced
            [ ElmWriter_writePattern pattern;
              StructuredWriter_string (StringRopeOne "=")
            ];
          StructuredWriter_indent 4L (ElmWriter_writeExpression expression)
        ]

and ElmWriter_writeFunction ({ Declaration = declaration; Documentation = documentation; Signature = signature }: Generated_Declaration_Documentation_Signature<ElmSyntaxNode_Node<ElmSyntaxExpression_FunctionImplementation>, ValueOption<ElmSyntaxNode_Node<ElmSyntaxDocumentation_Documentation>>, ValueOption<ElmSyntaxNode_Node<ElmSyntaxSignature_Signature>>>) : StructuredWriter_Writer =
    StructuredWriter_breaked
        [ StructuredWriter_maybe (ValueOption.map ElmWriter_writeDocumentation documentation);
          StructuredWriter_maybe (ValueOption.map ((>>) ElmSyntaxNode_value ElmWriter_writeSignature) signature);
          ElmWriter_writeFunctionImplementation (ElmSyntaxNode_value declaration)
        ]

and ElmWriter_writeFunctionImplementation (declaration: Generated_Arguments_Expression_Name<List<ElmSyntaxNode_Node<ElmSyntaxPattern_Pattern>>, ElmSyntaxNode_Node<ElmSyntaxExpression_Expression>, ElmSyntaxNode_Node<StringRope>>) : StructuredWriter_Writer =
    StructuredWriter_breaked
        [ StructuredWriter_spaced
            [ StructuredWriter_string (ElmSyntaxNode_value declaration.Name);
              StructuredWriter_spaced (List.map ElmWriter_writePattern declaration.Arguments);
              StructuredWriter_string (StringRopeOne "=")
            ];
          StructuredWriter_indent 4L (ElmWriter_writeExpression declaration.Expression)
        ]

let ElmSyntaxNode_map (f: 'a -> 'b) (ElmSyntaxNode_Node(r, a): ElmSyntaxNode_Node<'a>) : ElmSyntaxNode_Node<'b> =
    ElmSyntaxNode_Node (struct( r, f a ))

let rec ElmSyntaxPrintDefunctionalized_importsCombine (syntaxImports: List<ElmSyntaxNode_Node<ElmSyntaxImport_Import>>) : List<ElmSyntaxNode_Node<ElmSyntaxImport_Import>> =
    match syntaxImports with
    | [] ->
        []

    | [ onlyImport ] ->
        [ ElmSyntaxNode_map ElmSyntaxPrintDefunctionalized_importToNormal onlyImport ]

    | ElmSyntaxNode_Node(import0Range, import0) :: (ElmSyntaxNode_Node(import1Range, import1) :: import2Up) ->
        if Basics_eq (ElmSyntaxNode_value import0.ModuleName) (ElmSyntaxNode_value import1.ModuleName) then
            ElmSyntaxPrintDefunctionalized_importsCombine (List_cons (ElmSyntaxNode_Node (struct( import1Range, ElmSyntaxPrintDefunctionalized_importsMerge import0 import1 ))) import2Up)

        else
            List_cons (ElmSyntaxNode_Node (struct( import0Range, ElmSyntaxPrintDefunctionalized_importToNormal import0 ))) (ElmSyntaxPrintDefunctionalized_importsCombine (List_cons (ElmSyntaxNode_Node (struct( import1Range, import1 ))) import2Up))

let ElmSyntaxPrintDefunctionalized_imports (syntaxComments: List<ElmSyntaxNode_Node<StringRope>>) (syntaxImports: List<ElmSyntaxNode_Node<Generated_ExposingList_ModuleAlias_ModuleName<ValueOption<ElmSyntaxNode_Node<ElmSyntaxExposing_Exposing>>, ValueOption<ElmSyntaxNode_Node<ElmSyntaxModuleName_ModuleName>>, ElmSyntaxNode_Node<ElmSyntaxModuleName_ModuleName>>>>) : Print_Print =
    match syntaxImports with
    | [] ->
        Print_empty

    | ElmSyntaxNode_Node(import0Range, import0) :: imports1Up ->
        let commentsBetweenImports: List<StringRope> =
            (List_foldl
                (fun (ElmSyntaxNode_Node(importRange, _): ElmSyntaxNode_Node<Generated_ExposingList_ModuleAlias_ModuleName<ValueOption<ElmSyntaxNode_Node<ElmSyntaxExposing_Exposing>>, ValueOption<ElmSyntaxNode_Node<ElmSyntaxModuleName_ModuleName>>, ElmSyntaxNode_Node<ElmSyntaxModuleName_ModuleName>>>) (soFar: Generated_CommentsBetweenImports_PreviousImportRange<List<StringRope>, Generated_End_Start<ElmSyntaxRange_Location, ElmSyntaxRange_Location>>) ->
                    { CommentsBetweenImports =
                        List.append
                            soFar.CommentsBetweenImports
                            (ElmSyntaxPrintDefunctionalized_commentsInRange
                                { End = importRange.Start
                                ; Start = soFar.PreviousImportRange.End
                                }
                                syntaxComments
                            )
                    ; PreviousImportRange = importRange
                    }
                )
                { CommentsBetweenImports = []
                ; PreviousImportRange = import0Range
                }
                (List_cons (ElmSyntaxNode_Node (struct( import0Range, import0 ))) imports1Up)
            ).CommentsBetweenImports
        
        Print_followedBy
            (Print_listMapAndIntersperseAndFlatten
                (fun (syntaxImport: ElmSyntaxNode_Node<ElmSyntaxImport_Import>) ->
                    ElmSyntaxPrintDefunctionalized_import_ syntaxComments syntaxImport
                )
                Print_linebreak
                (ElmSyntaxPrintDefunctionalized_importsCombine
                    (List_sortWith
                        (fun (ElmSyntaxNode_Node(_, a): ElmSyntaxNode_Node<Generated_ExposingList_ModuleAlias_ModuleName<ValueOption<ElmSyntaxNode_Node<ElmSyntaxExposing_Exposing>>, ValueOption<ElmSyntaxNode_Node<ElmSyntaxModuleName_ModuleName>>, ElmSyntaxNode_Node<ElmSyntaxModuleName_ModuleName>>>) (ElmSyntaxNode_Node(_, b): ElmSyntaxNode_Node<Generated_ExposingList_ModuleAlias_ModuleName<ValueOption<ElmSyntaxNode_Node<ElmSyntaxExposing_Exposing>>, ValueOption<ElmSyntaxNode_Node<ElmSyntaxModuleName_ModuleName>>, ElmSyntaxNode_Node<ElmSyntaxModuleName_ModuleName>>>) ->
                            Basics_compare (ElmSyntaxNode_value a.ModuleName) (ElmSyntaxNode_value b.ModuleName)
                        )
                        (List_cons (ElmSyntaxNode_Node (struct( import0Range, import0 ))) imports1Up)
                    )
                )
            )
            (match commentsBetweenImports with
             | [] ->
                Print_empty

             | comment0 :: comment1Up ->
                Print_followedBy Print_linebreak (ElmSyntaxPrintDefunctionalized_moduleLevelComments (List_cons comment0 comment1Up))
            )

let ElmSyntaxPrint_imports (syntaxComments: List<ElmSyntaxNode_Node<StringRope>>) (syntaxImports: List<ElmSyntaxNode_Node<ElmSyntaxImport_Import>>) : Generated_Indent<int64> -> StringRope =
    fun (state: Generated_Indent<int64>) ->
        Print_toStringWithIndent state.Indent (ElmSyntaxPrintDefunctionalized_imports syntaxComments syntaxImports)

let ElmSyntaxNode_encode (f: 'a -> System.Text.Json.Nodes.JsonNode) (ElmSyntaxNode_Node(r, v): ElmSyntaxNode_Node<'a>) : System.Text.Json.Nodes.JsonNode =
    JsonEncode_object
        [ (struct( StringRopeOne "range", ElmSyntaxRange_encode r ));
          (struct( StringRopeOne "value", f v ))
        ]

let ElmSyntaxNode_empty (a: 'a) : ElmSyntaxNode_Node<'a> =
    ElmSyntaxNode_Node (struct( ElmSyntaxRange_empty, a ))

let ElmWriter_wrapInSurroundingParentheses (node: ElmSyntaxNode_Node<ElmSyntaxTypeAnnotation_TypeAnnotation>) : ElmSyntaxNode_Node<ElmSyntaxTypeAnnotation_TypeAnnotation> =
    let withParens (n: ElmSyntaxNode_Node<ElmSyntaxTypeAnnotation_TypeAnnotation>) : ElmSyntaxNode_Node<ElmSyntaxTypeAnnotation_TypeAnnotation> =
        ElmSyntaxNode_empty (ElmSyntaxTypeAnnotation_Tupled [ n ])
    
    match ElmSyntaxNode_value node with
    | ElmSyntaxTypeAnnotation_FunctionTypeAnnotation(_, _) ->
        withParens node

    | ElmSyntaxTypeAnnotation_Typed(_, typeParameters) ->
        match typeParameters with
        | [] ->
            node

        | _ ->
            withParens node

    | _ ->
        node

let ElmWriter_writeValueConstructor ({ Arguments = arguments; Name = name }: Generated_Arguments_Name<List<ElmSyntaxNode_Node<ElmSyntaxTypeAnnotation_TypeAnnotation>>, ElmSyntaxNode_Node<StringRope>>) : StructuredWriter_Writer =
    StructuredWriter_spaced (List_cons (StructuredWriter_string (ElmSyntaxNode_value name)) (List.map ((>>) ElmWriter_wrapInSurroundingParentheses ElmWriter_writeTypeAnnotation) arguments))

let ElmWriter_writeType (type__: Generated_Constructors_Documentation_Generics_Name<List<ElmSyntaxNode_Node<ElmSyntaxType_ValueConstructor>>, ValueOption<ElmSyntaxNode_Node<ElmSyntaxDocumentation_Documentation>>, List<ElmSyntaxNode_Node<StringRope>>, ElmSyntaxNode_Node<StringRope>>) : StructuredWriter_Writer =
    StructuredWriter_breaked
        [ StructuredWriter_spaced
            [ StructuredWriter_string (StringRopeOne "type");
              StructuredWriter_string (ElmSyntaxNode_value type__.Name);
              StructuredWriter_spaced (List.map ((>>) ElmSyntaxNode_value StructuredWriter_string) type__.Generics)
            ];
          let diffLines: bool =
            ElmWriter_startOnDifferentLines (List.map ElmSyntaxNode_range type__.Constructors)
          
          StructuredWriter_indent 4L (StructuredWriter_sepBy (struct( StringRopeOne "= ", StringRopeOne " | ", StringRopeOne "" )) diffLines (List.map ((>>) ElmSyntaxNode_value ElmWriter_writeValueConstructor) type__.Constructors))
        ]

let ElmWriter_writeDeclaration (ElmSyntaxNode_Node(_, decl): ElmSyntaxNode_Node<ElmSyntaxDeclaration_Declaration>) : StructuredWriter_Writer =
    match decl with
    | ElmSyntaxDeclaration_FunctionDeclaration(function_) ->
        ElmWriter_writeFunction function_

    | ElmSyntaxDeclaration_AliasDeclaration(typeAlias) ->
        ElmWriter_writeTypeAlias typeAlias

    | ElmSyntaxDeclaration_CustomTypeDeclaration(type__) ->
        ElmWriter_writeType type__

    | ElmSyntaxDeclaration_PortDeclaration(p) ->
        ElmWriter_writePortDeclaration p

    | ElmSyntaxDeclaration_InfixDeclaration(i) ->
        ElmWriter_writeInfix i

    | ElmSyntaxDeclaration_Destructuring(pattern, expression) ->
        ElmWriter_writeDestructuring pattern expression

let ElmWriter_writeFile (file: Generated_Comments_Declarations_Imports_ModuleDefinition<List<ElmSyntaxNode_Node<ElmSyntaxComments_Comment>>, List<ElmSyntaxNode_Node<ElmSyntaxDeclaration_Declaration>>, List<ElmSyntaxNode_Node<ElmSyntaxImport_Import>>, ElmSyntaxNode_Node<ElmSyntaxModule_Module>>) : StructuredWriter_Writer =
    StructuredWriter_breaked
        [ ElmWriter_writeModule (ElmSyntaxNode_value file.ModuleDefinition);
          StructuredWriter_breaked (List.map ((>>) ElmSyntaxNode_value ElmWriter_writeImport) file.Imports);
          StructuredWriter_breaked (List.map ElmWriter_writeDeclaration file.Declarations)
        ]

let ElmSyntaxNode_decoder (sub: JsonDecode_Decoder<'a>) : JsonDecode_Decoder<ElmSyntaxNode_Node<'a>> =
    JsonDecode_map2
        (fun (generated_0: ElmSyntaxRange_Range) (generated_1: 'a) ->
            ElmSyntaxNode_Node (struct( generated_0, generated_1 ))
        )
        (JsonDecode_field (StringRopeOne "range") ElmSyntaxRange_decoder)
        (JsonDecode_field (StringRopeOne "value") sub)

let ElmSyntaxNode_combine (f: ElmSyntaxNode_Node<'a> -> ElmSyntaxNode_Node<'b> -> 'c) ((ElmSyntaxNode_Node({ Start = start }, _) as a): ElmSyntaxNode_Node<'a>) ((ElmSyntaxNode_Node({ End = end_ }, _) as b): ElmSyntaxNode_Node<'b>) : ElmSyntaxNode_Node<'c> =
    ElmSyntaxNode_Node
        (struct(
          { End = end_
          ; Start = start
          }
        , f a b
