    match d with
    | ElmSyntaxInfix_Left ->
        JsonEncode_string (StringRopeOne "left")

    | ElmSyntaxInfix_Right ->
        JsonEncode_string (StringRopeOne "right")

    | ElmSyntaxInfix_Non ->
        JsonEncode_string (StringRopeOne "non")

let ElmSyntaxInfix_encode (inf: Generated_Direction_Function_Operator_Precedence<ElmSyntaxNode_Node<ElmSyntaxInfix_InfixDirection>, ElmSyntaxNode_Node<StringRope>, ElmSyntaxNode_Node<StringRope>, ElmSyntaxNode_Node<int64>>) : System.Text.Json.Nodes.JsonNode =
    JsonEncode_object
        [ (struct( StringRopeOne "direction", ElmSyntaxNode_encode ElmSyntaxInfix_encodeDirection inf.Direction ));
          (struct( StringRopeOne "precedence", ElmSyntaxNode_encode JsonEncode_int inf.Precedence ));
          (struct( StringRopeOne "operator", ElmSyntaxNode_encode JsonEncode_string inf.Operator ));
          (struct( StringRopeOne "function", ElmSyntaxNode_encode JsonEncode_string inf.Function ))
        ]

let ElmSyntaxInfix_decodeDirection: JsonDecode_Decoder<ElmSyntaxInfix_InfixDirection> =
    JsonDecode_andThen
        (fun (v: StringRope) ->
            match v with
            | StringRopeOne("left") ->
                JsonDecode_succeed ElmSyntaxInfix_Left

            | StringRopeOne("right") ->
                JsonDecode_succeed ElmSyntaxInfix_Right

            | StringRopeOne("non") ->
                JsonDecode_succeed ElmSyntaxInfix_Non

            | _ ->
                JsonDecode_fail (StringRopeOne "Invalid direction")
        )
        JsonDecode_string

let ElmSyntaxInfix_decoder: JsonDecode_Decoder<ElmSyntaxInfix_Infix> =
    JsonDecode_map4
        (fun (generated_Direction: ElmSyntaxNode_Node<ElmSyntaxInfix_InfixDirection>) (generated_Precedence: ElmSyntaxNode_Node<int64>) (generated_Operator: ElmSyntaxNode_Node<StringRope>) (generated_Function: ElmSyntaxNode_Node<StringRope>) ->
            { Direction = generated_Direction
            ; Function = generated_Function
            ; Operator = generated_Operator
            ; Precedence = generated_Precedence
            }
        )
        (JsonDecode_field (StringRopeOne "direction") (ElmSyntaxNode_decoder ElmSyntaxInfix_decodeDirection))
        (JsonDecode_field (StringRopeOne "precedence") (ElmSyntaxNode_decoder JsonDecode_int))
        (JsonDecode_field (StringRopeOne "operator") (ElmSyntaxNode_decoder JsonDecode_string))
        (JsonDecode_field (StringRopeOne "function") (ElmSyntaxNode_decoder JsonDecode_string))

