let ElmSyntaxExpression_functionRange (function_: Generated_Declaration_Documentation_Signature<ElmSyntaxNode_Node<ElmSyntaxExpression_FunctionImplementation>, ValueOption<ElmSyntaxNode_Node<ElmSyntaxDocumentation_Documentation>>, ValueOption<ElmSyntaxNode_Node<ElmSyntaxSignature_Signature>>>) : Generated_End_Start<ElmSyntaxRange_Location, ElmSyntaxRange_Location> =
    let declarationRange: ElmSyntaxRange_Range =
        ElmSyntaxNode_range function_.Declaration
    
    let startRange: ElmSyntaxRange_Range =
        match function_.Documentation with
        | ValueSome(ElmSyntaxNode_Node(range, _)) ->
            range

        | ValueNone ->
            match function_.Signature with
            | ValueSome(ElmSyntaxNode_Node(range, _)) ->
                range

            | ValueNone ->
                declarationRange
    
    { End = declarationRange.End
    ; Start = startRange.Start
    }

