        true

    | StringRopeOne("*") ->
        true

    | StringRopeOne("<|") ->
        true

    | StringRopeOne("|>") ->
        true

    | StringRopeOne("||") ->
        true

    | StringRopeOne("<=") ->
        true

    | StringRopeOne(">=") ->
        true

    | StringRopeOne("|=") ->
        true

    | StringRopeOne("|.") ->
        true

    | StringRopeOne("//") ->
        true

    | StringRopeOne("</>") ->
        true

    | StringRopeOne("<?>") ->
        true

    | StringRopeOne("^") ->
        true

    | StringRopeOne("<<") ->
        true

    | StringRopeOne(">>") ->
        true

    | StringRopeOne("<") ->
        true

    | StringRopeOne(">") ->
        true

    | StringRopeOne("/") ->
        true

    | StringRopeOne("&&") ->
        true

    | StringRopeOne("-") ->
        true

    | _ ->
        false

let ElmParserTokens_equal: ParserFast_Parser<unit> =
    ParserFast_symbol (StringRopeOne "=") ()

let ElmParserTokens_charToHex (c: int) : int64 =
    match c with
    | 48 ->
        0L

    | 49 ->
        1L

    | 50 ->
        2L

    | 51 ->
        3L

    | 52 ->
        4L

    | 53 ->
        5L

    | 54 ->
        6L

    | 55 ->
        7L

    | 56 ->
        8L

    | 57 ->
        9L

    | 97 ->
        10L

    | 98 ->
        11L

    | 99 ->
        12L

    | 100 ->
        13L

    | 101 ->
        14L

    | 102 ->
        15L

    | 65 ->
        10L

    | 66 ->
        11L

    | 67 ->
        12L

    | 68 ->
        13L

    | 69 ->
        14L

    | _ ->
        15L

let ElmParserTokens_hexStringToInt (string_: StringRope) : int64 =
    (String_foldr
        (fun (c: int) (soFar: Generated_Exponent_Result<int64, int64>) ->
            { Exponent = (+) soFar.Exponent 1L
            ; Result = (+) soFar.Result ((*) (Basics_ipow 16L soFar.Exponent) (ElmParserTokens_charToHex c))
            }
        )
        { Exponent = 0L
        ; Result = 0L
        }
        string_
    ).Result

