let ElmParserLayout_problemTopIndentation<'a>: ParserFast_Parser<'a> =
    ParserFast_problem (StringRopeOne "must be on top indentation")

let ElmParserLayout_problemPositivelyIndented<'a>: ParserFast_Parser<'a> =
    ParserFast_problem (StringRopeOne "must be positively indented")

let ElmParserLayout_problemModuleLevelIndentation<'a>: ParserFast_Parser<'a> =
    ParserFast_problem (StringRopeOne "must be on module-level indentation")

let ElmParserLayout_positivelyIndentedPlusFollowedBy (extraIndent: int64) (nextParser: ParserFast_Parser<'a>) : ParserFast_Parser<'a> =
    ParserFast_columnIndentAndThen
        (fun (column: int64) (indent: int64) ->
            if (>) column ((+) indent extraIndent) then
                nextParser

            else
                ElmParserLayout_problemPositivelyIndented
        )

let ElmParserLayout_positivelyIndentedFollowedBy (nextParser: ParserFast_Parser<'a>) : ParserFast_Parser<'a> =
    ParserFast_columnIndentAndThen
        (fun (column: int64) (indent: int64) ->
            if (>) column indent then
                nextParser

            else
                ElmParserLayout_problemPositivelyIndented
        )

let ElmParserLayout_onTopIndentationFollowedBy (nextParser: ParserFast_Parser<'a>) : ParserFast_Parser<'a> =
    ParserFast_columnIndentAndThen
        (fun (column: int64) (indent: int64) ->
            if Basics_eq ((-) column indent) 0L then
                nextParser

            else
                ElmParserLayout_problemTopIndentation
        )

let ElmParserLayout_moduleLevelIndentationFollowedBy (nextParser: ParserFast_Parser<'a>) : ParserFast_Parser<'a> =
    ParserFast_columnAndThen
        (fun (column: int64) ->
            if Basics_eq column 1L then
                nextParser

            else
                ElmParserLayout_problemModuleLevelIndentation
        )

let ElmParserLayout_endsTopIndented (parser: ParserFast_Parser<'a>) : ParserFast_Parser<'a> =
    ParserFast_validateEndColumnIndentation
        (fun (column: int64) (indent: int64) ->
            Basics_eq ((-) column indent) 0L
        )
        (StringRopeOne "must be on top indentation")
        parser

let ElmParserLayout_endsPositivelyIndented (parser: ParserFast_Parser<'a>) : ParserFast_Parser<'a> =
    ParserFast_validateEndColumnIndentation
        (fun (column: int64) (indent: int64) ->
            (>) column indent
        )
        (StringRopeOne "must be positively indented")
        parser

