let ElmParserExpression_rangeMoveStartLeftByOneColumn (range: Generated_End_Start<ElmSyntaxRange_Location, Generated_Column_Row<int64, int64>>) : Generated_End_Start<ElmSyntaxRange_Location, Generated_Column_Row<int64, int64>> =
    { End = range.End
    ; Start =
        { Column = (-) range.Start.Column 1L
        ; Row = range.Start.Row
        }
    }

