let ElmParserExpression_negationWhitespaceProblem<'a>: ParserFast_Parser<'a> =
    ParserFast_problem (StringRopeOne "if a negation sign is not preceded by whitespace, it's considered subtraction")

let ElmParserExpression_errUnknownInfixOperator<'a>: Result_Result<StringRope, 'a> =
    Error (StringRopeOne "unknown infix operator")

let ElmParserExpression_applyExtensionRight (ElmParserExpression_ExtendRightByOperation(operation): ElmParserExpression_ExtensionRight) ((ElmSyntaxNode_Node(leftRange, _) as leftNode): ElmSyntaxNode_Node<ElmSyntaxExpression_Expression>) : ElmSyntaxNode_Node<ElmSyntaxExpression_Expression> =
    let (ElmSyntaxNode_Node(rightExpressionRange, _) as rightExpressionNode: ElmSyntaxNode_Node<ElmSyntaxExpression_Expression>) =
        operation.Expression
    
    ElmSyntaxNode_Node
        (struct(
          { End = rightExpressionRange.End
          ; Start = leftRange.Start
          }
        , ElmSyntaxExpression_OperatorApplication (struct( operation.Symbol, operation.Direction, leftNode, rightExpressionNode ))
        ))

let ElmParserExpression_allowedPrefixOperatorFollowedByClosingParensOneOf: ParserFast_Parser<ParserWithComments_WithComments<ElmSyntaxNode_Node<ElmSyntaxExpression_Expression>>> =
    ParserFast_whileWithoutLinebreakAnd2PartUtf16ValidateMapWithRangeBacktrackableFollowedBySymbol
        (fun (operatorRange: Generated_End_Start<Generated_Column_Row<int64, int64>, Generated_Column_Row<int64, int64>>) (operator: StringRope) ->
            { Comments = Rope_empty
            ; Syntax =
                ElmSyntaxNode_Node
                    (struct(
                      { End =
                            { Column = (+) operatorRange.End.Column 1L
                            ; Row = operatorRange.End.Row
                            }
                      ; Start =
                            { Column = (-) operatorRange.Start.Column 1L
                            ; Row = operatorRange.Start.Row
                            }
                      }
                    , ElmSyntaxExpression_PrefixOperator operator
                    ))
            }
        )
        ElmParserTokens_isOperatorSymbolChar
        ElmParserTokens_isAllowedOperatorToken
        (StringRopeOne ")")

let ElmParserComments_problemUnexpectedDocumentation<'a>: ParserFast_Parser<'a> =
    ParserFast_problem (StringRopeOne "unexpected documentation comment")

let ElmJsonUtil_encodeTyped (x: StringRope) (v: System.Text.Json.Nodes.JsonNode) : System.Text.Json.Nodes.JsonNode =
    JsonEncode_object
        [ (struct( StringRopeOne "type", JsonEncode_string x ));
          (struct( x, v ))
        ]

let ElmSyntaxExposing_encodeTopLevelExpose: ElmSyntaxNode_Node<ElmSyntaxExposing_TopLevelExpose> -> System.Text.Json.Nodes.JsonNode =
    ElmSyntaxNode_encode
        (fun (exp: ElmSyntaxExposing_TopLevelExpose) ->
            match exp with
            | ElmSyntaxExposing_InfixExpose(x) ->
                ElmJsonUtil_encodeTyped (StringRopeOne "infix") (JsonEncode_object [ (struct( StringRopeOne "name", JsonEncode_string x )) ])

            | ElmSyntaxExposing_FunctionExpose(x) ->
                ElmJsonUtil_encodeTyped (StringRopeOne "function") (JsonEncode_object [ (struct( StringRopeOne "name", JsonEncode_string x )) ])

            | ElmSyntaxExposing_TypeOrAliasExpose(x) ->
                ElmJsonUtil_encodeTyped (StringRopeOne "typeOrAlias") (JsonEncode_object [ (struct( StringRopeOne "name", JsonEncode_string x )) ])

            | ElmSyntaxExposing_TypeExpose(exposedType) ->
                ElmJsonUtil_encodeTyped (StringRopeOne "typeexpose") (ElmSyntaxExposing_encodeExposedType exposedType)
        )

let ElmSyntaxExposing_encode (exp: ElmSyntaxExposing_Exposing) : System.Text.Json.Nodes.JsonNode =
    match exp with
    | ElmSyntaxExposing_All(r) ->
        ElmJsonUtil_encodeTyped (StringRopeOne "all") (ElmSyntaxRange_encode r)

    | ElmSyntaxExposing_Explicit(l) ->
        ElmJsonUtil_encodeTyped (StringRopeOne "explicit") (JsonEncode_list ElmSyntaxExposing_encodeTopLevelExpose l)

let ElmSyntaxImport_encode ({ ExposingList = exposingList; ModuleAlias = moduleAlias; ModuleName = moduleName }: Generated_ExposingList_ModuleAlias_ModuleName<ValueOption<ElmSyntaxNode_Node<ElmSyntaxExposing_Exposing>>, ValueOption<ElmSyntaxNode_Node<ElmSyntaxModuleName_ModuleName>>, ElmSyntaxNode_Node<ElmSyntaxModuleName_ModuleName>>) : System.Text.Json.Nodes.JsonNode =
