        [ (struct( StringRopeOne "moduleName", ElmSyntaxNode_encode ElmSyntaxModuleName_encode moduleName ));
          (struct( StringRopeOne "moduleAlias", ValueOption.defaultValue JsonEncode_null (ValueOption.map (ElmSyntaxNode_encode ElmSyntaxModuleName_encode) moduleAlias) ));
          (struct( StringRopeOne "exposingList", ValueOption.defaultValue JsonEncode_null (ValueOption.map (ElmSyntaxNode_encode ElmSyntaxExposing_encode) exposingList) ))
        ]

let ElmSyntaxModule_encodeDefaultModuleData (moduleData: Generated_ExposingList_ModuleName<ElmSyntaxNode_Node<ElmSyntaxExposing_Exposing>, ElmSyntaxNode_Node<ElmSyntaxModuleName_ModuleName>>) : System.Text.Json.Nodes.JsonNode =
    JsonEncode_object
        [ (struct( StringRopeOne "moduleName", ElmSyntaxNode_encode ElmSyntaxModuleName_encode moduleData.ModuleName ));
          (struct( StringRopeOne "exposingList", ElmSyntaxNode_encode ElmSyntaxExposing_encode moduleData.ExposingList ))
        ]

let ElmSyntaxModule_encodeEffectModuleData (moduleData: Generated_Command_ExposingList_ModuleName_Subscription<ValueOption<ElmSyntaxNode_Node<StringRope>>, ElmSyntaxNode_Node<ElmSyntaxExposing_Exposing>, ElmSyntaxNode_Node<ElmSyntaxModuleName_ModuleName>, ValueOption<ElmSyntaxNode_Node<StringRope>>>) : System.Text.Json.Nodes.JsonNode =
    JsonEncode_object
        [ (struct( StringRopeOne "moduleName", ElmSyntaxNode_encode ElmSyntaxModuleName_encode moduleData.ModuleName ));
          (struct( StringRopeOne "exposingList", ElmSyntaxNode_encode ElmSyntaxExposing_encode moduleData.ExposingList ));
