          (struct( StringRopeOne "subscription", ValueOption.defaultValue JsonEncode_null (ValueOption.map (ElmSyntaxNode_encode JsonEncode_string) moduleData.Subscription) ))
        ]

let ElmSyntaxModule_encode (m: ElmSyntaxModule_Module) : System.Text.Json.Nodes.JsonNode =
    match m with
    | ElmSyntaxModule_NormalModule(d) ->
        ElmJsonUtil_encodeTyped (StringRopeOne "normal") (ElmSyntaxModule_encodeDefaultModuleData d)

    | ElmSyntaxModule_PortModule(d) ->
        ElmJsonUtil_encodeTyped (StringRopeOne "port") (ElmSyntaxModule_encodeDefaultModuleData d)

    | ElmSyntaxModule_EffectModule(d) ->
        ElmJsonUtil_encodeTyped (StringRopeOne "effect") (ElmSyntaxModule_encodeEffectModuleData d)

let rec ElmSyntaxPattern_encode (pattern: ElmSyntaxPattern_Pattern) : System.Text.Json.Nodes.JsonNode =
    match pattern with
    | ElmSyntaxPattern_AllPattern ->
        ElmJsonUtil_encodeTyped (StringRopeOne "all") (JsonEncode_object [])

    | ElmSyntaxPattern_UnitPattern ->
        ElmJsonUtil_encodeTyped (StringRopeOne "unit") (JsonEncode_object [])

    | ElmSyntaxPattern_CharPattern(c) ->
        ElmJsonUtil_encodeTyped (StringRopeOne "char") (JsonEncode_object [ (struct( StringRopeOne "value", JsonEncode_string (String_fromChar c) )) ])

    | ElmSyntaxPattern_StringPattern(v) ->
        ElmJsonUtil_encodeTyped (StringRopeOne "string") (JsonEncode_object [ (struct( StringRopeOne "value", JsonEncode_string v )) ])

    | ElmSyntaxPattern_HexPattern(h) ->
        ElmJsonUtil_encodeTyped (StringRopeOne "hex") (JsonEncode_object [ (struct( StringRopeOne "value", JsonEncode_int h )) ])

    | ElmSyntaxPattern_IntPattern(i) ->
        ElmJsonUtil_encodeTyped (StringRopeOne "int") (JsonEncode_object [ (struct( StringRopeOne "value", JsonEncode_int i )) ])

    | ElmSyntaxPattern_FloatPattern(f) ->
        ElmJsonUtil_encodeTyped (StringRopeOne "float") (JsonEncode_object [ (struct( StringRopeOne "value", JsonEncode_float f )) ])

    | ElmSyntaxPattern_TuplePattern(patterns) ->
        ElmJsonUtil_encodeTyped (StringRopeOne "tuple") (JsonEncode_object [ (struct( StringRopeOne "value", JsonEncode_list (ElmSyntaxNode_encode ElmSyntaxPattern_encode) patterns )) ])

    | ElmSyntaxPattern_RecordPattern(pointers) ->
        ElmJsonUtil_encodeTyped (StringRopeOne "record") (JsonEncode_object [ (struct( StringRopeOne "value", JsonEncode_list (ElmSyntaxNode_encode JsonEncode_string) pointers )) ])

    | ElmSyntaxPattern_UnConsPattern(p1, p2) ->
        ElmJsonUtil_encodeTyped
            (StringRopeOne "uncons")
            (JsonEncode_object
                [ (struct( StringRopeOne "left", ElmSyntaxNode_encode ElmSyntaxPattern_encode p1 ));
                  (struct( StringRopeOne "right", ElmSyntaxNode_encode ElmSyntaxPattern_encode p2 ))
                ]
            )

    | ElmSyntaxPattern_ListPattern(patterns) ->
        ElmJsonUtil_encodeTyped (StringRopeOne "list") (JsonEncode_object [ (struct( StringRopeOne "value", JsonEncode_list (ElmSyntaxNode_encode ElmSyntaxPattern_encode) patterns )) ])

    | ElmSyntaxPattern_VarPattern(name) ->
        ElmJsonUtil_encodeTyped (StringRopeOne "var") (JsonEncode_object [ (struct( StringRopeOne "value", JsonEncode_string name )) ])

    | ElmSyntaxPattern_NamedPattern(qualifiedNameRef, patterns) ->
        ElmJsonUtil_encodeTyped
            (StringRopeOne "named")
            (JsonEncode_object
                [ (struct(
                    StringRopeOne "qualified"
                  , JsonEncode_object
                        [ (struct( StringRopeOne "moduleName", ElmSyntaxModuleName_encode qualifiedNameRef.ModuleName ));
                          (struct( StringRopeOne "name", JsonEncode_string qualifiedNameRef.Name ))
                        ]
                  ));
                  (struct( StringRopeOne "patterns", JsonEncode_list (ElmSyntaxNode_encode ElmSyntaxPattern_encode) patterns ))
                ]
            )

    | ElmSyntaxPattern_AsPattern(destructured, name) ->
        ElmJsonUtil_encodeTyped
            (StringRopeOne "as")
            (JsonEncode_object
                [ (struct( StringRopeOne "name", ElmSyntaxNode_encode JsonEncode_string name ));
                  (struct( StringRopeOne "pattern", ElmSyntaxNode_encode ElmSyntaxPattern_encode destructured ))
                ]
            )

    | ElmSyntaxPattern_ParenthesizedPattern(p1) ->
        ElmJsonUtil_encodeTyped (StringRopeOne "parentisized") (JsonEncode_object [ (struct( StringRopeOne "value", ElmSyntaxNode_encode ElmSyntaxPattern_encode p1 )) ])

let rec ElmSyntaxTypeAnnotation_encode (typeAnnotation: ElmSyntaxTypeAnnotation_TypeAnnotation) : System.Text.Json.Nodes.JsonNode =
    match typeAnnotation with
    | ElmSyntaxTypeAnnotation_GenericType(name) ->
        ElmJsonUtil_encodeTyped (StringRopeOne "generic") (JsonEncode_object [ (struct( StringRopeOne "value", JsonEncode_string name )) ])

    | ElmSyntaxTypeAnnotation_Typed(moduleNameAndName, args) ->
        let inner
            ((struct( mod_, n )):
                (struct(
                  ElmSyntaxModuleName_ModuleName
                * StringRope
                ))
            )
            : System.Text.Json.Nodes.JsonNode =
            JsonEncode_object
                [ (struct( StringRopeOne "moduleName", ElmSyntaxModuleName_encode mod_ ));
                  (struct( StringRopeOne "name", JsonEncode_string n ))
                ]
        
        ElmJsonUtil_encodeTyped
            (StringRopeOne "typed")
            (JsonEncode_object
                [ (struct( StringRopeOne "moduleNameAndName", ElmSyntaxNode_encode inner moduleNameAndName ));
                  (struct( StringRopeOne "args", JsonEncode_list (ElmSyntaxNode_encode ElmSyntaxTypeAnnotation_encode) args ))
                ]
            )

    | ElmSyntaxTypeAnnotation_Unit ->
        ElmJsonUtil_encodeTyped (StringRopeOne "unit") (JsonEncode_object [])

    | ElmSyntaxTypeAnnotation_Tupled(t) ->
        ElmJsonUtil_encodeTyped (StringRopeOne "tupled") (JsonEncode_object [ (struct( StringRopeOne "values", JsonEncode_list (ElmSyntaxNode_encode ElmSyntaxTypeAnnotation_encode) t )) ])

    | ElmSyntaxTypeAnnotation_FunctionTypeAnnotation(left, right) ->
        ElmJsonUtil_encodeTyped
            (StringRopeOne "function")
            (JsonEncode_object
                [ (struct( StringRopeOne "left", ElmSyntaxNode_encode ElmSyntaxTypeAnnotation_encode left ));
                  (struct( StringRopeOne "right", ElmSyntaxNode_encode ElmSyntaxTypeAnnotation_encode right ))
                ]
            )

    | ElmSyntaxTypeAnnotation_Record(recordDefinition) ->
        ElmJsonUtil_encodeTyped (StringRopeOne "record") (JsonEncode_object [ (struct( StringRopeOne "value", ElmSyntaxTypeAnnotation_encodeRecordDefinition recordDefinition )) ])

    | ElmSyntaxTypeAnnotation_GenericRecord(name, recordDefinition) ->
        ElmJsonUtil_encodeTyped
            (StringRopeOne "genericRecord")
            (JsonEncode_object
                [ (struct( StringRopeOne "name", ElmSyntaxNode_encode JsonEncode_string name ));
                  (struct( StringRopeOne "values", ElmSyntaxNode_encode ElmSyntaxTypeAnnotation_encodeRecordDefinition recordDefinition ))
                ]
            )

and ElmSyntaxTypeAnnotation_encodeRecordDefinition: ElmSyntaxTypeAnnotation_RecordDefinition -> System.Text.Json.Nodes.JsonNode =
    JsonEncode_list (ElmSyntaxNode_encode ElmSyntaxTypeAnnotation_encodeRecordField)

and ElmSyntaxTypeAnnotation_encodeRecordField
    ((struct( name, ref )):
        (struct(
          ElmSyntaxNode_Node<StringRope>
        * ElmSyntaxNode_Node<ElmSyntaxTypeAnnotation_TypeAnnotation>
        ))
    )
    : System.Text.Json.Nodes.JsonNode =
    JsonEncode_object
        [ (struct( StringRopeOne "name", ElmSyntaxNode_encode JsonEncode_string name ));
          (struct( StringRopeOne "typeAnnotation", ElmSyntaxNode_encode ElmSyntaxTypeAnnotation_encode ref ))
        ]

let ElmSyntaxSignature_encode ({ Name = name; TypeAnnotation = typeAnnotation }: Generated_Name_TypeAnnotation<ElmSyntaxNode_Node<StringRope>, ElmSyntaxNode_Node<ElmSyntaxTypeAnnotation_TypeAnnotation>>) : System.Text.Json.Nodes.JsonNode =
    JsonEncode_object
        [ (struct( StringRopeOne "name", ElmSyntaxNode_encode JsonEncode_string name ));
          (struct( StringRopeOne "typeAnnotation", ElmSyntaxNode_encode ElmSyntaxTypeAnnotation_encode typeAnnotation ))
        ]

let rec ElmSyntaxExpression_encodeFunction ({ Declaration = declaration; Documentation = documentation; Signature = signature }: Generated_Declaration_Documentation_Signature<ElmSyntaxNode_Node<ElmSyntaxExpression_FunctionImplementation>, ValueOption<ElmSyntaxNode_Node<ElmSyntaxDocumentation_Documentation>>, ValueOption<ElmSyntaxNode_Node<ElmSyntaxSignature_Signature>>>) : System.Text.Json.Nodes.JsonNode =
    JsonEncode_object
        [ (struct( StringRopeOne "documentation", ValueOption.defaultValue JsonEncode_null (ValueOption.map (ElmSyntaxNode_encode ElmSyntaxDocumentation_encode) documentation) ));
          (struct( StringRopeOne "signature", ValueOption.defaultValue JsonEncode_null (ValueOption.map (ElmSyntaxNode_encode ElmSyntaxSignature_encode) signature) ));
          (struct( StringRopeOne "declaration", ElmSyntaxNode_encode ElmSyntaxExpression_encodeFunctionDeclaration declaration ))
        ]

and ElmSyntaxExpression_encodeFunctionDeclaration ({ Arguments = arguments; Expression = expression; Name = name }: Generated_Arguments_Expression_Name<List<ElmSyntaxNode_Node<ElmSyntaxPattern_Pattern>>, ElmSyntaxNode_Node<ElmSyntaxExpression_Expression>, ElmSyntaxNode_Node<StringRope>>) : System.Text.Json.Nodes.JsonNode =
    JsonEncode_object
        [ (struct( StringRopeOne "name", ElmSyntaxNode_encode JsonEncode_string name ));
          (struct( StringRopeOne "arguments", JsonEncode_list (ElmSyntaxNode_encode ElmSyntaxPattern_encode) arguments ));
          (struct( StringRopeOne "expression", ElmSyntaxNode_encode ElmSyntaxExpression_encode expression ))
        ]

and ElmSyntaxExpression_encode (expr: ElmSyntaxExpression_Expression) : System.Text.Json.Nodes.JsonNode =
    match expr with
    | ElmSyntaxExpression_UnitExpr ->
        ElmJsonUtil_encodeTyped (StringRopeOne "unit") JsonEncode_null

    | ElmSyntaxExpression_Application(l) ->
        ElmJsonUtil_encodeTyped (StringRopeOne "application") (JsonEncode_list (ElmSyntaxNode_encode ElmSyntaxExpression_encode) l)

    | ElmSyntaxExpression_OperatorApplication(op, dir, left, right) ->
        ElmJsonUtil_encodeTyped (StringRopeOne "operatorapplication") (ElmSyntaxExpression_encodeOperatorApplication op dir left right)

    | ElmSyntaxExpression_FunctionOrValue(moduleName, name) ->
        ElmJsonUtil_encodeTyped
            (StringRopeOne "functionOrValue")
            (JsonEncode_object
                [ (struct( StringRopeOne "moduleName", ElmSyntaxModuleName_encode moduleName ));
                  (struct( StringRopeOne "name", JsonEncode_string name ))
                ]
            )

    | ElmSyntaxExpression_IfBlock(c, t, e) ->
        ElmJsonUtil_encodeTyped
            (StringRopeOne "ifBlock")
            (JsonEncode_object
                [ (struct( StringRopeOne "clause", ElmSyntaxNode_encode ElmSyntaxExpression_encode c ));
                  (struct( StringRopeOne "then", ElmSyntaxNode_encode ElmSyntaxExpression_encode t ));
                  (struct( StringRopeOne "else", ElmSyntaxNode_encode ElmSyntaxExpression_encode e ))
                ]
            )

    | ElmSyntaxExpression_PrefixOperator(x) ->
        ElmJsonUtil_encodeTyped (StringRopeOne "prefixoperator") (JsonEncode_string x)

    | ElmSyntaxExpression_Operator(x) ->
        ElmJsonUtil_encodeTyped (StringRopeOne "operator") (JsonEncode_string x)

    | ElmSyntaxExpression_Hex(h) ->
        ElmJsonUtil_encodeTyped (StringRopeOne "hex") (JsonEncode_int h)

    | ElmSyntaxExpression_Integer(x) ->
        ElmJsonUtil_encodeTyped (StringRopeOne "integer") (JsonEncode_int x)

    | ElmSyntaxExpression_Floatable(x) ->
        ElmJsonUtil_encodeTyped (StringRopeOne "float") (JsonEncode_float x)

    | ElmSyntaxExpression_Negation(x) ->
        ElmJsonUtil_encodeTyped (StringRopeOne "negation") (ElmSyntaxNode_encode ElmSyntaxExpression_encode x)

    | ElmSyntaxExpression_Literal(x) ->
        ElmJsonUtil_encodeTyped (StringRopeOne "literal") (JsonEncode_string x)

    | ElmSyntaxExpression_CharLiteral(c) ->
        ElmJsonUtil_encodeTyped (StringRopeOne "charLiteral") (JsonEncode_string (String_fromChar c))

    | ElmSyntaxExpression_TupledExpression(xs) ->
        ElmJsonUtil_encodeTyped (StringRopeOne "tupled") (JsonEncode_list (ElmSyntaxNode_encode ElmSyntaxExpression_encode) xs)

    | ElmSyntaxExpression_ListExpr(xs) ->
        ElmJsonUtil_encodeTyped (StringRopeOne "list") (JsonEncode_list (ElmSyntaxNode_encode ElmSyntaxExpression_encode) xs)

    | ElmSyntaxExpression_ParenthesizedExpression(x) ->
        ElmJsonUtil_encodeTyped (StringRopeOne "parenthesized") (ElmSyntaxNode_encode ElmSyntaxExpression_encode x)

    | ElmSyntaxExpression_LetExpression(x) ->
        ElmJsonUtil_encodeTyped (StringRopeOne "let") (ElmSyntaxExpression_encodeLetBlock x)

    | ElmSyntaxExpression_CaseExpression(x) ->
