let ElmInterface_operators: ElmInterface_Interface -> List<ElmSyntaxInfix_Infix> =
    List_filterMap
        (fun (interface_: ElmInterface_Exposed) ->
            match interface_ with
            | ElmInterface_Operator(operator) ->
                ValueSome operator

            | _ ->
                ValueNone
        )

let ElmInterface_ifCustomType
    (f:
        (struct(
          StringRope
        * List<StringRope>
        )) ->
            ElmInterface_Exposed
    )
    (i: ElmInterface_Exposed)
    : ElmInterface_Exposed =
    match i with
    | ElmInterface_CustomType(t) ->
        f t

    | _ ->
        i

let ElmInterface_getValidOperatorInterface (t1: ElmInterface_Exposed) (t2: ElmInterface_Exposed) : ValueOption<ElmInterface_Exposed> =
    match (struct( t1, t2 )) with
    | (struct( ElmInterface_Operator(x), ElmInterface_Operator(y) )) ->
        if Basics_and (Basics_eq (ElmSyntaxNode_value x.Precedence) 5L) (Basics_eq (ElmSyntaxNode_value x.Direction) ElmSyntaxInfix_Left) then
            ValueSome (ElmInterface_Operator y)

        else
            ValueSome (ElmInterface_Operator x)

    | _ ->
        ValueNone

let ElmInterface_resolveGroup
    (g:
        List<
            (struct(
              StringRope
            * ElmInterface_Exposed
            ))
            >
    )
    : ValueOption<
        (struct(
          StringRope
        * ElmInterface_Exposed
        ))
        > =
    match g with
    | [] ->
        ValueNone

    | [ x ] ->
        ValueSome x

    | [ (struct( n1, t1 )); (struct( _, t2 )) ] ->
        ValueOption.map
            (fun (a: ElmInterface_Exposed) ->
                (struct( n1, a ))
            )
            (ElmInterface_getValidOperatorInterface t1 t2)

    | _ ->
        ValueNone

let ElmInterface_fileToDefinitions
    (file: Generated_Comments_Declarations_Imports_ModuleDefinition<List<ElmSyntaxNode_Node<ElmSyntaxComments_Comment>>, List<ElmSyntaxNode_Node<ElmSyntaxDeclaration_Declaration>>, List<ElmSyntaxNode_Node<ElmSyntaxImport_Import>>, ElmSyntaxNode_Node<ElmSyntaxModule_Module>>)
    : List<
        (struct(
          StringRope
        * ElmInterface_Exposed
        ))
        > =
    let allDeclarations:
            List<
                (struct(
                  StringRope
                * ElmInterface_Exposed
                ))
                > =
        List_filterMap
            (fun (ElmSyntaxNode_Node(_, decl): ElmSyntaxNode_Node<ElmSyntaxDeclaration_Declaration>) ->
                match decl with
                | ElmSyntaxDeclaration_CustomTypeDeclaration(t) ->
                    ValueSome
                        (struct(
                          ElmSyntaxNode_value t.Name
                        , ElmInterface_CustomType
                            (struct(
                              ElmSyntaxNode_value t.Name
                            , List.map
                                ((>>)
                                    ElmSyntaxNode_value
                                    ((>>)
                                        (fun (generated_record: Generated_Arguments_Name<List<ElmSyntaxNode_Node<ElmSyntaxTypeAnnotation_TypeAnnotation>>, ElmSyntaxNode_Node<StringRope>>) ->
                                            generated_record.Name
                                        )
                                        ElmSyntaxNode_value
                                    )
                                )
                                t.Constructors
                            ))
                        ))

                | ElmSyntaxDeclaration_AliasDeclaration(a) ->
                    ValueSome (struct( ElmSyntaxNode_value a.Name, ElmInterface_Alias (ElmSyntaxNode_value a.Name) ))

                | ElmSyntaxDeclaration_PortDeclaration(p) ->
                    ValueSome (struct( ElmSyntaxNode_value p.Name, ElmInterface_Function (ElmSyntaxNode_value p.Name) ))

                | ElmSyntaxDeclaration_FunctionDeclaration(f) ->
                    let declaration: ElmSyntaxExpression_FunctionImplementation =
                        ElmSyntaxNode_value f.Declaration
                    
                    let name: StringRope =
                        ElmSyntaxNode_value declaration.Name
                    
                    ValueSome (struct( name, ElmInterface_Function name ))

                | ElmSyntaxDeclaration_InfixDeclaration(i) ->
                    ValueSome (struct( ElmSyntaxNode_value i.Operator, ElmInterface_Operator i ))

                | ElmSyntaxDeclaration_Destructuring(_, _) ->
                    ValueNone
            )
            file.Declarations
    
    List_filterMap
        ElmInterface_resolveGroup
        (List.map
            (fun ((struct( name, _ )):
                    (struct(
                      StringRope
                    * ElmInterface_Exposed
                    ))
                 ) ->
                List.filter
                    (fun ((struct( otherDeclarationName, _ )):
                            (struct(
                              StringRope
                            * ElmInterface_Exposed
                            ))
                         ) ->
                        Basics_eq otherDeclarationName name
                    )
                    allDeclarations
            )
            allDeclarations
        )

let ElmInterface_exposesFunction (k: StringRope) (interface_: List<ElmInterface_Exposed>) : bool =
    List.exists
        (fun (x: ElmInterface_Exposed) ->
            match x with
            | ElmInterface_Function(l) ->
                Basics_eq k l

            | ElmInterface_CustomType((struct( _, constructors ))) ->
                List_member k constructors

            | ElmInterface_Operator(inf) ->
                Basics_eq (ElmSyntaxNode_value inf.Operator) k

            | ElmInterface_Alias(_) ->
                false
        )
        interface_

let ElmInterface_exposesAlias (k: StringRope) (interface_: List<ElmInterface_Exposed>) : bool =
    List.exists
        (fun (x: ElmInterface_Exposed) ->
            match x with
            | ElmInterface_Alias(l) ->
                Basics_eq k l

            | _ ->
                false
        )
        interface_

let ElmInterface_buildInterfaceFromExplicit (x: List<ElmSyntaxNode_Node<ElmSyntaxExposing_TopLevelExpose>>) (exposedDict: Map<StringRope, ElmInterface_Exposed>) : List<ElmInterface_Exposed> =
    List_filterMap
        (fun (ElmSyntaxNode_Node(_, expose): ElmSyntaxNode_Node<ElmSyntaxExposing_TopLevelExpose>) ->
            match expose with
            | ElmSyntaxExposing_InfixExpose(k) ->
                Dict_get k exposedDict

            | ElmSyntaxExposing_TypeOrAliasExpose(s) ->
                ValueOption.map
                    (ElmInterface_ifCustomType
                        (fun ((struct( name, _ )):
                                (struct(
                                  StringRope
                                * List<StringRope>
                                ))
                             ) ->
                            ElmInterface_CustomType (struct( name, [] ))
                        )
                    )
                    (Dict_get s exposedDict)

            | ElmSyntaxExposing_FunctionExpose(s) ->
                ValueSome (ElmInterface_Function s)

            | ElmSyntaxExposing_TypeExpose(exposedType) ->
                match exposedType.Open with
                | ValueNone ->
                    ValueSome (ElmInterface_CustomType (struct( exposedType.Name, [] )))

                | ValueSome(_) ->
                    Dict_get exposedType.Name exposedDict
        )
        x

let ElmInterface_build (ElmInternalRawFile_Raw(file): ElmInternalRawFile_RawFile) : ElmInterface_Interface =
    let fileDefinitionList:
            List<
                (struct(
                  StringRope
                * ElmInterface_Exposed
                ))
                > =
        ElmInterface_fileToDefinitions file
    
    match ElmSyntaxModule_exposingList (ElmSyntaxNode_value file.ModuleDefinition) with
    | ElmSyntaxExposing_Explicit(x) ->
        ElmInterface_buildInterfaceFromExplicit x (Dict_fromList fileDefinitionList)

    | ElmSyntaxExposing_All(_) ->
        List.map Tuple_second fileDefinitionList

let ElmProcessing_addFile (file: ElmRawFile_RawFile) (ElmProcessing_ProcessContext(context): ElmProcessing_ProcessContext) : ElmProcessing_ProcessContext =
    ElmProcessing_ProcessContext (Map.add (ElmRawFile_moduleName file) (ElmInterface_build file) context)

let CharExtra_isUtf16Surrogate (c: int) : bool =
    System.Double.IsNaN (float (int64 c))

let ParserFast_charStringIsUtf16HighSurrogate (charString: StringRope) : bool =
    String_any CharExtra_isUtf16Surrogate charString

let ParserFast_charOrEnd (offset: int64) (string_: StringRope) : int64 =
    let actualChar: StringRope =
        String_slice offset ((+) offset 1L) string_
    
    match actualChar with
    | StringRopeOne("\n") ->
        -2L

    | StringRopeOne("") ->
        -1L

    | _ ->
        if ParserFast_charStringIsUtf16HighSurrogate actualChar then
            (+) offset 2L

        else
            (+) offset 1L

