let ElmParserLayout_whitespaceAndCommentsOrEmpty: ParserFast_Parser<ParserWithComments_Comments> =
    ParserFast_skipWhileWhitespaceFollowedBy
        (ParserFast_offsetSourceAndThenOrSucceed
            (fun (offset: int64) (source: StringRope) ->
                match String_slice offset ((+) offset 2L) source with
                | StringRopeOne("--") ->
                    ValueSome ElmParserLayout_fromSingleLineCommentNode

