let ParserLenient_charStringIsUtf16HighSurrogate (charString: StringRope) : bool =
    String_any CharExtra_isUtf16Surrogate charString

let ParserLenient_charOrEnd (offset: int64) (string_: StringRope) : int64 =
    match String_slice offset ((+) offset 1L) string_ with
    | StringRopeOne("\n") ->
        -2L

    | StringRopeOne("") ->
        -1L

    | charNotLinebreakNotEndOfSource ->
        if ParserLenient_charStringIsUtf16HighSurrogate charNotLinebreakNotEndOfSource then
            (+) offset 2L

        else
            (+) offset 1L

let ParserLenient_anyChar: ParserLenient_Parser<int> =
    ParserLenient_Parser
        (fun (s: Generated_Col_Indent_Offset_Row_Src<int64, List<int64>, int64, int64, StringRope>) ->
            let newOffset: int64 =
                ParserLenient_charOrEnd s.Offset s.Src
            
            if Basics_eq newOffset -1L then
                ParserLenient_pStepBadBacktracking

            else
                if Basics_eq newOffset -2L then
                    ParserLenient_Good
                        (struct(
                          10
                        , { Col = 1L
                          ; Indent = s.Indent
                          ; Offset = (+) s.Offset 1L
                          ; Row = (+) s.Row 1L
                          ; Src = s.Src
                          }
                        ))

                else
                    match String_toList (String_slice s.Offset newOffset s.Src) with
                    | [] ->
                        ParserLenient_pStepBadBacktracking

                    | c :: _ ->
                        ParserLenient_Good
                            (struct(
                              c
                            , { Col = (+) s.Col 1L
                              ; Indent = s.Indent
                              ; Offset = newOffset
                              ; Row = s.Row
                              ; Src = s.Src
                              }
                            ))
        )

let ParserLenient_isSubCharWithoutLinebreak (predicate: int -> bool) (offset: int64) (string_: StringRope) : int64 =
    let actualChar: StringRope =
        String_slice offset ((+) offset 1L) string_
    
    if String_any predicate actualChar then
        (+) offset 1L

    else
        if Basics_and (ParserLenient_charStringIsUtf16HighSurrogate actualChar) (String_any predicate (String_slice offset ((+) offset 2L) string_)) then
            (+) offset 2L

        else
            -1L

let rec ParserLenient_skipWhileHelp (isGood: int -> bool) (offset: int64) (row: int64) (col: int64) (src: StringRope) (indent: List<int64>) : ParserLenient_State =
    let actualChar: StringRope =
        String_slice offset ((+) offset 1L) src
    
    if String_any isGood actualChar then
        match actualChar with
        | StringRopeOne("\n") ->
            ParserLenient_skipWhileHelp isGood ((+) offset 1L) ((+) row 1L) 1L src indent

        | _ ->
            ParserLenient_skipWhileHelp isGood ((+) offset 1L) row ((+) col 1L) src indent

    else
        if Basics_and (ParserLenient_charStringIsUtf16HighSurrogate actualChar) (String_any isGood (String_slice offset ((+) offset 2L) src)) then
            ParserLenient_skipWhileHelp isGood ((+) offset 2L) row ((+) col 1L) src indent

        else
            { Col = col
            ; Indent = indent
            ; Offset = offset
            ; Row = row
            ; Src = src
            }

