        StringRopeOne "\\t"

    | 10 ->
        StringRopeOne "\n"

    | 13 ->
        StringRopeOne "\r"

    | otherCharacter ->
        if ElmSyntaxPrintDefunctionalized_characterIsNotPrint otherCharacter then
            String_append (StringRopeOne "\\u{") (String_append (ElmSyntaxPrintDefunctionalized_characterHex otherCharacter) (StringRopeOne "}"))

        else
            String_fromChar otherCharacter

let ElmSyntaxPrintDefunctionalized_stringLiteral (ElmSyntaxNode_Node(range, stringContent): ElmSyntaxNode_Node<StringRope>) : Print_Print =
    let singleDoubleQuotedStringContentEscaped: StringRope =
        String_foldl
            (fun (contentChar: int) (soFar: StringRope) ->
                String_append soFar (ElmSyntaxPrintDefunctionalized_singleDoubleQuotedStringCharToEscaped contentChar)
            )
            (StringRopeOne "")
            stringContent
    
    let wasProbablyTripleDoubleQuoteOriginally: bool =
        Basics_or (Basics_neq range.Start.Row range.End.Row) (Basics_neq ((-) ((-) range.End.Column range.Start.Column) (ElmSyntaxPrintDefunctionalized_stringUnicodeLength singleDoubleQuotedStringContentEscaped)) 2L)
    
    if wasProbablyTripleDoubleQuoteOriginally then
        Print_followedBy
            ElmSyntaxPrintDefunctionalized_printExactlyDoubleQuoteDoubleQuoteDoubleQuote
            (Print_followedBy
                (Print_listMapAndIntersperseAndFlatten
                    Print_exactly
                    Print_linebreak
                    (String_lines
                        (ElmSyntaxPrintDefunctionalized_tripleDoubleQuotedStringEscapeDoubleQuotes
                            (String_foldl
                                (fun (contentChar: int) (soFar: StringRope) ->
                                    String_append soFar (ElmSyntaxPrintDefunctionalized_tripleDoubleQuotedStringCharToEscaped contentChar)
                                )
                                (StringRopeOne "")
                                stringContent
                            )
                        )
                    )
                )
                ElmSyntaxPrintDefunctionalized_printExactlyDoubleQuoteDoubleQuoteDoubleQuote
            )

    else
        Print_exactly (String_append (StringRopeOne "\"") (String_append singleDoubleQuotedStringContentEscaped (StringRopeOne "\"")))

let rec ElmSyntaxPrintDefunctionalized_patternNotParenthesized (syntaxComments: List<ElmSyntaxNode_Node<StringRope>>) (ElmSyntaxNode_Node(fullRange, syntaxPattern): ElmSyntaxNode_Node<ElmSyntaxPattern_Pattern>) : Print_Print =
    match syntaxPattern with
    | ElmSyntaxPattern_AllPattern ->
        ElmSyntaxPrintDefunctionalized_printExactlyUnderscore

    | ElmSyntaxPattern_UnitPattern ->
        ElmSyntaxPrintDefunctionalized_printExactlyParensOpeningParensClosed

    | ElmSyntaxPattern_VarPattern(name) ->
        Print_exactly name

    | ElmSyntaxPattern_CharPattern(char_) ->
        Print_exactly (ElmSyntaxPrintDefunctionalized_charLiteral char_)

    | ElmSyntaxPattern_StringPattern(string_) ->
        ElmSyntaxPrintDefunctionalized_stringLiteral (ElmSyntaxNode_Node (struct( fullRange, string_ )))

    | ElmSyntaxPattern_IntPattern(int_) ->
        Print_exactly (ElmSyntaxPrintDefunctionalized_intLiteral int_)

    | ElmSyntaxPattern_HexPattern(int_) ->
        Print_exactly (ElmSyntaxPrintDefunctionalized_hexLiteral int_)

    | ElmSyntaxPattern_FloatPattern(float_) ->
        Print_exactly (String_fromFloat float_)

    | ElmSyntaxPattern_ParenthesizedPattern(inParens) ->
        let commentsBeforeInParens: List<StringRope> =
            ElmSyntaxPrintDefunctionalized_commentsInRange
                { End = (ElmSyntaxNode_range inParens).Start
                ; Start = fullRange.Start
                }
                syntaxComments
        
        let commentsAfterInParens: List<StringRope> =
            ElmSyntaxPrintDefunctionalized_commentsInRange
                { End = fullRange.End
                ; Start = (ElmSyntaxNode_range inParens).End
                }
                syntaxComments
        
        match (struct( commentsBeforeInParens, commentsAfterInParens )) with
        | (struct( [], [] )) ->
            ElmSyntaxPrintDefunctionalized_patternNotParenthesized syntaxComments inParens

        | _ ->
            ElmSyntaxPrintDefunctionalized_parenthesized
                ElmSyntaxPrintDefunctionalized_patternNotParenthesized
                { FullRange = fullRange
                ; NotParenthesized = ElmSyntaxPrintDefunctionalized_patternToNotParenthesized inParens
                }
                syntaxComments

    | ElmSyntaxPattern_TuplePattern(parts) ->
        match parts with
        | [ part0; part1 ] ->
            ElmSyntaxPrintDefunctionalized_tuple
                { LineSpreadMinimum = Print_SingleLine
                ; PrintPartNotParenthesized = ElmSyntaxPrintDefunctionalized_patternNotParenthesized
                }
                syntaxComments
                { FullRange = fullRange
                ; Part0 = part0
                ; Part1 = part1
                }

        | [ part0; part1; part2 ] ->
            ElmSyntaxPrintDefunctionalized_triple
                { LineSpreadMinimum = Print_SingleLine
                ; PrintPartNotParenthesized = ElmSyntaxPrintDefunctionalized_patternNotParenthesized
                }
                syntaxComments
                { FullRange = fullRange
                ; Part0 = part0
                ; Part1 = part1
                ; Part2 = part2
                }

        | [] ->
            ElmSyntaxPrintDefunctionalized_printExactlyParensOpeningParensClosed

        | [ inParens ] ->
            let commentsBeforeInParens: List<StringRope> =
                ElmSyntaxPrintDefunctionalized_commentsInRange
                    { End = (ElmSyntaxNode_range inParens).Start
                    ; Start = fullRange.Start
                    }
                    syntaxComments
            
            let commentsAfterInParens: List<StringRope> =
                ElmSyntaxPrintDefunctionalized_commentsInRange
                    { End = fullRange.End
                    ; Start = (ElmSyntaxNode_range inParens).End
                    }
                    syntaxComments
            
            match (struct( commentsBeforeInParens, commentsAfterInParens )) with
            | (struct( [], [] )) ->
                ElmSyntaxPrintDefunctionalized_patternNotParenthesized syntaxComments inParens

            | _ ->
                ElmSyntaxPrintDefunctionalized_parenthesized
                    ElmSyntaxPrintDefunctionalized_patternNotParenthesized
                    { FullRange = fullRange
                    ; NotParenthesized = ElmSyntaxPrintDefunctionalized_patternToNotParenthesized inParens
                    }
                    syntaxComments

        | part0 :: (part1 :: (part2 :: (part3 :: part4Up))) ->
            ElmSyntaxPrintDefunctionalized_invalidNTuple
                ElmSyntaxPrintDefunctionalized_patternNotParenthesized
                syntaxComments
                { FullRange = fullRange
                ; Part0 = part0
                ; Part1 = part1
                ; Part2 = part2
                ; Part3 = part3
                ; Part4Up = part4Up
                }

    | ElmSyntaxPattern_RecordPattern(fields) ->
        ElmSyntaxPrintDefunctionalized_patternRecord
            syntaxComments
            { Fields = fields
            ; FullRange = fullRange
            }

    | ElmSyntaxPattern_UnConsPattern(headPattern, tailPattern) ->
        ElmSyntaxPrintDefunctionalized_patternCons
            syntaxComments
            { Head = headPattern
            ; Tail = tailPattern
            }

    | ElmSyntaxPattern_ListPattern(elementPatterns) ->
        ElmSyntaxPrintDefunctionalized_patternList
            syntaxComments
            { Elements = elementPatterns
            ; FullRange = fullRange
            }

    | ElmSyntaxPattern_NamedPattern(syntaxQualifiedNameRef, argumentPatterns) ->
        ElmSyntaxPrintDefunctionalized_construct
            { LineSpreadMinimum = Print_SingleLine
            ; PrintArgumentParenthesizedIfSpaceSeparated = ElmSyntaxPrintDefunctionalized_patternParenthesizedIfSpaceSeparated
            }
            syntaxComments
            { Arguments = argumentPatterns
            ; FullRange = fullRange
            ; Start =
                ElmSyntaxPrintDefunctionalized_qualifiedReference
                    { Qualification = syntaxQualifiedNameRef.ModuleName
                    ; Unqualified = syntaxQualifiedNameRef.Name
                    }
            }

    | ElmSyntaxPattern_AsPattern(aliasedPattern, aliasNameNode) ->
        ElmSyntaxPrintDefunctionalized_patternAs
            syntaxComments
            { AliasNameNode = aliasNameNode
            ; AliasedPattern = aliasedPattern
            }

and ElmSyntaxPrintDefunctionalized_patternAs (syntaxComments: List<ElmSyntaxNode_Node<StringRope>>) (syntaxAs: Generated_AliasNameNode_AliasedPattern<ElmSyntaxNode_Node<StringRope>, ElmSyntaxNode_Node<ElmSyntaxPattern_Pattern>>) : Print_Print =
    let namePrint: Print_Print =
        Print_exactly (ElmSyntaxNode_value syntaxAs.AliasNameNode)
    
    let commentsBeforeAliasName: List<StringRope> =
        ElmSyntaxPrintDefunctionalized_commentsInRange
            { End = (ElmSyntaxNode_range syntaxAs.AliasNameNode).Start
            ; Start = (ElmSyntaxNode_range syntaxAs.AliasedPattern).End
            }
            syntaxComments
    
    let commentsCollapsibleBeforeAliasName: Generated_LineSpread_Print<Print_LineSpread, Print_Print> =
        ElmSyntaxPrintDefunctionalized_collapsibleComments commentsBeforeAliasName
    
    let aliasedPatternPrint: Print_Print =
        ElmSyntaxPrintDefunctionalized_patternParenthesizedIfSpaceSeparated syntaxComments syntaxAs.AliasedPattern
    
    let lineSpread: Print_LineSpread =
        Print_lineSpreadMergeWith
            (fun (_: unit) ->
                Print_lineSpread aliasedPatternPrint
            )
            commentsCollapsibleBeforeAliasName.LineSpread
    
    Print_followedBy
        (Print_withIndentAtNextMultipleOf4
            (Print_followedBy
                (match commentsBeforeAliasName with
                 | [] ->
                    namePrint

                 | _ :: _ ->
                    Print_followedBy namePrint (Print_followedBy (Print_spaceOrLinebreakIndented commentsCollapsibleBeforeAliasName.LineSpread) commentsCollapsibleBeforeAliasName.Print)
                )
                (Print_spaceOrLinebreakIndented lineSpread)
            )
        )
        (Print_followedBy ElmSyntaxPrintDefunctionalized_printExactlyAs (Print_followedBy (Print_spaceOrLinebreakIndented lineSpread) aliasedPatternPrint))

and ElmSyntaxPrintDefunctionalized_patternParenthesizedIfSpaceSeparated (syntaxComments: List<ElmSyntaxNode_Node<StringRope>>) (syntaxPattern: ElmSyntaxNode_Node<ElmSyntaxPattern_Pattern>) : Print_Print =
    if ElmSyntaxPrintDefunctionalized_patternIsSpaceSeparated (ElmSyntaxNode_value syntaxPattern) then
        ElmSyntaxPrintDefunctionalized_patternParenthesized syntaxComments syntaxPattern

    else
        ElmSyntaxPrintDefunctionalized_patternNotParenthesized syntaxComments syntaxPattern

and ElmSyntaxPrintDefunctionalized_patternParenthesized (syntaxComments: List<ElmSyntaxNode_Node<StringRope>>) (patternNode: ElmSyntaxNode_Node<ElmSyntaxPattern_Pattern>) : Print_Print =
    ElmSyntaxPrintDefunctionalized_parenthesized
        ElmSyntaxPrintDefunctionalized_patternNotParenthesized
        { FullRange = ElmSyntaxNode_range patternNode
        ; NotParenthesized = ElmSyntaxPrintDefunctionalized_patternToNotParenthesized patternNode
        }
        syntaxComments

and ElmSyntaxPrintDefunctionalized_patternCons (syntaxComments: List<ElmSyntaxNode_Node<StringRope>>) (syntaxCons: Generated_Head_Tail<ElmSyntaxNode_Node<ElmSyntaxPattern_Pattern>, ElmSyntaxNode_Node<ElmSyntaxPattern_Pattern>>) : Print_Print =
    let tailPatterns: List<ElmSyntaxNode_Node<ElmSyntaxPattern_Pattern>> =
        ElmSyntaxPrintDefunctionalized_patternConsExpand syntaxCons.Tail
    
    let tailPatternPrintsAndCommentsBeforeReverse: List<Print_Print> =
        (List_foldl
            (fun (tailPatternNode: ElmSyntaxNode_Node<ElmSyntaxPattern_Pattern>) (soFar: Generated_EndLocation_Reverse<ElmSyntaxRange_Location, List<Print_Print>>) ->
                let print: Print_Print =
                    ElmSyntaxPrintDefunctionalized_patternParenthesizedIfSpaceSeparated syntaxComments tailPatternNode
                
                let (ElmSyntaxNode_Node(tailPatternRange, _): ElmSyntaxNode_Node<ElmSyntaxPattern_Pattern>) =
                    tailPatternNode
                
                { EndLocation = tailPatternRange.End
                ; Reverse =
                    List_cons
                        (match
                            ElmSyntaxPrintDefunctionalized_commentsInRange
                                { End = tailPatternRange.Start
                                ; Start = soFar.EndLocation
                                }
                                syntaxComments
                         with
                         | [] ->
                            print

                         | comment0 :: comment1Up ->
                            let commentsBefore: Generated_LineSpread_Print<Print_LineSpread, Print_Print> =
                                ElmSyntaxPrintDefunctionalized_collapsibleComments (List_cons comment0 comment1Up)
                            
                            Print_followedBy
                                print
                                (Print_followedBy
                                    (Print_spaceOrLinebreakIndented
                                        (Print_lineSpreadMergeWith
                                            (fun (_: unit) ->
                                                Print_lineSpread print
                                            )
                                            commentsBefore.LineSpread
                                        )
                                    )
                                    commentsBefore.Print
                                )
                        )
                        soFar.Reverse
                }
            )
            { EndLocation = (ElmSyntaxNode_range syntaxCons.Head).End
            ; Reverse = []
            }
            tailPatterns
        ).Reverse
    
    let headPrint: Print_Print =
        ElmSyntaxPrintDefunctionalized_patternParenthesizedIfSpaceSeparated syntaxComments syntaxCons.Head
    
    let lineSpread: Print_LineSpread =
        Print_lineSpreadMergeWith
            (fun (_: unit) ->
                Print_lineSpreadListMapAndCombine Print_lineSpread tailPatternPrintsAndCommentsBeforeReverse
            )
            (Print_lineSpread headPrint)
    
    Print_followedBy
        (Print_withIndentAtNextMultipleOf4
            (Print_followedBy
                (Print_listReverseAndMapAndIntersperseAndFlatten
                    (fun (tailPatternElementPrintWithCommentsBefore: Print_Print) ->
                        Print_followedBy (Print_withIndentIncreasedBy 3L tailPatternElementPrintWithCommentsBefore) ElmSyntaxPrintDefunctionalized_printExactlyColonColonSpace
                    )
                    (Print_spaceOrLinebreakIndented lineSpread)
                    tailPatternPrintsAndCommentsBeforeReverse
                )
                (Print_spaceOrLinebreakIndented lineSpread)
            )
        )
        headPrint

and ElmSyntaxPrintDefunctionalized_patternList (syntaxComments: List<ElmSyntaxNode_Node<StringRope>>) (syntaxList: Generated_Elements_FullRange<List<ElmSyntaxNode_Node<ElmSyntaxPattern_Pattern>>, ElmSyntaxRange_Range>) : Print_Print =
    match syntaxList.Elements with
    | [] ->
        Print_followedBy
            (match ElmSyntaxPrintDefunctionalized_commentsInRange syntaxList.FullRange syntaxComments with
             | [] ->
                ElmSyntaxPrintDefunctionalized_printExactlySquareClosing

             | comment0 :: comment1Up ->
                let commentsCollapsed: Generated_LineSpread_Print<Print_LineSpread, Print_Print> =
                    ElmSyntaxPrintDefunctionalized_collapsibleComments (List_cons comment0 comment1Up)
                
                Print_followedBy ElmSyntaxPrintDefunctionalized_printExactlySquareClosing (Print_followedBy (Print_emptyOrLinebreakIndented commentsCollapsed.LineSpread) (Print_withIndentIncreasedBy 1L commentsCollapsed.Print))
            )
            ElmSyntaxPrintDefunctionalized_printExactlySquareOpening

    | element0 :: element1Up ->
        let elementPrintsWithCommentsBefore: Generated_EndLocation_Reverse<ElmSyntaxRange_Location, List<Print_Print>> =
            List_foldl
                (fun (elementNode: ElmSyntaxNode_Node<ElmSyntaxPattern_Pattern>) (soFar: Generated_EndLocation_Reverse<ElmSyntaxRange_Location, List<Print_Print>>) ->
                    let elementPrint: Print_Print =
                        ElmSyntaxPrintDefunctionalized_patternNotParenthesized syntaxComments elementNode
                    
                    let (ElmSyntaxNode_Node(elementRange, _): ElmSyntaxNode_Node<ElmSyntaxPattern_Pattern>) =
                        elementNode
                    
                    { EndLocation = elementRange.End
                    ; Reverse =
                        List_cons
                            (match
                                ElmSyntaxPrintDefunctionalized_commentsInRange
                                    { End = elementRange.Start
                                    ; Start = soFar.EndLocation
                                    }
                                    syntaxComments
                             with
                             | [] ->
                                elementPrint

                             | comment0 :: comment1Up ->
                                let commentsBeforeElement: Generated_LineSpread_Print<Print_LineSpread, Print_Print> =
                                    ElmSyntaxPrintDefunctionalized_collapsibleComments (List_cons comment0 comment1Up)
                                
                                Print_followedBy
                                    elementPrint
                                    (Print_followedBy
                                        (Print_spaceOrLinebreakIndented
                                            (Print_lineSpreadMergeWith
                                                (fun (_: unit) ->
                                                    Print_lineSpread elementPrint
                                                )
                                                commentsBeforeElement.LineSpread
                                            )
                                        )
                                        commentsBeforeElement.Print
                                    )
                            )
                            soFar.Reverse
                    }
                )
                { EndLocation = syntaxList.FullRange.Start
                ; Reverse = []
                }
                (List_cons element0 element1Up)
        
        let commentsAfterElements: ValueOption<Generated_LineSpread_Print<Print_LineSpread, Print_Print>> =
            match
                ElmSyntaxPrintDefunctionalized_commentsInRange
                    { End = syntaxList.FullRange.End
                    ; Start = elementPrintsWithCommentsBefore.EndLocation
                    }
                    syntaxComments
            with
            | [] ->
                ValueNone

            | comment0 :: comment1Up ->
                ValueSome (ElmSyntaxPrintDefunctionalized_collapsibleComments (List_cons comment0 comment1Up))
        
        let lineSpread: Print_LineSpread =
            Print_lineSpreadMergeWith
                (fun (_: unit) ->
                    ElmSyntaxPrintDefunctionalized_maybeLineSpread
                        (fun (generated_record: Generated_LineSpread_Print<Print_LineSpread, Print_Print>) ->
                            generated_record.LineSpread
                        )
                        commentsAfterElements
                )
                (Print_lineSpreadListMapAndCombine Print_lineSpread elementPrintsWithCommentsBefore.Reverse)
        
        Print_followedBy
            ElmSyntaxPrintDefunctionalized_printExactlySquareClosing
            (Print_followedBy
                (match commentsAfterElements with
                 | ValueNone ->
                    Print_spaceOrLinebreakIndented lineSpread

                 | ValueSome(commentsCollapsibleAfterElements) ->
                    Print_followedBy (Print_spaceOrLinebreakIndented lineSpread) (Print_withIndentIncreasedBy 2L (Print_followedBy commentsCollapsibleAfterElements.Print (Print_spaceOrLinebreakIndented lineSpread)))
                )
                (Print_followedBy
                    (Print_listReverseAndMapAndIntersperseAndFlatten
                        (fun (elementPrintWithCommentsBefore: Print_Print) ->
                            Print_withIndentIncreasedBy 2L elementPrintWithCommentsBefore
                        )
                        (Print_followedBy ElmSyntaxPrintDefunctionalized_printExactlyCommaSpace (Print_emptyOrLinebreakIndented lineSpread))
                        elementPrintsWithCommentsBefore.Reverse
                    )
                    ElmSyntaxPrintDefunctionalized_printExactlySquareOpeningSpace
                )
            )

let rec ElmSyntaxPrintDefunctionalized_expressionLetDeclaration (syntaxComments: List<ElmSyntaxNode_Node<StringRope>>) (letDeclaration: ElmSyntaxExpression_LetDeclaration) : Print_Print =
    match letDeclaration with
    | ElmSyntaxExpression_LetFunction(letDeclarationExpression) ->
        let implementationPrint: Print_Print =
            ElmSyntaxPrintDefunctionalized_declarationExpressionImplementation syntaxComments (ElmSyntaxNode_value letDeclarationExpression.Declaration)
        
        match letDeclarationExpression.Signature with
        | ValueNone ->
            implementationPrint

        | ValueSome(ElmSyntaxNode_Node(signatureRange, signature)) ->
            let commentsBetweenSignatureAndImplementationName: List<StringRope> =
                ElmSyntaxPrintDefunctionalized_commentsInRange
                    { End = (ElmSyntaxNode_range letDeclarationExpression.Declaration).Start
                    ; Start = signatureRange.End
                    }
                    syntaxComments
            
            Print_followedBy
                implementationPrint
                (Print_followedBy
                    (match commentsBetweenSignatureAndImplementationName with
                     | [] ->
                        Print_linebreakIndented

                     | comment0 :: comment1Up ->
                        Print_followedBy Print_linebreakIndented (Print_followedBy (ElmSyntaxPrintDefunctionalized_comments (List_cons comment0 comment1Up)) Print_linebreakIndented)
                    )
                    (ElmSyntaxPrintDefunctionalized_declarationSignature syntaxComments signature)
                )

    | ElmSyntaxExpression_LetDestructuring(destructuringPattern, destructuredExpression) ->
        let destructuringPatternPrint: Print_Print =
            ElmSyntaxPrintDefunctionalized_patternParenthesizedIfSpaceSeparated syntaxComments destructuringPattern
        
        let destructuredExpressionPrint: Print_Print =
            ElmSyntaxPrintDefunctionalized_expressionNotParenthesized syntaxComments destructuredExpression
        
        let commentsBeforeDestructuredExpression: List<StringRope> =
            ElmSyntaxPrintDefunctionalized_commentsInRange
                { End = (ElmSyntaxNode_range destructuredExpression).Start
                ; Start = (ElmSyntaxNode_range destructuringPattern).End
                }
                syntaxComments
        
        Print_followedBy
            (Print_withIndentAtNextMultipleOf4
                (Print_followedBy
                    (match commentsBeforeDestructuredExpression with
                     | [] ->
                        destructuredExpressionPrint

                     | comment0 :: comment1Up ->
                        Print_followedBy destructuredExpressionPrint (Print_followedBy Print_linebreakIndented (ElmSyntaxPrintDefunctionalized_comments (List_cons comment0 comment1Up)))
                    )
                    (Print_followedBy ElmSyntaxPrintDefunctionalized_printEqualsLinebreakIndented (Print_spaceOrLinebreakIndented (Print_lineSpread destructuringPatternPrint)))
                )
            )
            destructuringPatternPrint

and ElmSyntaxPrintDefunctionalized_declarationExpressionImplementation (syntaxComments: List<ElmSyntaxNode_Node<StringRope>>) (implementation: Generated_Arguments_Expression_Name<List<ElmSyntaxNode_Node<ElmSyntaxPattern_Pattern>>, ElmSyntaxNode_Node<ElmSyntaxExpression_Expression>, ElmSyntaxNode_Node<StringRope>>) : Print_Print =
    let parameterPrintsWithCommentsBefore: Generated_EndLocation_Reverse<ElmSyntaxRange_Location, List<Print_Print>> =
        List_foldl
            (fun (parameterPattern: ElmSyntaxNode_Node<ElmSyntaxPattern_Pattern>) (soFar: Generated_EndLocation_Reverse<ElmSyntaxRange_Location, List<Print_Print>>) ->
                let parameterRange: ElmSyntaxRange_Range =
                    ElmSyntaxNode_range parameterPattern
                
                let parameterPrint: Print_Print =
                    ElmSyntaxPrintDefunctionalized_patternParenthesizedIfSpaceSeparated syntaxComments parameterPattern
                
                { EndLocation = parameterRange.End
                ; Reverse =
                    List_cons
                        (match
                            ElmSyntaxPrintDefunctionalized_commentsInRange
                                { End = parameterRange.Start
                                ; Start = soFar.EndLocation
                                }
                                syntaxComments
                         with
                         | [] ->
                            parameterPrint

                         | comment0 :: comment1Up ->
                            let commentsBefore: Generated_LineSpread_Print<Print_LineSpread, Print_Print> =
                                ElmSyntaxPrintDefunctionalized_collapsibleComments (List_cons comment0 comment1Up)
                            
                            Print_followedBy
                                parameterPrint
                                (Print_followedBy
                                    (Print_spaceOrLinebreakIndented
                                        (Print_lineSpreadMergeWith
                                            (fun (_: unit) ->
                                                Print_lineSpread parameterPrint
                                            )
                                            commentsBefore.LineSpread
                                        )
                                    )
                                    commentsBefore.Print
                                )
                        )
                        soFar.Reverse
                }
            )
            { EndLocation = (ElmSyntaxNode_range implementation.Name).End
            ; Reverse = []
            }
            implementation.Arguments
    
    let parametersLineSpread: Print_LineSpread =
        Print_lineSpreadListMapAndCombine Print_lineSpread parameterPrintsWithCommentsBefore.Reverse
    
    let expressionPrint: Print_Print =
        ElmSyntaxPrintDefunctionalized_expressionNotParenthesized syntaxComments implementation.Expression
    
    let commentsBetweenParametersAndResult: List<StringRope> =
        ElmSyntaxPrintDefunctionalized_commentsInRange
            { End = (ElmSyntaxNode_range implementation.Expression).Start
            ; Start = parameterPrintsWithCommentsBefore.EndLocation
            }
            syntaxComments
    
    Print_followedBy
        (Print_withIndentAtNextMultipleOf4
            (Print_followedBy
                (Print_followedBy
                    (match commentsBetweenParametersAndResult with
                     | [] ->
                        expressionPrint

                     | comment0 :: comment1Up ->
                        Print_followedBy expressionPrint (Print_followedBy Print_linebreakIndented (ElmSyntaxPrintDefunctionalized_comments (List_cons comment0 comment1Up)))
                    )
                    Print_linebreakIndented
                )
                (Print_followedBy
                    ElmSyntaxPrintDefunctionalized_printExactlyEquals
                    (Print_followedBy
                        (Print_spaceOrLinebreakIndented parametersLineSpread)
                        (Print_listReverseAndMapAndFlatten
                            (fun (parameterPrintWithCommentsBefore: Print_Print) ->
                                Print_followedBy parameterPrintWithCommentsBefore (Print_spaceOrLinebreakIndented parametersLineSpread)
                            )
                            parameterPrintsWithCommentsBefore.Reverse
                        )
                    )
                )
            )
        )
        (Print_exactly (ElmSyntaxNode_value implementation.Name))

and ElmSyntaxPrintDefunctionalized_expressionNotParenthesized (syntaxComments: List<ElmSyntaxNode_Node<StringRope>>) (ElmSyntaxNode_Node(fullRange, syntaxExpression): ElmSyntaxNode_Node<ElmSyntaxExpression_Expression>) : Print_Print =
    match syntaxExpression with
    | ElmSyntaxExpression_UnitExpr ->
        ElmSyntaxPrintDefunctionalized_printExactlyParensOpeningParensClosed

    | ElmSyntaxExpression_Application(application) ->
        match application with
        | [] ->
            Print_empty

        | [ notAppliedAfterAll ] ->
            ElmSyntaxPrintDefunctionalized_expressionNotParenthesized syntaxComments notAppliedAfterAll

        | applied :: (argument0 :: argument1Up) ->
            ElmSyntaxPrintDefunctionalized_expressionCall
                syntaxComments
                { Applied = applied
                ; Argument0 = argument0
                ; Argument1Up = argument1Up
                ; FullRange = fullRange
                }

    | ElmSyntaxExpression_OperatorApplication(operator, _, left, right) ->
        ElmSyntaxPrintDefunctionalized_expressionOperation
            syntaxComments
            { FullRange = fullRange
            ; Left = left
            ; Operator = operator
            ; Right = right
            }

    | ElmSyntaxExpression_FunctionOrValue(qualification, unqualified) ->
        Print_exactly
            (ElmSyntaxPrintDefunctionalized_qualifiedReference
                { Qualification = qualification
                ; Unqualified = unqualified
                }
            )

    | ElmSyntaxExpression_IfBlock(condition, onTrue, onFalse) ->
        ElmSyntaxPrintDefunctionalized_expressionIfThenElse
            syntaxComments
            { Condition = condition
            ; ConditionLineSpreadMinimum = Print_SingleLine
            ; FullRange = fullRange
            ; OnFalse = onFalse
            ; OnTrue = onTrue
            }

    | ElmSyntaxExpression_PrefixOperator(operatorSymbol) ->
        Print_exactly (String_append (StringRopeOne "(") (String_append operatorSymbol (StringRopeOne ")")))

    | ElmSyntaxExpression_Operator(operatorSymbol) ->
        Print_exactly operatorSymbol

    | ElmSyntaxExpression_Integer(int_) ->
        Print_exactly (ElmSyntaxPrintDefunctionalized_intLiteral int_)

    | ElmSyntaxExpression_Hex(int_) ->
        Print_exactly (ElmSyntaxPrintDefunctionalized_hexLiteral int_)

    | ElmSyntaxExpression_Floatable(float_) ->
        Print_exactly (ElmSyntaxPrintDefunctionalized_floatLiteral float_)

    | ElmSyntaxExpression_Negation(negated) ->
        ElmSyntaxPrintDefunctionalized_printExpressionNegation syntaxComments negated

    | ElmSyntaxExpression_Literal(string_) ->
        ElmSyntaxPrintDefunctionalized_stringLiteral (ElmSyntaxNode_Node (struct( fullRange, string_ )))

    | ElmSyntaxExpression_CharLiteral(char_) ->
        Print_exactly (ElmSyntaxPrintDefunctionalized_charLiteral char_)

    | ElmSyntaxExpression_TupledExpression(parts) ->
        match parts with
        | [] ->
            ElmSyntaxPrintDefunctionalized_printExactlyParensOpeningParensClosed

        | [ inParens ] ->
            let commentsBeforeInParens: List<StringRope> =
                ElmSyntaxPrintDefunctionalized_commentsInRange
                    { End = (ElmSyntaxNode_range inParens).Start
                    ; Start = fullRange.Start
                    }
                    syntaxComments
            
            let commentsAfterInParens: List<StringRope> =
                ElmSyntaxPrintDefunctionalized_commentsInRange
                    { End = fullRange.End
                    ; Start = (ElmSyntaxNode_range inParens).End
                    }
                    syntaxComments
            
            match (struct( commentsBeforeInParens, commentsAfterInParens )) with
            | (struct( [], [] )) ->
                ElmSyntaxPrintDefunctionalized_expressionNotParenthesized syntaxComments inParens

            | _ ->
                ElmSyntaxPrintDefunctionalized_parenthesized
