let ElmSyntaxPrintDefunctionalized_declarations (context: Generated_Comments_PortDocumentationComments_PreviousEnd<List<ElmSyntaxNode_Node<StringRope>>, List<ElmSyntaxNode_Node<StringRope>>, ElmSyntaxRange_Location>) (syntaxDeclarations: List<ElmSyntaxNode_Node<ElmSyntaxDeclaration_Declaration>>) : Print_Print =
    match syntaxDeclarations with
    | [] ->
        Print_empty

    | ElmSyntaxNode_Node(declaration0Range, declaration0) :: declarations1Up ->
        Print_followedBy
            (List_foldl
                (fun (ElmSyntaxNode_Node(declarationRange, syntaxDeclaration): ElmSyntaxNode_Node<ElmSyntaxDeclaration_Declaration>) (soFar: Generated_PreviousRange_Print<Generated_End_Start<ElmSyntaxRange_Location, ElmSyntaxRange_Location>, Print_Print>) ->
                    let maybeDeclarationPortDocumentationComment: ValueOption<ElmSyntaxNode_Node<StringRope>> =
                        match syntaxDeclaration with
                        | ElmSyntaxDeclaration_PortDeclaration(_) ->
                            ElmSyntaxPrintDefunctionalized_firstCommentInRange
                                { End = declarationRange.Start
                                ; Start = soFar.PreviousRange.End
                                }
                                context.PortDocumentationComments

                        | ElmSyntaxDeclaration_FunctionDeclaration(_) ->
                            ValueNone

                        | ElmSyntaxDeclaration_AliasDeclaration(_) ->
                            ValueNone

                        | ElmSyntaxDeclaration_CustomTypeDeclaration(_) ->
                            ValueNone

                        | ElmSyntaxDeclaration_InfixDeclaration(_) ->
                            ValueNone

                        | ElmSyntaxDeclaration_Destructuring(_, _) ->
                            ValueNone
                    
                    { PreviousRange = declarationRange
                    ; Print =
                        Print_followedBy
                            (match
                                ElmSyntaxPrintDefunctionalized_commentsInRange
                                    { End = declarationRange.Start
                                    ; Start = soFar.PreviousRange.End
                                    }
                                    context.Comments
                             with
                             | comment0 :: comment1Up ->
                                Print_followedBy
                                    (ElmSyntaxPrintDefunctionalized_declaration
                                        { Comments = ElmSyntaxPrintDefunctionalized_commentNodesInRange declarationRange context.Comments
                                        ; PortDocumentationComment = maybeDeclarationPortDocumentationComment
                                        }
                                        syntaxDeclaration
                                    )
                                    (Print_followedBy
                                        (ElmSyntaxPrintDefunctionalized_moduleLevelCommentsBeforeDeclaration
                                            { Comment0 = comment0
                                            ; Comment1Up = comment1Up
                                            }
                                        )
                                        ElmSyntaxPrintDefunctionalized_printLinebreakLinebreakLinebreak
                                    )

                             | [] ->
                                ElmSyntaxPrintDefunctionalized_linebreaksFollowedByDeclaration
                                    { Comments = ElmSyntaxPrintDefunctionalized_commentNodesInRange declarationRange context.Comments
                                    ; PortDocumentationComment = maybeDeclarationPortDocumentationComment
                                    }
                                    syntaxDeclaration
                            )
                            soFar.Print
                    }
                )
                { PreviousRange = declaration0Range
                ; Print = Print_empty
                }
                declarations1Up
            ).Print
            (ElmSyntaxPrintDefunctionalized_declaration
                { Comments = context.Comments
                ; PortDocumentationComment =
                    match declaration0 with
                    | ElmSyntaxDeclaration_PortDeclaration(_) ->
                        ElmSyntaxPrintDefunctionalized_firstCommentInRange
                            { End = declaration0Range.Start
                            ; Start = context.PreviousEnd
                            }
                            context.PortDocumentationComments

                    | ElmSyntaxDeclaration_FunctionDeclaration(_) ->
                        ValueNone

                    | ElmSyntaxDeclaration_AliasDeclaration(_) ->
                        ValueNone

                    | ElmSyntaxDeclaration_CustomTypeDeclaration(_) ->
                        ValueNone

                    | ElmSyntaxDeclaration_InfixDeclaration(_) ->
                        ValueNone

                    | ElmSyntaxDeclaration_Destructuring(_, _) ->
                        ValueNone
                }
                declaration0
            )

let ElmSyntaxPrintDefunctionalized_module_ (syntaxModule: ElmSyntaxFile_File) : Print_Print =
    let maybeModuleDocumentation: ValueOption<ElmSyntaxNode_Node<StringRope>> =
        ElmSyntaxPrintDefunctionalized_moduleDocumentation syntaxModule
    
    let maybeModuleDocumentationParsed: ValueOption<Generated_RawAfterAtDocsLines_WhileAtDocsLines<StringRope, List<Generated_AtDocsLine_RawBefore<List<StringRope>, StringRope>>>> =
        match maybeModuleDocumentation with
        | ValueNone ->
            ValueNone

        | ValueSome(ElmSyntaxNode_Node(_, syntaxModuleDocumentation)) ->
            ValueSome (ElmSyntaxPrintDefunctionalized_moduleDocumentationParse syntaxModuleDocumentation)
    
    let lastSyntaxLocationBeforeDeclarations: ElmSyntaxRange_Location =
        match syntaxModule.Imports with
        | ElmSyntaxNode_Node(firstImportRange, _) :: _ ->
            firstImportRange.End

        | [] ->
            (ElmSyntaxNode_range syntaxModule.ModuleDefinition).End
    
    let commentsAndPortDocumentationComments: Generated_PortDocumentationComments_RemainingComments<List<ElmSyntaxNode_Node<StringRope>>, List<ElmSyntaxNode_Node<StringRope>>> =
        ElmSyntaxPrintDefunctionalized_splitOffPortDocumentationComments
            (match maybeModuleDocumentation with
             | ValueNone ->
                syntaxModule.Comments

             | ValueSome(syntaxModuleDocumentation) ->
                List.filter
                    (fun (c: ElmSyntaxNode_Node<StringRope>) ->
                        Basics_neq c syntaxModuleDocumentation
                    )
                    syntaxModule.Comments
            )
    
    let commentsBeforeDeclarations: List<StringRope> =
        match syntaxModule.Declarations with
        | [] ->
            []

        | ElmSyntaxNode_Node(declaration0Range, _) :: _ ->
            ElmSyntaxPrintDefunctionalized_commentsInRange
                { End = declaration0Range.Start
                ; Start = lastSyntaxLocationBeforeDeclarations
                }
                commentsAndPortDocumentationComments.RemainingComments
    
    let atDocsLines: List<List<StringRope>> =
        match maybeModuleDocumentationParsed with
        | ValueNone ->
            []

        | ValueSome(moduleDocumentationParsed) ->
            List.map
                (fun (generated_record: Generated_AtDocsLine_RawBefore<List<StringRope>, StringRope>) ->
                    generated_record.AtDocsLine
                )
                moduleDocumentationParsed.WhileAtDocsLines
    
    Print_followedBy
        (match syntaxModule.Declarations with
         | [] ->
            Print_empty

         | declaration0 :: declaration1Up ->
            match ElmSyntaxPrintDefunctionalized_commentsAfter (ElmSyntaxNode_range (ElmSyntaxPrintDefunctionalized_listFilledLast declaration0 declaration1Up)).End commentsAndPortDocumentationComments.RemainingComments with
            | [] ->
                Print_empty

            | comment0 :: comment1Up ->
                Print_followedBy (ElmSyntaxPrintDefunctionalized_moduleLevelComments (List_cons comment0 comment1Up)) ElmSyntaxPrintDefunctionalized_printLinebreakLinebreakLinebreak
        )
        (Print_followedBy
            Print_linebreak
            (Print_followedBy
                (ElmSyntaxPrintDefunctionalized_declarations
                    { Comments = commentsAndPortDocumentationComments.RemainingComments
                    ; PortDocumentationComments = commentsAndPortDocumentationComments.PortDocumentationComments
                    ; PreviousEnd = lastSyntaxLocationBeforeDeclarations
                    }
                    syntaxModule.Declarations
                )
                (Print_followedBy
                    (match commentsBeforeDeclarations with
                     | [] ->
                        Print_empty

                     | comment0 :: comment1Up ->
                        ElmSyntaxPrintDefunctionalized_moduleLevelCommentsBeforeDeclaration
                            { Comment0 = comment0
                            ; Comment1Up = comment1Up
                            }
                    )
                    (Print_followedBy
                        Print_linebreak
                        (Print_followedBy
                            (match syntaxModule.Imports with
                             | [] ->
                                match maybeModuleDocumentation with
                                | ValueNone ->
                                    ElmSyntaxPrintDefunctionalized_printLinebreakLinebreak

                                | ValueSome(_) ->
                                    match commentsBeforeDeclarations with
                                    | [] ->
                                        ElmSyntaxPrintDefunctionalized_printLinebreakLinebreak

                                    | _ :: _ ->
                                        Print_empty

                             | ElmSyntaxNode_Node(import0Range, import0) :: import1Up ->
                                Print_followedBy
                                    ElmSyntaxPrintDefunctionalized_printLinebreakLinebreak
                                    (Print_followedBy
                                        (ElmSyntaxPrintDefunctionalized_imports commentsAndPortDocumentationComments.RemainingComments (List_cons (ElmSyntaxNode_Node (struct( import0Range, import0 ))) import1Up))
                                        (Print_followedBy
                                            Print_linebreak
                                            (match
                                                ElmSyntaxPrintDefunctionalized_commentsInRange
                                                    { End = import0Range.Start
                                                    ; Start = (ElmSyntaxNode_range syntaxModule.ModuleDefinition).End
                                                    }
                                                    commentsAndPortDocumentationComments.RemainingComments
                                             with
                                             | [] ->
                                                Print_linebreak

                                             | comment0 :: comment1Up ->
                                                Print_followedBy (ElmSyntaxPrintDefunctionalized_moduleLevelComments (List_cons comment0 comment1Up)) ElmSyntaxPrintDefunctionalized_printLinebreakLinebreak
                                            )
                                        )
                                    )
                            )
                            (Print_followedBy
                                (match maybeModuleDocumentationParsed with
                                 | ValueNone ->
                                    Print_empty

                                 | ValueSome(moduleDocumentationParsed) ->
                                    Print_followedBy (ElmSyntaxPrintDefunctionalized_printModuleDocumentation moduleDocumentationParsed) ElmSyntaxPrintDefunctionalized_printLinebreakLinebreak
                                )
                                (ElmSyntaxPrintDefunctionalized_moduleHeader
                                    { AtDocsLines = atDocsLines
                                    ; Comments = commentsAndPortDocumentationComments.RemainingComments
                                    }
                                    (ElmSyntaxNode_value syntaxModule.ModuleDefinition)
                                )
                            )
                        )
                    )
                )
            )
        )

