let ElmParserDeclarations_declarationWithDocumentation: ParserFast_Parser<ParserWithComments_WithComments<ElmSyntaxNode_Node<ElmSyntaxDeclaration_Declaration>>> =
    ParserFast_validate
        (fun (result: Generated_Comments_Syntax<Rope_Rope<ElmSyntaxNode_Node<ElmSyntaxDocumentation_Documentation>>, ElmSyntaxNode_Node<ElmSyntaxDeclaration_Declaration>>) ->
            let (ElmSyntaxNode_Node(_, decl): ElmSyntaxNode_Node<ElmSyntaxDeclaration_Declaration>) =
                result.Syntax
            
            match decl with
            | ElmSyntaxDeclaration_FunctionDeclaration(letFunctionDeclaration) ->
                match letFunctionDeclaration.Signature with
                | ValueNone ->
                    true

                | ValueSome(ElmSyntaxNode_Node(_, signature)) ->
                    let (ElmSyntaxNode_Node(_, implementation): ElmSyntaxNode_Node<ElmSyntaxExpression_FunctionImplementation>) =
                        letFunctionDeclaration.Declaration
                    
                    let (ElmSyntaxNode_Node(_, implementationName): ElmSyntaxNode_Node<StringRope>) =
                        implementation.Name
                    
                    let (ElmSyntaxNode_Node(_, signatureName): ElmSyntaxNode_Node<StringRope>) =
                        signature.Name
                    
                    Basics_eq implementationName signatureName

            | _ ->
                true
        )
        (StringRopeOne "Expected to find the same name for declaration and signature")
        (ParserFast_map2
            (fun (documentation: ElmSyntaxNode_Node<ElmSyntaxDocumentation_Documentation>) (afterDocumentation: Generated_Comments_Syntax<ValueOption<Rope_RopeFilled<ElmSyntaxNode_Node<StringRope>>>, ElmParserDeclarations_DeclarationAfterDocumentation>) ->
                let start: ElmSyntaxRange_Location =
                    (ElmSyntaxNode_range documentation).Start
                
                match afterDocumentation.Syntax with
                | ElmParserDeclarations_FunctionDeclarationAfterDocumentation(functionDeclarationAfterDocumentation) ->
                    match functionDeclarationAfterDocumentation.Signature with
                    | ValueSome(signature) ->
                        let (ElmSyntaxNode_Node(implementationNameRange, _): ElmSyntaxNode_Node<StringRope>) =
                            signature.ImplementationName
                        
                        let (ElmSyntaxNode_Node(expressionRange, _): ElmSyntaxNode_Node<ElmSyntaxExpression_Expression>) =
                            functionDeclarationAfterDocumentation.Expression
                        
                        { Comments = afterDocumentation.Comments
                        ; Syntax =
                            ElmSyntaxNode_Node
                                (struct(
                                  { End = expressionRange.End
                                  ; Start = start
                                  }
                                , ElmSyntaxDeclaration_FunctionDeclaration
                                    { Declaration =
                                        ElmSyntaxNode_Node
                                            (struct(
                                              { End = expressionRange.End
                                              ; Start = implementationNameRange.Start
                                              }
                                            , { Arguments = functionDeclarationAfterDocumentation.Arguments
                                              ; Expression = functionDeclarationAfterDocumentation.Expression
                                              ; Name = signature.ImplementationName
                                              }
                                            ))
                                    ; Documentation = ValueSome documentation
                                    ; Signature =
                                        ValueSome
                                            (ElmSyntaxNode_combine
                                                (fun (generated_Name: ElmSyntaxNode_Node<StringRope>) (generated_TypeAnnotation: ElmSyntaxNode_Node<ElmSyntaxTypeAnnotation_TypeAnnotation>) ->
                                                    { Name = generated_Name
                                                    ; TypeAnnotation = generated_TypeAnnotation
                                                    }
                                                )
                                                functionDeclarationAfterDocumentation.StartName
                                                signature.TypeAnnotation
                                            )
                                    }
                                ))
                        }

                    | ValueNone ->
                        let (ElmSyntaxNode_Node(startNameRange, _): ElmSyntaxNode_Node<StringRope>) =
                            functionDeclarationAfterDocumentation.StartName
                        
                        let (ElmSyntaxNode_Node(expressionRange, _): ElmSyntaxNode_Node<ElmSyntaxExpression_Expression>) =
                            functionDeclarationAfterDocumentation.Expression
                        
                        { Comments = afterDocumentation.Comments
                        ; Syntax =
                            ElmSyntaxNode_Node
                                (struct(
                                  { End = expressionRange.End
                                  ; Start = start
                                  }
                                , ElmSyntaxDeclaration_FunctionDeclaration
                                    { Declaration =
                                        ElmSyntaxNode_Node
                                            (struct(
                                              { End = expressionRange.End
                                              ; Start = startNameRange.Start
                                              }
                                            , { Arguments = functionDeclarationAfterDocumentation.Arguments
                                              ; Expression = functionDeclarationAfterDocumentation.Expression
                                              ; Name = functionDeclarationAfterDocumentation.StartName
                                              }
                                            ))
                                    ; Documentation = ValueSome documentation
                                    ; Signature = ValueNone
                                    }
                                ))
                        }

                | ElmParserDeclarations_TypeDeclarationAfterDocumentation(typeDeclarationAfterDocumentation) ->
                    let end_: ElmSyntaxRange_Location =
                        match typeDeclarationAfterDocumentation.TailVariantsReverse with
                        | ElmSyntaxNode_Node(range, _) :: _ ->
                            range.End

                        | [] ->
                            let (ElmSyntaxNode_Node(headVariantRange, _): ElmSyntaxNode_Node<ElmSyntaxType_ValueConstructor>) =
                                typeDeclarationAfterDocumentation.HeadVariant
                            
                            headVariantRange.End
                    
                    { Comments = afterDocumentation.Comments
                    ; Syntax =
                        ElmSyntaxNode_Node
                            (struct(
                              { End = end_
                              ; Start = start
                              }
                            , ElmSyntaxDeclaration_CustomTypeDeclaration
                                { Constructors = List_cons typeDeclarationAfterDocumentation.HeadVariant (List.rev typeDeclarationAfterDocumentation.TailVariantsReverse)
                                ; Documentation = ValueSome documentation
                                ; Generics = typeDeclarationAfterDocumentation.Parameters
                                ; Name = typeDeclarationAfterDocumentation.Name
                                }
                            ))
                    }

                | ElmParserDeclarations_TypeAliasDeclarationAfterDocumentation(typeAliasDeclarationAfterDocumentation) ->
                    let (ElmSyntaxNode_Node(typeAnnotationRange, _): ElmSyntaxNode_Node<ElmSyntaxTypeAnnotation_TypeAnnotation>) =
                        typeAliasDeclarationAfterDocumentation.TypeAnnotation
                    
                    { Comments = afterDocumentation.Comments
                    ; Syntax =
                        ElmSyntaxNode_Node
                            (struct(
                              { End = typeAnnotationRange.End
                              ; Start = start
                              }
                            , ElmSyntaxDeclaration_AliasDeclaration
                                { Documentation = ValueSome documentation
                                ; Generics = typeAliasDeclarationAfterDocumentation.Parameters
                                ; Name = typeAliasDeclarationAfterDocumentation.Name
                                ; TypeAnnotation = typeAliasDeclarationAfterDocumentation.TypeAnnotation
                                }
                            ))
                    }

                | ElmParserDeclarations_PortDeclarationAfterDocumentation(portDeclarationAfterName) ->
                    let (ElmSyntaxNode_Node(typeAnnotationRange, _): ElmSyntaxNode_Node<ElmSyntaxTypeAnnotation_TypeAnnotation>) =
                        portDeclarationAfterName.TypeAnnotation
                    
                    { Comments = Rope_filledPrependTo afterDocumentation.Comments (Rope_one documentation)
                    ; Syntax =
                        ElmSyntaxNode_Node
                            (struct(
                              { End = typeAnnotationRange.End
                              ; Start = portDeclarationAfterName.StartLocation
                              }
                            , ElmSyntaxDeclaration_PortDeclaration
                                { Name = portDeclarationAfterName.Name
                                ; TypeAnnotation = portDeclarationAfterName.TypeAnnotation
                                }
                            ))
                    }
            )
            ElmParserComments_declarationDocumentation
            (ElmParserLayout_layoutStrictFollowedByWithComments (ParserFast_oneOf3 ElmParserDeclarations_functionAfterDocumentation ElmParserDeclarations_typeOrTypeAliasDefinitionAfterDocumentation ElmParserDeclarations_portDeclarationAfterDocumentation))
        )

