                    (fun (commentsBeforePipe: ElmSyntaxParserLenient_Rope<ElmSyntaxNode_Node<StringRope>>) (commentsWithExtraPipe: ElmSyntaxParserLenient_Rope<ElmSyntaxNode_Node<StringRope>>) (variantResult: Generated_Comments_Syntax<ValueOption<ElmSyntaxParserLenient_RopeFilled<ElmSyntaxNode_Node<StringRope>>>, ElmSyntaxNode_Node<ElmSyntaxType_ValueConstructor>>) ->
                        { Comments = ElmSyntaxParserLenient_ropePrependTo variantResult.Comments (ElmSyntaxParserLenient_ropePrependTo commentsWithExtraPipe commentsBeforePipe)
                        ; Syntax = variantResult.Syntax
                        }
                    )
                    ElmSyntaxParserLenient_whitespaceAndComments
                    (ParserLenient_orSucceed (ParserLenient_symbolFollowedBy (StringRopeOne "|") ElmSyntaxParserLenient_whitespaceAndComments) ElmSyntaxParserLenient_ropeEmpty)
                    ElmSyntaxParserLenient_variantDeclarationFollowedByWhitespaceAndComments
                )
            )
        )

let ElmSyntaxParserLenient_typeOrTypeAliasDefinitionWithoutDocumentation: ElmSyntaxParserLenient_Parser<ElmSyntaxParserLenient_WithComments<ElmSyntaxNode_Node<ElmSyntaxDeclaration_Declaration>>> =
    ParserLenient_map2WithStartLocation
        (fun (start: ElmSyntaxRange_Location) (commentsAfterType: ElmSyntaxParserLenient_Rope<ElmSyntaxNode_Node<StringRope>>) (afterStart: Generated_Comments_Syntax<ValueOption<ElmSyntaxParserLenient_RopeFilled<ElmSyntaxNode_Node<StringRope>>>, ElmSyntaxParserLenient_TypeOrTypeAliasDeclarationWithoutDocumentation>) ->
            let allComments: ElmSyntaxParserLenient_Comments =
                ElmSyntaxParserLenient_ropePrependTo afterStart.Comments commentsAfterType
            
            match afterStart.Syntax with
            | ElmSyntaxParserLenient_TypeDeclarationWithoutDocumentation(typeDeclarationAfterDocumentation) ->
                let end_: ElmSyntaxRange_Location =
                    match typeDeclarationAfterDocumentation.TailVariantsReverse with
                    | ElmSyntaxNode_Node(range, _) :: _ ->
                        range.End

                    | [] ->
                        let (ElmSyntaxNode_Node(headVariantRange, _): ElmSyntaxNode_Node<ElmSyntaxType_ValueConstructor>) =
                            typeDeclarationAfterDocumentation.HeadVariant
                        
                        headVariantRange.End
                
                { Comments = allComments
                ; Syntax =
                    ElmSyntaxNode_Node
                        (struct(
                          { End = end_
                          ; Start = start
                          }
                        , ElmSyntaxDeclaration_CustomTypeDeclaration
                            { Constructors = List_cons typeDeclarationAfterDocumentation.HeadVariant (List.rev typeDeclarationAfterDocumentation.TailVariantsReverse)
                            ; Documentation = ValueNone
                            ; Generics = typeDeclarationAfterDocumentation.Parameters
                            ; Name = typeDeclarationAfterDocumentation.Name
                            }
                        ))
                }

            | ElmSyntaxParserLenient_TypeAliasDeclarationWithoutDocumentation(typeAliasDeclarationAfterDocumentation) ->
                let (ElmSyntaxNode_Node(typeAnnotationRange, _): ElmSyntaxNode_Node<ElmSyntaxTypeAnnotation_TypeAnnotation>) =
                    typeAliasDeclarationAfterDocumentation.TypeAnnotation
                
                { Comments = allComments
                ; Syntax =
                    ElmSyntaxNode_Node
                        (struct(
                          { End = typeAnnotationRange.End
                          ; Start = start
                          }
                        , ElmSyntaxDeclaration_AliasDeclaration
                            { Documentation = ValueNone
                            ; Generics = typeAliasDeclarationAfterDocumentation.Parameters
                            ; Name = typeAliasDeclarationAfterDocumentation.Name
                            ; TypeAnnotation = typeAliasDeclarationAfterDocumentation.TypeAnnotation
                            }
                        ))
                }
        )
        (ParserLenient_keywordFollowedBy (StringRopeOne "type") ElmSyntaxParserLenient_whitespaceAndComments)
        (ParserLenient_oneOf2 ElmSyntaxParserLenient_typeAliasDefinitionWithoutDocumentationAfterTypePrefix ElmSyntaxParserLenient_choiceTypeDefinitionWithoutDocumentationAfterTypePrefix)

let ElmSyntaxParserLenient_declaration: ElmSyntaxParserLenient_Parser<Generated_Comments_Syntax<ElmSyntaxParserLenient_Comments, ElmSyntaxNode_Node<ElmSyntaxDeclaration_Declaration>>> =
    ParserLenient_oneOf5 ElmSyntaxParserLenient_functionDeclarationWithoutDocumentation ElmSyntaxParserLenient_declarationWithDocumentation ElmSyntaxParserLenient_typeOrTypeAliasDefinitionWithoutDocumentation ElmSyntaxParserLenient_portDeclarationWithoutDocumentation ElmSyntaxParserLenient_infixDeclaration

let ElmSyntaxParserLenient_declarations: ElmSyntaxParserLenient_Parser<Generated_Comments_Syntax<ElmSyntaxParserLenient_Comments, List<ElmSyntaxNode_Node<ElmSyntaxDeclaration_Declaration>>>> =
    ElmSyntaxParserLenient_manyWithComments
        (ElmSyntaxParserLenient_topIndentedFollowedBy
            (ParserLenient_map2
                (fun (declarationParsed: Generated_Comments_Syntax<ValueOption<ElmSyntaxParserLenient_RopeFilled<ElmSyntaxNode_Node<StringRope>>>, ElmSyntaxNode_Node<ElmSyntaxDeclaration_Declaration>>) (commentsAfter: ElmSyntaxParserLenient_Rope<ElmSyntaxNode_Node<StringRope>>) ->
                    { Comments = ElmSyntaxParserLenient_ropePrependTo commentsAfter declarationParsed.Comments
                    ; Syntax = declarationParsed.Syntax
                    }
                )
                ElmSyntaxParserLenient_declaration
                ElmSyntaxParserLenient_whitespaceAndComments
            )
        )

let ElmSyntaxParserLenient_module_: ElmSyntaxParserLenient_Parser<ElmSyntaxFile_File> =
    ParserLenient_map4
        (fun (moduleHeaderResult: Generated_Comments_Syntax<ValueOption<ElmSyntaxParserLenient_RopeFilled<ElmSyntaxNode_Node<StringRope>>>, ElmSyntaxNode_Node<ElmSyntaxModule_Module>>) (moduleComments: ElmSyntaxParserLenient_Rope<ElmSyntaxNode_Node<StringRope>>) (importsResult: Generated_Comments_Syntax<ValueOption<ElmSyntaxParserLenient_RopeFilled<ElmSyntaxNode_Node<StringRope>>>, List<ElmSyntaxNode_Node<ElmSyntaxImport_Import>>>) (declarationsResult: Generated_Comments_Syntax<ValueOption<ElmSyntaxParserLenient_RopeFilled<ElmSyntaxNode_Node<StringRope>>>, List<Generated_Declaration_LateImports<ElmSyntaxNode_Node<ElmSyntaxDeclaration_Declaration>, List<ElmSyntaxNode_Node<ElmSyntaxImport_Import>>>>>) ->
            let moduleHeaderBasedOnExistingPorts (existingModuleHeaderInfo: ElmSyntaxModule_DefaultModuleData) : ElmSyntaxModule_Module =
                if
                    List.exists
                        (fun (declarationAndLateImports: Generated_Declaration_LateImports<ElmSyntaxNode_Node<ElmSyntaxDeclaration_Declaration>, List<ElmSyntaxNode_Node<ElmSyntaxImport_Import>>>) ->
                            ElmSyntaxParserLenient_declarationIsPort (ElmSyntaxNode_value declarationAndLateImports.Declaration)
                        )
                        declarationsResult.Syntax
                then
                    ElmSyntaxModule_PortModule existingModuleHeaderInfo

                else
                    ElmSyntaxModule_NormalModule existingModuleHeaderInfo
            
            let importStartLocation: ElmSyntaxRange_Location =
                match importsResult.Syntax with
                | ElmSyntaxNode_Node(import0Range, _) :: _ ->
                    import0Range.Start

                | [] ->
                    match declarationsResult.Syntax with
                    | declarationAndLateImports0 :: _ ->
                        (ElmSyntaxNode_range declarationAndLateImports0.Declaration).Start

                    | [] ->
                        { Column = 1L
                        ; Row = 2L
                        }
            
            { Comments = ElmSyntaxParserLenient_commentsToList (ElmSyntaxParserLenient_ropePrependTo declarationsResult.Comments (ElmSyntaxParserLenient_ropePrependTo importsResult.Comments (ElmSyntaxParserLenient_ropePrependTo moduleComments moduleHeaderResult.Comments)))
            ; Declarations =
                List.map
                    (fun (generated_record: Generated_Declaration_LateImports<ElmSyntaxNode_Node<ElmSyntaxDeclaration_Declaration>, List<ElmSyntaxNode_Node<ElmSyntaxImport_Import>>>) ->
                        generated_record.Declaration
                    )
                    declarationsResult.Syntax
            ; Imports =
                List.append
                    (List.map
                        (fun (ElmSyntaxNode_Node(_, lateImport): ElmSyntaxNode_Node<ElmSyntaxImport_Import>) ->
                            ElmSyntaxNode_Node
                                (struct(
                                  { End = importStartLocation
                                  ; Start = importStartLocation
                                  }
                                , lateImport
                                ))
                        )
                        (List.collect
                            (fun (generated_record: Generated_Declaration_LateImports<ElmSyntaxNode_Node<ElmSyntaxDeclaration_Declaration>, List<ElmSyntaxNode_Node<ElmSyntaxImport_Import>>>) ->
                                generated_record.LateImports
                            )
                            declarationsResult.Syntax
                        )
                    )
                    importsResult.Syntax
            ; ModuleDefinition =
                ElmSyntaxNode_map
                    (fun (syntaxModuleHeader: ElmSyntaxModule_Module) ->
                        match syntaxModuleHeader with
                        | ElmSyntaxModule_EffectModule(effectModuleHeader) ->
                            ElmSyntaxModule_EffectModule effectModuleHeader

                        | ElmSyntaxModule_NormalModule(normalModuleHeader) ->
                            moduleHeaderBasedOnExistingPorts normalModuleHeader

                        | ElmSyntaxModule_PortModule(normalModuleHeader) ->
                            moduleHeaderBasedOnExistingPorts normalModuleHeader
                    )
                    moduleHeaderResult.Syntax
            }
        )
        (ElmSyntaxParserLenient_whitespaceAndCommentsEndsTopIndentedFollowedByWithComments ElmSyntaxParserLenient_moduleHeader)
        (ElmSyntaxParserLenient_whitespaceAndCommentsEndsTopIndentedFollowedByComments
            (ParserLenient_map2OrSucceed
                (fun (moduleDocumentation: ElmSyntaxNode_Node<ElmSyntaxDocumentation_Documentation>) (commentsAfter: ElmSyntaxParserLenient_Rope<ElmSyntaxNode_Node<ElmSyntaxDocumentation_Documentation>>) ->
                    ElmSyntaxParserLenient_ropeFilledPrependTo commentsAfter (ElmSyntaxParserLenient_ropeOne moduleDocumentation)
                )
                ElmSyntaxParserLenient_documentationComment
                ElmSyntaxParserLenient_whitespaceAndCommentsEndsTopIndented
                ElmSyntaxParserLenient_ropeEmpty
            )
        )
        (ElmSyntaxParserLenient_manyWithComments ElmSyntaxParserLenient_importFollowedByWhitespaceAndComments)
        (ElmSyntaxParserLenient_manyWithComments
            (ElmSyntaxParserLenient_topIndentedFollowedBy
                (ParserLenient_map3
                    (fun (declarationParsed: Generated_Comments_Syntax<ValueOption<ElmSyntaxParserLenient_RopeFilled<ElmSyntaxNode_Node<StringRope>>>, ElmSyntaxNode_Node<ElmSyntaxDeclaration_Declaration>>) (commentsAfter: ElmSyntaxParserLenient_Rope<ElmSyntaxNode_Node<StringRope>>) (lateImportsResult: Generated_Comments_Syntax<ValueOption<ElmSyntaxParserLenient_RopeFilled<ElmSyntaxNode_Node<StringRope>>>, List<ElmSyntaxNode_Node<ElmSyntaxImport_Import>>>) ->
                        { Comments = ElmSyntaxParserLenient_ropePrependTo lateImportsResult.Comments (ElmSyntaxParserLenient_ropePrependTo commentsAfter declarationParsed.Comments)
                        ; Syntax =
                            { Declaration = declarationParsed.Syntax
                            ; LateImports = lateImportsResult.Syntax
                            }
                        }
                    )
                    ElmSyntaxParserLenient_declaration
                    ElmSyntaxParserLenient_whitespaceAndComments
                    (ElmSyntaxParserLenient_manyWithComments ElmSyntaxParserLenient_importFollowedByWhitespaceAndComments)
                )
            )
        )

let FormatSingleModule_formatSingleModule (originalSource: StringRope) : StringRope =
    match ElmSyntaxParserLenient_run ElmSyntaxParserLenient_module_ originalSource with
    | ValueSome(syntaxModule) ->
        ElmSyntaxPrint_toString (ElmSyntaxPrint_module_ syntaxModule)

    | ValueNone ->
        originalSource


